export const WORDS = [{"id":"d1-1","day":1,"word":"résumé","meaning":"이력서","ipa":"[ˈrezəmeɪ]","kr":"레주메이","example":"She updated her résumé before applying for the job.","exampleKr":"그녀는 지원하기 전에 이력서를 업데이트했다.","roots":"re-(다시) + sumer(취하다, 라틴어 sumere) → 다시 정리해 취합한 것"},{"id":"d1-2","day":1,"word":"retirement","meaning":"은퇴","ipa":"[rɪˈtaɪərmənt]","kr":"리타이어먼트","example":"He is looking forward to his retirement next year.","exampleKr":"그는 내년 은퇴를 고대하고 있다.","roots":"re-(뒤로) + tire(끌다, 프랑스어 tirer) + -ment(명사형) → 뒤로 물러남"},{"id":"d1-3","day":1,"word":"position","meaning":"직책","ipa":"[pəˈzɪʃn]","kr":"포지션","example":"She applied for a manager position at the company.","exampleKr":"그녀는 회사의 매니저 직책에 지원했다.","roots":"pos(놓다, 라틴어 ponere) + -ition(명사형) → 놓인 자리"},{"id":"d1-4","day":1,"word":"musical director","meaning":"음악 감독","ipa":"[ˈmjuːzɪkl dəˈrektər]","kr":"뮤지컬 디렉터","example":"The musical director chose the songs for the show.","exampleKr":"음악 감독이 공연 곡들을 선정했다."},{"id":"d1-5","day":1,"word":"permanent conductor","meaning":"상임 지휘자","ipa":"[ˈpɜːrmənənt kənˈdʌktər]","kr":"퍼머넌트 컨덕터","example":"He was appointed as the orchestra's permanent conductor.","exampleKr":"그는 오케스트라의 상임 지휘자로 임명되었다."},{"id":"d1-6","day":1,"word":"replacement","meaning":"후임자","ipa":"[rɪˈpleɪsmənt]","kr":"리플레이스먼트","example":"They are searching for a replacement for the retiring manager.","exampleKr":"그들은 은퇴하는 매니저의 후임자를 찾고 있다.","roots":"re-(다시) + place(두다) + -ment(명사형) → 다시 두는 것, 대체물"},{"id":"d1-7","day":1,"word":"approximately","meaning":"대략","ipa":"[əˈprɑːksɪmətli]","kr":"어프록시머틀리","example":"The trip takes approximately three hours by car.","exampleKr":"그 여행은 차로 대략 세 시간 걸린다.","roots":"ap-(~쪽으로) + proxim(가까운, 라틴어 proximus) + -ate + -ly → 가까운 쪽으로"},{"id":"d1-8","day":1,"word":"roughly","meaning":"대략","ipa":"[ˈrʌfli]","kr":"러플리","example":"Roughly half the students passed the exam.","exampleKr":"대략 학생의 절반이 시험에 통과했다."},{"id":"d1-9","day":1,"word":"broadly","meaning":"대략","ipa":"[ˈbrɔːdli]","kr":"브로들리","example":"Broadly speaking, the plan seems reasonable.","exampleKr":"대략적으로 말해서, 그 계획은 합리적으로 보인다."},{"id":"d1-10","day":1,"word":"loosely","meaning":"대략","ipa":"[ˈluːsli]","kr":"루슬리","example":"The rules were loosely enforced at the event.","exampleKr":"그 규칙은 행사에서 대략적으로만 시행되었다."},{"id":"d1-11","day":1,"word":"desirous of","meaning":"~을 원하는","ipa":"[dɪˈzaɪərəs əv]","kr":"디자이어러스 오브","example":"She was desirous of a fresh start in life.","exampleKr":"그녀는 인생의 새로운 시작을 원했다."},{"id":"d1-12","day":1,"word":"routine","meaning":"일상적인","ipa":"[ruːˈtiːn]","kr":"루틴","example":"He follows the same morning routine every day.","exampleKr":"그는 매일 같은 아침 일상을 따른다.","roots":"rout(길, 프랑스어 route) + -ine(형용사형) → 정해진 길을 따라가는 것, 일상적인"},{"id":"d1-13","day":1,"word":"chore","meaning":"집안일","ipa":"[tʃɔːr]","kr":"초어","example":"Washing dishes is my least favorite chore.","exampleKr":"설거지는 내가 가장 싫어하는 집안일이다."},{"id":"d1-14","day":1,"word":"nanny","meaning":"아이 돌보는 사람","ipa":"[ˈnæni]","kr":"내니","example":"The nanny took the children to the park.","exampleKr":"그 아이 돌보는 사람은 아이들을 공원에 데려갔다."},{"id":"d1-15","day":1,"word":"stir around","meaning":"돌아다니다","ipa":"[stɜːr əˈraʊnd]","kr":"스터 어라운드","example":"The kids stirred around the yard all afternoon.","exampleKr":"아이들은 오후 내내 마당을 돌아다녔다."},{"id":"d1-16","day":1,"word":"occur","meaning":"(머리에) 떠오르다","ipa":"[əˈkɜːr]","kr":"어커","example":"A great idea occurred to her while showering.","exampleKr":"샤워하는 동안 그녀에게 좋은 생각이 떠올랐다.","roots":"oc-(향하여, ob-의 변형) + cur(달리다, 라틴어 currere) → 향해 달려오다, (머리에) 떠오르다"},{"id":"d1-17","day":1,"word":"study","meaning":"서재","ipa":"[ˈstʌdi]","kr":"스터디","example":"He reads quietly in his study every evening.","exampleKr":"그는 매일 저녁 서재에서 조용히 책을 읽는다."},{"id":"d1-18","day":1,"word":"resist oneself","meaning":"참다","ipa":"[rɪˈzɪst wʌnˈself]","kr":"리지스트 원셀프","example":"He couldn't resist himself from eating the cake.","exampleKr":"그는 케이크를 먹는 것을 참을 수 없었다.","roots":"re-(반대로) + sist(서다, 라틴어 sistere) → 맞서서 버티고 서다, 참다"},{"id":"d1-19","day":1,"word":"endure","meaning":"견디다","ipa":"[ɪnˈdʊr]","kr":"인듀어","example":"The soldiers had to endure harsh winter conditions.","exampleKr":"군인들은 혹독한 겨울 조건을 견뎌야 했다.","roots":"en-(강조) + dur(단단한, 라틴어 durus) + -e → 단단하게 버티다, 견디다"},{"id":"d1-20","day":1,"word":"withstand","meaning":"견디다","ipa":"[wɪðˈstænd]","kr":"위드스탠드","example":"The building was built to withstand earthquakes.","exampleKr":"그 건물은 지진을 견디도록 지어졌다.","roots":"with-(~에 맞서, 고대 영어 wið는 원래 '대항하여') + stand(서다) → 맞서서 버티고 서다, 견디다"},{"id":"d1-21","day":1,"word":"bear","meaning":"견디다","ipa":"[ber]","kr":"베어","example":"She could hardly bear the pain any longer.","exampleKr":"그녀는 그 고통을 더 이상 견딜 수 없었다."},{"id":"d1-22","day":1,"word":"put up with","meaning":"견디다, 참다","ipa":"[pʊt ʌp wɪð]","kr":"풋 업 위드","example":"I can't put up with his rude behavior anymore.","exampleKr":"나는 그의 무례한 행동을 더는 참을 수 없다."},{"id":"d1-23","day":1,"word":"indifferent","meaning":"무관심한","ipa":"[ɪnˈdɪfərənt]","kr":"인디퍼런트","example":"He seemed indifferent to the outcome of the game.","exampleKr":"그는 경기 결과에 무관심해 보였다.","roots":"in-(부정) + different(다른) → 다르지 않은, 무관심한"},{"id":"d1-24","day":1,"word":"unfortunate","meaning":"유감스러운","ipa":"[ʌnˈfɔːrtʃənət]","kr":"언포처너트","example":"It was unfortunate that she missed the flight.","exampleKr":"그녀가 비행기를 놓친 것은 유감스러운 일이었다.","roots":"un-(부정) + fortune(운, 라틴어 fortuna) + -ate → 운이 없는"},{"id":"d1-25","day":1,"word":"obsess","meaning":"집착하다","ipa":"[əbˈses]","kr":"업세스","example":"He tends to obsess over small details.","exampleKr":"그는 사소한 세부 사항에 집착하는 경향이 있다.","roots":"ob-(맞서) + sess(앉다, 라틴어 sedere) → 맞서 눌러앉다, 사로잡히다"},{"id":"d1-26","day":1,"word":"solution oriented","meaning":"해결 지향적인","ipa":"[səˈluːʃn ˈɔːrientɪd]","kr":"솔루션 오리엔티드","example":"Our team takes a solution oriented approach to problems.","exampleKr":"우리 팀은 문제에 대해 해결 지향적인 접근을 취한다."},{"id":"d1-27","day":1,"word":"planet","meaning":"지구, 행성","ipa":"[ˈplænɪt]","kr":"플래닛","example":"Earth is the only known planet with life.","exampleKr":"지구는 생명체가 있다고 알려진 유일한 행성이다."},{"id":"d1-28","day":1,"word":"spill","meaning":"쏟아지다","ipa":"[spɪl]","kr":"스필","example":"Be careful not to spill your coffee.","exampleKr":"커피를 쏟지 않도록 조심해라."},{"id":"d1-29","day":1,"word":"stain","meaning":"얼룩지게 하다","ipa":"[steɪn]","kr":"스테인","example":"The red wine stained the white tablecloth.","exampleKr":"레드와인이 흰 식탁보를 얼룩지게 했다.","roots":"(di)s-(제거) + tain(물들이다, 라틴어 tingere) → 색이 빠져 얼룩지게 하다"},{"id":"d1-30","day":1,"word":"along the lines of","meaning":"~과 비슷한","ipa":"[əˈlɔːŋ ðə laɪnz əv]","kr":"어롱 더 라인즈 오브","example":"He said something along the lines of \"I quit.\"","exampleKr":"그는 \"그만두겠다\"와 비슷한 말을 했다."},{"id":"d1-31","day":1,"word":"get ~ in trouble","meaning":"~을 곤경에 빠뜨리다","ipa":"[ɡet ɪn ˈtrʌbl]","kr":"겟 인 트러블","example":"Skipping class will get you in trouble.","exampleKr":"수업을 빠지면 곤경에 빠질 것이다."},{"id":"d1-32","day":1,"word":"in company","meaning":"사람들 앞에서","ipa":"[ɪn ˈkʌmpəni]","kr":"인 컴퍼니","example":"He rarely speaks in company.","exampleKr":"그는 사람들 앞에서는 좀처럼 말하지 않는다."},{"id":"d1-33","day":1,"word":"bother -ing","meaning":"~하려고 애쓰다","ipa":"[ˈbɑːðər]","kr":"바더","example":"She didn't bother explaining the whole situation.","exampleKr":"그녀는 전체 상황을 설명하려고 애쓰지 않았다."},{"id":"d1-34","day":1,"word":"the room","meaning":"모인 사람들","ipa":"[ðə ruːm]","kr":"더 룸","example":"The room fell silent after his announcement.","exampleKr":"그의 발표 후 모인 사람들이 조용해졌다."},{"id":"d1-35","day":1,"word":"group polarization","meaning":"집단 양극화 현상","ipa":"[ɡruːp ˌpoʊləraɪˈzeɪʃn]","kr":"그룹 폴러라이제이션","example":"Group polarization can make opinions more extreme.","exampleKr":"집단 양극화 현상은 의견을 더 극단적으로 만들 수 있다."},{"id":"d1-36","day":1,"word":"exposure","meaning":"접하기, 노출","ipa":"[ɪkˈspoʊʒər]","kr":"익스포저","example":"Frequent exposure to sunlight can damage the skin.","exampleKr":"잦은 햇빛 노출은 피부를 손상시킬 수 있다.","roots":"ex-(밖으로) + pos(e)(놓다) + -ure(명사형) → 밖에 드러내 놓음"},{"id":"d1-37","day":1,"word":"conflicting","meaning":"상반된","ipa":"[kənˈflɪktɪŋ]","kr":"컨플릭팅","example":"The two witnesses gave conflicting accounts of the accident.","exampleKr":"두 목격자는 사고에 대해 상반된 설명을 했다.","roots":"con-(함께) + flict(부딪히다, 라틴어 fligere) → 서로 부딪히는"},{"id":"d1-38","day":1,"word":"inconsistent","meaning":"상반된","ipa":"[ˌɪnkənˈsɪstənt]","kr":"인컨시스턴트","example":"His statements were inconsistent with the evidence.","exampleKr":"그의 진술은 증거와 상반되었다.","roots":"in-(부정) + con-(함께) + sist(서다, 라틴어 sistere) → 함께 서지 못하는"},{"id":"d1-39","day":1,"word":"contradictory","meaning":"상반된","ipa":"[ˌkɑːntrəˈdɪktəri]","kr":"컨트러딕터리","example":"The report contained contradictory information.","exampleKr":"그 보고서에는 상반된 정보가 담겨 있었다.","roots":"contra-(반대로) + dict(말하다) + -ory → 반대로 말하는"},{"id":"d1-40","day":1,"word":"incompatible","meaning":"상반된","ipa":"[ˌɪnkəmˈpætəbl]","kr":"인컴패터블","example":"The new software is incompatible with older devices.","exampleKr":"새 소프트웨어는 구형 기기와 호환되지 않는다.","roots":"in-(부정) + com-(함께) + pat(견디다, 라틴어 pati) + -ible → 함께 견딜 수 없는"},{"id":"d1-41","day":1,"word":"diverse","meaning":"다양한","ipa":"[daɪˈvɜːrs]","kr":"다이버스","example":"The city has a diverse population.","exampleKr":"그 도시는 다양한 인구를 가지고 있다.","roots":"di-(따로) + vers(돌다, 라틴어 vertere) → 따로 돌려진, 다양한"},{"id":"d1-42","day":1,"word":"varied","meaning":"다양한","ipa":"[ˈverid]","kr":"베리드","example":"She has a varied taste in music.","exampleKr":"그녀는 음악 취향이 다양하다.","roots":"vari(다양한, 라틴어 varius) + -ed → 다양하게 된"},{"id":"d1-43","day":1,"word":"various","meaning":"다양한","ipa":"[ˈveriəs]","kr":"베리어스","example":"The store sells various kinds of fruit.","exampleKr":"그 가게는 다양한 종류의 과일을 판다.","roots":"vari(다양한) + -ous → 다양한 성질의"},{"id":"d1-44","day":1,"word":"varying","meaning":"다양한","ipa":"[ˈveriɪŋ]","kr":"베리잉","example":"Students showed varying levels of interest.","exampleKr":"학생들은 다양한 수준의 관심을 보였다.","roots":"vari(다양한) + -ing → 다양해지는"},{"id":"d1-45","day":1,"word":"a range of","meaning":"다양한","ipa":"[ə reɪndʒ əv]","kr":"어 레인지 오브","example":"The shop offers a range of services.","exampleKr":"그 가게는 다양한 서비스를 제공한다."},{"id":"d1-46","day":1,"word":"a variety of","meaning":"다양한","ipa":"[ə vəˈraɪəti əv]","kr":"어 버라이어티 오브","example":"He enjoys a variety of outdoor activities.","exampleKr":"그는 다양한 야외 활동을 즐긴다."},{"id":"d1-47","day":1,"word":"diversified","meaning":"다양한","ipa":"[daɪˈvɜːrsɪfaɪd]","kr":"다이버시파이드","example":"The company diversified its product line.","exampleKr":"그 회사는 제품군을 다양화했다.","roots":"di-(따로) + vers(돌다) + -ify(~하게 만들다) + -ed → 다양하게 만들어진"},{"id":"d1-48","day":1,"word":"multiple","meaning":"다양한","ipa":"[ˈmʌltɪpl]","kr":"멀티플","example":"She speaks multiple languages fluently.","exampleKr":"그녀는 여러 언어를 유창하게 구사한다.","roots":"multi-(많은) + -ple(겹, 라틴어 plicare 접다) → 여러 겹의"},{"id":"d1-49","day":1,"word":"echo chamber","meaning":"에코 챔버","ipa":"[ˈekoʊ ˈtʃeɪmbər]","kr":"에코 체임버","example":"Social media can become an echo chamber.","exampleKr":"소셜 미디어는 에코 챔버가 될 수 있다."},{"id":"d1-50","day":1,"word":"confirmation bias","meaning":"확증 편향","ipa":"[ˌkɑːnfərˈmeɪʃən ˈbaɪəs]","kr":"컨퍼메이션 바이어스","example":"Confirmation bias makes people ignore opposing views.","exampleKr":"확증 편향은 사람들이 반대되는 견해를 무시하게 만든다."},{"id":"d1-51","day":1,"word":"effectiveness","meaning":"업무 효율성, 유효성","ipa":"[ɪˈfektɪvnəs]","kr":"이펙티브니스","example":"They questioned the effectiveness of the new policy.","exampleKr":"그들은 새 정책의 효율성에 의문을 제기했다.","roots":"ef-(밖으로) + fect(만들다, 라틴어 facere) + -ive + -ness → 밖으로 만들어내는 정도"},{"id":"d1-52","day":1,"word":"drive away","meaning":"~을 몰아내다","ipa":"[draɪv əˈweɪ]","kr":"드라이브 어웨이","example":"High prices could drive away customers.","exampleKr":"높은 가격은 고객들을 몰아낼 수 있다."},{"id":"d1-53","day":1,"word":"talent","meaning":"인재(들)","ipa":"[ˈtælənt]","kr":"탤런트","example":"The company hires young talent every year.","exampleKr":"그 회사는 매년 젊은 인재들을 고용한다."},{"id":"d1-54","day":1,"word":"tear apart","meaning":"~을 해체하다","ipa":"[ter əˈpɑːrt]","kr":"테어 어파트","example":"The argument nearly tore the family apart.","exampleKr":"그 다툼은 가족을 거의 해체할 뻔했다."},{"id":"d1-55","day":1,"word":"uncertainty","meaning":"불확실성","ipa":"[ʌnˈsɜːrtnti]","kr":"언서튼티","example":"The future holds a great deal of uncertainty.","exampleKr":"미래에는 상당한 불확실성이 존재한다.","roots":"un-(부정) + certain(확실한, 라틴어 certus) + -ty → 확실하지 않음"},{"id":"d1-56","day":1,"word":"on board","meaning":"일할 수 있게 준비시키다","ipa":"[ɑːn bɔːrd]","kr":"온 보드","example":"It took time to get the new staff on board.","exampleKr":"새 직원들을 일할 준비시키는 데 시간이 걸렸다."},{"id":"d1-57","day":1,"word":"functioning","meaning":"제대로 기능을 하는","ipa":"[ˈfʌŋkʃənɪŋ]","kr":"펑셔닝","example":"The machine is still functioning after years of use.","exampleKr":"그 기계는 수년간 사용 후에도 여전히 제대로 기능한다.","roots":"funct(수행하다, 라틴어 fungi) + -ion + -ing → 기능을 수행하는"},{"id":"d1-58","day":1,"word":"steadfast","meaning":"변함없는","ipa":"[ˈstedfæst]","kr":"스테드패스트","example":"He remained steadfast in his beliefs.","exampleKr":"그는 자신의 신념에 변함없었다."},{"id":"d1-59","day":1,"word":"loyal","meaning":"충성스러운","ipa":"[ˈlɔɪəl]","kr":"로이얼","example":"She has been a loyal customer for years.","exampleKr":"그녀는 수년간 충성스러운 고객이었다.","roots":"loi/leg(법, 라틴어 lex) + -al → 법을 따르는, 충성스러운"},{"id":"d1-60","day":1,"word":"royal","meaning":"왕족의","ipa":"[ˈrɔɪəl]","kr":"로이얼","example":"The royal family attended the ceremony.","exampleKr":"왕족 가족이 그 행사에 참석했다.","roots":"reg(왕, 라틴어 rex) + -al → 왕에 관한"},{"id":"d1-61","day":1,"word":"virtually","meaning":"사실상, 실질적으로","ipa":"[ˈvɜːrtʃuəli]","kr":"버추얼리","example":"The project is virtually complete.","exampleKr":"그 프로젝트는 사실상 완료되었다.","roots":"virtu(e)(힘, 라틴어 virtus) + -al + -ly → 실질적인 힘으로 보면"},{"id":"d1-62","day":1,"word":"effectively","meaning":"사실상","ipa":"[ɪˈfektɪvli]","kr":"이펙티블리","example":"The new law effectively banned the practice.","exampleKr":"새 법은 사실상 그 관행을 금지했다.","roots":"ef-(밖으로) + fect(만들다) + -ive + -ly → 만들어낸 결과대로, 사실상"},{"id":"d1-63","day":1,"word":"practically","meaning":"사실상","ipa":"[ˈpræktɪkli]","kr":"프랙티클리","example":"Practically everyone in the office attended the meeting.","exampleKr":"사실상 사무실의 모든 사람이 회의에 참석했다.","roots":"practic(e)(실행하다, 그리스어 praktikos) + -al + -ly → 실질적으로"},{"id":"d1-64","day":1,"word":"practice","meaning":"실행; 훈련; 업무","ipa":"[ˈpræktɪs]","kr":"프랙티스","example":"Doctors need years of practice to master surgery.","exampleKr":"의사들은 수술을 숙달하기 위해 수년의 훈련이 필요하다.","roots":"prac(행하다, 그리스어 prassein) + -tice(~하는 것) → 실제로 행하는 것, 실행"},{"id":"d1-65","day":1,"word":"narrative","meaning":"이야기, 서술","ipa":"[ˈnærətɪv]","kr":"내러티브","example":"The film tells a powerful narrative of survival.","exampleKr":"그 영화는 생존에 관한 강력한 이야기를 담고 있다.","roots":"narr(말하다, 라틴어 narrare) + -ative → 이야기하는 것"},{"id":"d1-66","day":1,"word":"bond","meaning":"유대, 접착","ipa":"[bɑːnd]","kr":"본드","example":"The two sisters share a close bond.","exampleKr":"두 자매는 끈끈한 유대를 공유한다."},{"id":"d1-67","day":1,"word":"derive","meaning":"끌어내서 얻다","ipa":"[dɪˈraɪv]","kr":"디라이브","example":"She derives great joy from painting.","exampleKr":"그녀는 그림 그리기에서 큰 기쁨을 끌어낸다.","roots":"de-(~로부터) + rive(강, 라틴어 rivus) → 강에서 물을 끌어오다, 유래하다"},{"id":"d1-68","day":1,"word":"attain","meaning":"끌어내서 얻다","ipa":"[əˈteɪn]","kr":"어테인","example":"He worked hard to attain his goals.","exampleKr":"그는 목표를 달성하기 위해 열심히 일했다.","roots":"at-(~쪽으로) + tain(닿다, 라틴어 tangere) → ~에 닿다, 이루다"},{"id":"d1-69","day":1,"word":"acquire","meaning":"끌어내서 얻다","ipa":"[əˈkwaɪər]","kr":"어콰이어","example":"She acquired new skills during the internship.","exampleKr":"그녀는 인턴십 동안 새로운 기술을 습득했다.","roots":"ac-(~쪽으로) + quire(구하다, 라틴어 quaerere) → 구해서 얻다"},{"id":"d1-70","day":1,"word":"resilience","meaning":"회복력, 탄성","ipa":"[rɪˈzɪliəns]","kr":"리질리언스","example":"The team showed great resilience after the setback.","exampleKr":"그 팀은 좌절 후에도 뛰어난 회복력을 보였다.","roots":"re-(다시) + sili(뛰다, 라틴어 salire) + -ence → 다시 튀어오르는 힘"},{"id":"d1-71","day":1,"word":"wellspring","meaning":"원천","ipa":"[ˈwelˌsprɪŋ]","kr":"웰스프링","example":"Her childhood was a wellspring of creativity.","exampleKr":"그녀의 어린 시절은 창의력의 원천이었다."},{"id":"d1-72","day":1,"word":"potential","meaning":"잠재력, 가능성","ipa":"[pəˈtenʃl]","kr":"포텐셜","example":"The young athlete has great potential.","exampleKr":"그 젊은 운동선수는 큰 잠재력을 가지고 있다.","roots":"potent(할 수 있는, 라틴어 posse) + -ial → 할 수 있는 상태"},{"id":"d1-73","day":1,"word":"inspiration","meaning":"영감","ipa":"[ˌɪnspəˈreɪʃn]","kr":"인스퍼레이션","example":"Nature is a constant source of inspiration for her.","exampleKr":"자연은 그녀에게 끊임없는 영감의 원천이다.","roots":"in-(안으로) + spir(숨쉬다, 라틴어 spirare) + -ation → 안으로 숨을 불어넣음"},{"id":"d1-74","day":1,"word":"strike","meaning":"(갑자기) 생각이 떠오르다","ipa":"[straɪk]","kr":"스트라이크","example":"A brilliant idea struck him suddenly.","exampleKr":"갑자기 그에게 훌륭한 생각이 떠올랐다."},{"id":"d1-75","day":1,"word":"carry forward","meaning":"~을 전진시키다","ipa":"[ˈkæri ˈfɔːrwərd]","kr":"캐리 포워드","example":"We will carry forward the project next quarter.","exampleKr":"우리는 다음 분기에 그 프로젝트를 전진시킬 것이다."},{"id":"d1-76","day":1,"word":"flooded","meaning":"범람한, 물이 넘치는","ipa":"[ˈflʌdɪd]","kr":"플러디드","example":"The basement was flooded after the storm.","exampleKr":"폭풍 후 지하실이 물에 잠겼다."},{"id":"d1-77","day":1,"word":"grand","meaning":"웅장한","ipa":"[ɡrænd]","kr":"그랜드","example":"They held a grand celebration for the anniversary.","exampleKr":"그들은 기념일을 위해 웅장한 축하 행사를 열었다.","roots":"grand(크고 위대한, 라틴어 grandis, 고대 프랑스어를 거쳐 유입) → 웅장한"},{"id":"d1-78","day":1,"word":"mural","meaning":"벽화","ipa":"[ˈmjʊrəl]","kr":"뮤럴","example":"The artist painted a mural on the city wall.","exampleKr":"그 예술가는 도시 벽에 벽화를 그렸다.","roots":"mur(벽, 라틴어 murus) + -al → 벽에 관한"},{"id":"d1-79","day":1,"word":"show up","meaning":"나오다, 나타나다","ipa":"[ʃoʊ ʌp]","kr":"쇼 업","example":"He didn't show up for the meeting.","exampleKr":"그는 회의에 나타나지 않았다."},{"id":"d1-80","day":1,"word":"microscopic","meaning":"미세한, 아주 작은","ipa":"[ˌmaɪkrəˈskɑːpɪk]","kr":"마이크로스코픽","example":"The bacteria are too microscopic to see with the naked eye.","exampleKr":"그 박테리아는 육안으로 보기에 너무 미세하다.","roots":"micro-(작은, 그리스어 mikros) + scop(보다, 그리스어 skopein) + -ic → 작은 것을 보는"},{"id":"d1-81","day":1,"word":"minute","meaning":"미세한","ipa":"[maɪˈnjuːt]","kr":"마이뉴트","example":"The recipe requires only minute amounts of salt.","exampleKr":"그 조리법은 아주 미세한 양의 소금만 필요로 한다.","roots":"min(작게 하다, 라틴어 minuere) + -ute → 작게 만들어진"},{"id":"d1-82","day":1,"word":"fine","meaning":"미세한","ipa":"[faɪn]","kr":"파인","example":"The sand on the beach was very fine.","exampleKr":"해변의 모래는 매우 미세했다."},{"id":"d1-83","day":1,"word":"hierarchy","meaning":"위계, 계급, 서열","ipa":"[ˈhaɪərɑːrki]","kr":"하이어라키","example":"The company has a strict hierarchy of management.","exampleKr":"그 회사는 엄격한 경영 위계를 가지고 있다.","roots":"hier(신성한, 그리스어 hieros) + arch(다스리다, 그리스어 arkhein) + -y → 신성한 순서로 다스림"},{"id":"d1-84","day":1,"word":"weed out","meaning":"~을 제거하다, 골라내다","ipa":"[wiːd aʊt]","kr":"위드 아웃","example":"The coach weeded out the weaker players.","exampleKr":"코치는 약한 선수들을 제거했다."},{"id":"d1-85","day":1,"word":"obviously","meaning":"눈에 띄게","ipa":"[ˈɑːbviəsli]","kr":"압비어슬리","example":"Obviously, the plan needs more work.","exampleKr":"눈에 띄게, 그 계획은 더 많은 작업이 필요하다.","roots":"ob-(맞서) + vi(길, 라틴어 via) + -ous + -ly → 길을 막아서서 보이는, 명백히"},{"id":"d1-86","day":1,"word":"chain","meaning":"계통, 연쇄, 사슬","ipa":"[tʃeɪn]","kr":"체인","example":"The store operates a chain of restaurants.","exampleKr":"그 매장은 레스토랑 체인을 운영한다."},{"id":"d1-87","day":1,"word":"innovative","meaning":"혁신적인","ipa":"[ˈɪnəveɪtɪv]","kr":"이노베이티브","example":"The startup developed an innovative product.","exampleKr":"그 스타트업은 혁신적인 제품을 개발했다.","roots":"in-(안으로) + nov(새로운, 라틴어 novus) + -ative → 새로움을 안으로 들여오는"},{"id":"d1-88","day":1,"word":"patent","meaning":"특허(권)","ipa":"[ˈpætnt]","kr":"패턴트","example":"The inventor filed a patent for his design.","exampleKr":"발명가는 자신의 디자인에 대한 특허를 신청했다.","roots":"pat(열려있다, 라틴어 patere) + -ent → 열려서 명백히 드러난"},{"id":"d1-89","day":1,"word":"misinterpret","meaning":"잘못 전달하다","ipa":"[ˌmɪsɪnˈtɜːrprɪt]","kr":"미스인터프릿","example":"She misinterpreted his silence as anger.","exampleKr":"그녀는 그의 침묵을 화난 것으로 잘못 해석했다.","roots":"mis-(잘못) + inter-(사이에) + pret(해석하다, 라틴어 interpretari) → 잘못 해석하다"},{"id":"d1-90","day":1,"word":"telegram","meaning":"전보","ipa":"[ˈtelɪɡræm]","kr":"텔리그램","example":"He sent a telegram to notify them of his arrival.","exampleKr":"그는 도착을 알리기 위해 전보를 보냈다.","roots":"tele-(멀리, 그리스어) + gram(쓰다, 그리스어 gramma) → 멀리 쓴 것"},{"id":"d1-91","day":1,"word":"profitable","meaning":"수익성 있는, 유리한","ipa":"[ˈprɑːfɪtəbl]","kr":"프라피터블","example":"The new business turned out to be profitable.","exampleKr":"새 사업은 수익성이 있는 것으로 판명되었다.","roots":"pro-(앞으로) + fit(만들다, 라틴어 facere) + -able → 앞으로 만들어낼 수 있는, 이득이 되는"},{"id":"d1-92","day":1,"word":"communication","meaning":"통신 (수단), 의사소통","ipa":"[kəˌmjuːnɪˈkeɪʃn]","kr":"커뮤니케이션","example":"Clear communication is essential in a team.","exampleKr":"명확한 의사소통은 팀에서 필수적이다.","roots":"com-(함께) + mun(i)(공통의, 라틴어 communis) + -ication → 함께 공통되게 나누는 것"},{"id":"d1-93","day":1,"word":"replace","meaning":"대체하다","ipa":"[rɪˈpleɪs]","kr":"리플레이스","example":"They will replace the old machine with a new one.","exampleKr":"그들은 오래된 기계를 새것으로 대체할 것이다.","roots":"re-(다시) + place(두다) → 다시 두다, 대체하다"},{"id":"d1-94","day":1,"word":"substitute","meaning":"대체하다","ipa":"[ˈsʌbstɪtuːt]","kr":"섭스티튜트","example":"She used honey as a substitute for sugar.","exampleKr":"그녀는 설탕 대신 꿀을 대체제로 사용했다.","roots":"sub-(아래에) + stit(ute)(세우다, 라틴어 statuere) → 아래에 대신 세우다"},{"id":"d1-95","day":1,"word":"alternate","meaning":"대체하다","ipa":"[ˈɔːltərneɪt]","kr":"올터네이트","example":"The two teams alternate turns each round.","exampleKr":"두 팀은 매 라운드마다 순서를 번갈아 한다.","roots":"alter(다른, 라틴어 alter) + -ate → 다른 것으로 번갈아 하다"},{"id":"d1-96","day":1,"word":"scholar","meaning":"학자","ipa":"[ˈskɑːlər]","kr":"스칼러","example":"The scholar spent years studying ancient texts.","exampleKr":"그 학자는 고대 문헌을 연구하는 데 수년을 보냈다.","roots":"schol(여가/학교, 그리스어 skhole) + -ar → 학교에서 배우는 사람"},{"id":"d1-97","day":1,"word":"comprehensive","meaning":"종합적인, 포괄적인","ipa":"[ˌkɑːmprɪˈhensɪv]","kr":"컴프리헨시브","example":"The report offers a comprehensive analysis of the market.","exampleKr":"그 보고서는 시장에 대한 종합적인 분석을 제공한다.","roots":"com-(함께) + prehend(잡다, 라틴어 prehendere) + -ive → 함께 다 붙잡는"},{"id":"d1-98","day":1,"word":"inclusive","meaning":"포괄적인","ipa":"[ɪnˈkluːsɪv]","kr":"인클루시브","example":"The school promotes an inclusive environment for all students.","exampleKr":"그 학교는 모든 학생을 위한 포괄적인 환경을 조성한다.","roots":"in-(안으로) + clud(e)(닫다, 라틴어 claudere) + -ive → 안으로 닫아 포함하는"},{"id":"d1-99","day":1,"word":"generic","meaning":"포괄적인","ipa":"[dʒəˈnerɪk]","kr":"제네릭","example":"He bought the generic brand instead of the name brand.","exampleKr":"그는 유명 브랜드 대신 일반 브랜드를 샀다.","roots":"gener(종류, 라틴어 genus) + -ic → 종류에 관한, 일반적인"},{"id":"d1-100","day":1,"word":"encyclopedia","meaning":"백과사전","ipa":"[ɪnˌsaɪkləˈpiːdiə]","kr":"인사이클로피디어","example":"She looked up the word in an encyclopedia.","exampleKr":"그녀는 백과사전에서 그 단어를 찾아봤다.","roots":"en-(안에) + cyclo(원, 그리스어 kyklos) + paideia(교육, 그리스어) → 전반적인 교육을 원 안에 담은 것"},{"id":"d2-1","day":2,"word":"estimate","meaning":"추정하다, 예측하다","ipa":"[ˈestɪmeɪt]","kr":"에스티메이트","example":"Experts estimate the project will cost $2 million.","exampleKr":"전문가들은 그 프로젝트가 200만 달러가 들 것으로 추정한다."},{"id":"d2-2","day":2,"word":"sector","meaning":"분야, 부문","ipa":"[ˈsektər]","kr":"섹터","example":"The tech sector grew rapidly last year.","exampleKr":"기술 분야는 작년에 빠르게 성장했다.","roots":"sec(자르다, 라틴어 secare) + -tor(명사형) → 잘라낸 구역, 부문"},{"id":"d2-3","day":2,"word":"social work","meaning":"사회 복지","ipa":"[ˈsoʊʃl wɜːrk]","kr":"소셜 워크","example":"She has a degree in social work.","exampleKr":"그녀는 사회 복지 학위를 가지고 있다."},{"id":"d2-4","day":2,"word":"wholesale","meaning":"도매","ipa":"[ˈhoʊlseɪl]","kr":"홀세일","example":"He buys goods at wholesale prices.","exampleKr":"그는 도매가로 상품을 산다."},{"id":"d2-5","day":2,"word":"retail","meaning":"소매","ipa":"[ˈriːteɪl]","kr":"리테일","example":"The store focuses on retail sales.","exampleKr":"그 가게는 소매 판매에 집중한다.","roots":"re-(다시) + tail(자르다, 프랑스어 tailler) → 물건을 다시 잘라 나눠 파는 것"},{"id":"d2-6","day":2,"word":"manufacture","meaning":"제조하다","ipa":"[ˌmænjuˈfæktʃər]","kr":"매뉴팩처","example":"The factory manufactures car parts.","exampleKr":"그 공장은 자동차 부품을 제조한다.","roots":"manu(손, 라틴어 manus) + fact(만들다, 라틴어 facere) + -ure(명사형) → 손으로 만든 것"},{"id":"d2-7","day":2,"word":"existing","meaning":"현존하는, 기존의","ipa":"[ɪɡˈzɪstɪŋ]","kr":"이그지스팅","example":"They upgraded the existing system.","exampleKr":"그들은 기존 시스템을 업그레이드했다.","roots":"ex-(밖으로) + sist(서다, 라틴어 sistere) + -ing → 밖으로 나와 서 있는, 존재하는"},{"id":"d2-8","day":2,"word":"established","meaning":"기존의","ipa":"[ɪˈstæblɪʃt]","kr":"이스태블리쉬트","example":"It is an established company with a long history.","exampleKr":"그것은 오랜 역사를 가진 기존 회사다.","roots":"e-(밖으로, 강조) + stabl(안정된, 라틴어 stabilis) + -ish(동사형) → 안정되게 세워진, 확립된"},{"id":"d2-9","day":2,"word":"net effect","meaning":"순효과","ipa":"[net ɪˈfekt]","kr":"넷 이펙트","example":"The net effect of the policy was positive.","exampleKr":"그 정책의 순효과는 긍정적이었다."},{"id":"d2-10","day":2,"word":"net sales","meaning":"(세금 뺀) 순 매출액","ipa":"[net seɪlz]","kr":"넷 세일즈","example":"Net sales increased by ten percent this quarter.","exampleKr":"이번 분기 순 매출액이 10퍼센트 증가했다."},{"id":"d2-11","day":2,"word":"undergo","meaning":"겪다","ipa":"[ˌʌndərˈɡoʊ]","kr":"언더고우","example":"The patient will undergo surgery tomorrow.","exampleKr":"그 환자는 내일 수술을 받을 것이다."},{"id":"d2-12","day":2,"word":"go through","meaning":"겪다","ipa":"[ɡoʊ θruː]","kr":"고우 쓰루","example":"She went through a difficult time last year.","exampleKr":"그녀는 작년에 힘든 시기를 겪었다."},{"id":"d2-13","day":2,"word":"suffer","meaning":"겪다","ipa":"[ˈsʌfər]","kr":"서퍼","example":"Many farmers suffered from the drought.","exampleKr":"많은 농부들이 가뭄으로 고통을 겪었다.","roots":"sub-(아래에서) + fer(나르다, 라틴어 ferre) → 아래에서 짊어지고 견디다"},{"id":"d2-14","day":2,"word":"anticipate","meaning":"예상하다, 전망하다","ipa":"[ænˈtɪsɪpeɪt]","kr":"앤티시페이트","example":"We anticipate strong sales this holiday season.","exampleKr":"우리는 이번 연휴 시즌에 강한 매출을 예상한다.","roots":"anti-(=ante-, 미리) + cip(잡다, 라틴어 capere) + -ate → 미리 잡아 대비하다"},{"id":"d2-15","day":2,"word":"be determined to","meaning":"~하기로 결심하다","ipa":"[bi dɪˈtɜːrmɪnd tuː]","kr":"비 디터민드 투","example":"She is determined to finish the marathon.","exampleKr":"그녀는 마라톤을 완주하기로 결심했다."},{"id":"d2-16","day":2,"word":"field","meaning":"분야, 영역","ipa":"[fiːld]","kr":"필드","example":"He works in the field of engineering.","exampleKr":"그는 공학 분야에서 일한다."},{"id":"d2-17","day":2,"word":"realm","meaning":"분야, 영역","ipa":"[relm]","kr":"렐름","example":"This falls outside the realm of science.","exampleKr":"이것은 과학의 영역 밖에 있다.","roots":"reg(왕, 다스리다, 라틴어 rex/regalis) + -alme(명사형, 고대 프랑스어) → 왕이 다스리는 영역"},{"id":"d2-18","day":2,"word":"domain","meaning":"분야, 영역","ipa":"[doʊˈmeɪn]","kr":"도우메인","example":"Marketing is not her domain of expertise.","exampleKr":"마케팅은 그녀의 전문 분야가 아니다.","roots":"domin(주인, 지배자, 라틴어 dominus) + -ain(명사형) → 지배자가 다스리는 영역"},{"id":"d2-19","day":2,"word":"sphere","meaning":"분야, 영역","ipa":"[sfɪr]","kr":"스피어","example":"Politics is a sphere she avoids.","exampleKr":"정치는 그녀가 피하는 영역이다."},{"id":"d2-20","day":2,"word":"medicine","meaning":"의학, 약","ipa":"[ˈmedɪsn]","kr":"메디슨","example":"He studies medicine at the university.","exampleKr":"그는 대학에서 의학을 공부한다.","roots":"med(치료하다, 라틴어 mederi) + -icine(명사형) → 치료하는 것, 의학"},{"id":"d2-21","day":2,"word":"internship","meaning":"인턴 과정","ipa":"[ˈɪntɜːrnʃɪp]","kr":"인턴십","example":"She completed an internship at a law firm.","exampleKr":"그녀는 로펌에서 인턴 과정을 마쳤다.","roots":"intern(내부의, 라틴어 internus) + -ship(신분, 상태) → 조직 내부에서 배우는 신분"},{"id":"d2-22","day":2,"word":"surgery","meaning":"외과, 수술","ipa":"[ˈsɜːrdʒəri]","kr":"서저리","example":"The surgery lasted for six hours.","exampleKr":"그 수술은 여섯 시간 동안 진행되었다.","roots":"cheir(손, 그리스어 kheir) + ergon(일, 그리스어) → 손으로 하는 일, 외과 수술"},{"id":"d2-23","day":2,"word":"deny","meaning":"거절하다, 부인하다","ipa":"[dɪˈnaɪ]","kr":"디나이","example":"He denied any involvement in the scandal.","exampleKr":"그는 그 스캔들에 연루된 것을 부인했다.","roots":"de-(부정) + ny(말하다, 라틴어 negare) → 아니라고 말하다, 부인하다"},{"id":"d2-24","day":2,"word":"decline","meaning":"거절하다","ipa":"[dɪˈklaɪn]","kr":"디클라인","example":"She declined the invitation to the party.","exampleKr":"그녀는 파티 초대를 거절했다.","roots":"de-(아래로) + clin(기울다, 라틴어 clinare) → 아래로 기울다, 거절하다"},{"id":"d2-25","day":2,"word":"turn down","meaning":"거절하다","ipa":"[tɜːrn daʊn]","kr":"턴 다운","example":"He turned down the job offer.","exampleKr":"그는 그 일자리 제안을 거절했다."},{"id":"d2-26","day":2,"word":"reject","meaning":"거절하다","ipa":"[rɪˈdʒekt]","kr":"리젝트","example":"The committee rejected the proposal.","exampleKr":"위원회는 그 제안을 거절했다.","roots":"re-(뒤로) + ject(던지다, 라틴어 jacere) → 뒤로 던지다, 거절하다"},{"id":"d2-27","day":2,"word":"refuse","meaning":"거절하다","ipa":"[rɪˈfjuːz]","kr":"리퓨즈","example":"She refused to answer the question.","exampleKr":"그녀는 질문에 답하기를 거절했다.","roots":"re-(뒤로) + fus(붓다, 라틴어 fundere) → 뒤로 쏟아버리다, 거절하다"},{"id":"d2-28","day":2,"word":"in labor","meaning":"진통 중인","ipa":"[ɪn ˈleɪbər]","kr":"인 레이버","example":"The woman was in labor for ten hours.","exampleKr":"그 여성은 열 시간 동안 진통 중이었다."},{"id":"d2-29","day":2,"word":"affect","meaning":"영향을 미치다","ipa":"[əˈfekt]","kr":"어펙트","example":"The weather can affect our mood.","exampleKr":"날씨는 우리의 기분에 영향을 미칠 수 있다.","roots":"af-(ad-, ~에게) + fect(하다, 라틴어 facere) → ~에게 작용을 가하다, 영향을 미치다"},{"id":"d2-30","day":2,"word":"method","meaning":"방법","ipa":"[ˈmeθəd]","kr":"메써드","example":"They tried a new teaching method.","exampleKr":"그들은 새로운 교육 방법을 시도했다.","roots":"meta-(따라서, 넘어서) + hod(길, 그리스어 hodos) → 따라가는 길, 방법"},{"id":"d2-31","day":2,"word":"newborn","meaning":"신생아","ipa":"[ˈnuːbɔːrn]","kr":"뉴본","example":"The newborn slept most of the day.","exampleKr":"그 신생아는 하루의 대부분을 잤다."},{"id":"d2-32","day":2,"word":"factor","meaning":"요인","ipa":"[ˈfæktər]","kr":"팩터","example":"Price is a major factor in the decision.","exampleKr":"가격은 그 결정에서 주요 요인이다.","roots":"fact(만들다, 라틴어 facere) + -or(행위자) → 만들어내는 것, 요인"},{"id":"d2-33","day":2,"word":"honorary","meaning":"명예(직)의","ipa":"[ˈɑːnəreri]","kr":"아너레리","example":"She received an honorary degree from the university.","exampleKr":"그녀는 대학에서 명예 학위를 받았다.","roots":"honor(명예, 라틴어 honor) + -ary(형용사형) → 명예로 주어지는"},{"id":"d2-34","day":2,"word":"doctorate","meaning":"박사 학위","ipa":"[ˈdɑːktərət]","kr":"닥터럿","example":"He earned his doctorate in physics.","exampleKr":"그는 물리학 박사 학위를 받았다.","roots":"doc(가르치다, 라틴어 docere) + -tor(행위자) + -ate(명사형) → 가르칠 자격, 박사 학위"},{"id":"d2-35","day":2,"word":"hold","meaning":"간직하다","ipa":"[hoʊld]","kr":"호울드","example":"She holds fond memories of her hometown.","exampleKr":"그녀는 고향에 대한 좋은 기억을 간직하고 있다."},{"id":"d2-36","day":2,"word":"timetable","meaning":"시간표","ipa":"[ˈtaɪmteɪbl]","kr":"타임테이블","example":"Check the timetable before you leave.","exampleKr":"떠나기 전에 시간표를 확인해라."},{"id":"d2-37","day":2,"word":"main gate","meaning":"정문","ipa":"[meɪn ɡeɪt]","kr":"메인 게이트","example":"Meet me at the main gate at noon.","exampleKr":"정오에 정문에서 만나자."},{"id":"d2-38","day":2,"word":"purchase","meaning":"구매하다","ipa":"[ˈpɜːrtʃəs]","kr":"퍼처스","example":"She wants to purchase a new laptop.","exampleKr":"그녀는 새 노트북을 구매하고 싶어한다.","roots":"pur-(완전히, 프랑스어 pour-) + chase(쫓다, 프랑스어 chacier) → 끝까지 쫓아가서 얻다, 구매하다"},{"id":"d2-39","day":2,"word":"in advance","meaning":"미리","ipa":"[ɪn ədˈvæns]","kr":"인 어드밴스","example":"Please book your ticket in advance.","exampleKr":"미리 티켓을 예매해 주세요."},{"id":"d2-40","day":2,"word":"beforehand","meaning":"미리","ipa":"[bɪˈfɔːrhænd]","kr":"비포핸드","example":"He prepared his speech beforehand.","exampleKr":"그는 미리 연설을 준비했다."},{"id":"d2-41","day":2,"word":"on site","meaning":"현장에서","ipa":"[ɑːn saɪt]","kr":"온 사이트","example":"The technician fixed the issue on site.","exampleKr":"기술자는 현장에서 문제를 해결했다."},{"id":"d2-42","day":2,"word":"resident","meaning":"거주자","ipa":"[ˈrezɪdənt]","kr":"레지던트","example":"Only residents can use the parking lot.","exampleKr":"거주자만 그 주차장을 이용할 수 있다.","roots":"re-(계속) + sid(앉다, 라틴어 sedere) + -ent → 계속 앉아 있는 사람, 거주자"},{"id":"d2-43","day":2,"word":"inhabitant","meaning":"거주자","ipa":"[ɪnˈhæbɪtənt]","kr":"인해비턴트","example":"The island has few inhabitants.","exampleKr":"그 섬에는 거주자가 거의 없다.","roots":"in-(안에) + habit(살다, 라틴어 habitare) + -ant → 안에 사는 사람, 거주자"},{"id":"d2-44","day":2,"word":"dweller","meaning":"거주자","ipa":"[ˈdwelər]","kr":"드웰러","example":"Cave dwellers left paintings on the walls.","exampleKr":"동굴 거주자들은 벽에 그림을 남겼다."},{"id":"d2-45","day":2,"word":"category","meaning":"분야","ipa":"[ˈkætəɡɔːri]","kr":"캐터고리","example":"This book falls under the fiction category.","exampleKr":"이 책은 소설 분야에 속한다.","roots":"cata-(~에 대해, 그리스어 kata) + agor(말하다, 그리스어 agoreuein) → 공개적으로 규정해 나눈 것, 범주"},{"id":"d2-46","day":2,"word":"act out","meaning":"~을 연기하다","ipa":"[ækt aʊt]","kr":"액트 아웃","example":"The children acted out the story.","exampleKr":"아이들은 그 이야기를 연기했다."},{"id":"d2-47","day":2,"word":"autograph","meaning":"사인하다","ipa":"[ˈɔːtəɡræf]","kr":"오토그래프","example":"The fans asked the singer to autograph their albums.","exampleKr":"팬들은 가수에게 앨범에 사인해달라고 요청했다.","roots":"auto-(스스로, 그리스어) + graph(쓰다, 그리스어 graphein) → 스스로 쓴 것, 사인"},{"id":"d2-48","day":2,"word":"announce","meaning":"발표하다","ipa":"[əˈnaʊns]","kr":"어나운스","example":"The company will announce its results tomorrow.","exampleKr":"그 회사는 내일 실적을 발표할 것이다.","roots":"an-(ad-, ~에게) + nounce(알리다, 라틴어 nuntiare) → ~에게 알리다, 발표하다"},{"id":"d2-49","day":2,"word":"unveil","meaning":"발표하다","ipa":"[ʌnˈveɪl]","kr":"언베일","example":"They unveiled the new product at the conference.","exampleKr":"그들은 콘퍼런스에서 새 제품을 발표했다.","roots":"un-(제거) + veil(베일, 라틴어 vela) → 베일을 걷어내다, 발표하다"},{"id":"d2-50","day":2,"word":"publish","meaning":"발표하다","ipa":"[ˈpʌblɪʃ]","kr":"퍼블리시","example":"She plans to publish her first novel next year.","exampleKr":"그녀는 내년에 첫 소설을 발표할 계획이다.","roots":"public(공공의, 라틴어 publicus) + -ish(동사형) → 공공에 알리다, 발표하다"},{"id":"d2-51","day":2,"word":"demonstrate","meaning":"입증하다","ipa":"[ˈdemənstreɪt]","kr":"데먼스트레이트","example":"The teacher demonstrated how to solve the problem.","exampleKr":"선생님은 문제를 푸는 방법을 설명했다.","roots":"de-(강조) + monstr(보여주다, 라틴어 monstrare) + -ate → 확실히 보여주다, 입증하다"},{"id":"d2-52","day":2,"word":"preschool age","meaning":"취학 전 연령","ipa":"[ˈpriːskuːl eɪdʒ]","kr":"프리스쿨 에이지","example":"Children of preschool age need close supervision.","exampleKr":"취학 전 연령의 아이들은 세심한 보살핌이 필요하다."},{"id":"d2-53","day":2,"word":"passage","meaning":"흐름, 경과, 추이","ipa":"[ˈpæsɪdʒ]","kr":"패시지","example":"The passage of time changed everything.","exampleKr":"시간의 흐름이 모든 것을 바꿔놓았다."},{"id":"d2-54","day":2,"word":"unfold","meaning":"펼쳐지다, 전개되다","ipa":"[ʌnˈfoʊld]","kr":"언포울드","example":"The story slowly unfolds over three chapters.","exampleKr":"그 이야기는 세 장에 걸쳐 서서히 전개된다."},{"id":"d2-55","day":2,"word":"overstate","meaning":"과장하다","ipa":"[ˌoʊvərˈsteɪt]","kr":"오버스테이트","example":"He tends to overstate his achievements.","exampleKr":"그는 자신의 성과를 과장하는 경향이 있다.","roots":"over-(지나치게) + state(진술하다, 라틴어 status) → 지나치게 진술하다, 과장하다"},{"id":"d2-56","day":2,"word":"cross off","meaning":"~을 지우다","ipa":"[krɔːs ɔːf]","kr":"크로스 오프","example":"She crossed off each item on her list.","exampleKr":"그녀는 목록의 각 항목을 지웠다."},{"id":"d2-57","day":2,"word":"go over","meaning":"~을 검토하다","ipa":"[ɡoʊ ˈoʊvər]","kr":"고우 오우버","example":"Let's go over the report before the meeting.","exampleKr":"회의 전에 그 보고서를 검토해보자."},{"id":"d2-58","day":2,"word":"tagalong","meaning":"붙어서 따라다니는 사람","ipa":"[ˈtæɡəlɔːŋ]","kr":"태거롱","example":"Her little brother is always a tagalong.","exampleKr":"그녀의 남동생은 항상 따라다니는 아이다."},{"id":"d2-59","day":2,"word":"sense of control","meaning":"통제감","ipa":"[sens əv kənˈtroʊl]","kr":"센스 오브 컨트로울","example":"Planning ahead gives her a sense of control.","exampleKr":"미리 계획하는 것은 그녀에게 통제감을 준다."},{"id":"d2-60","day":2,"word":"random error","meaning":"임의 오차, 무작위 오차","ipa":"[ˈrændəm ˈerər]","kr":"랜덤 에러","example":"The results contained a small random error.","exampleKr":"그 결과에는 작은 임의 오차가 포함되어 있었다."},{"id":"d2-61","day":2,"word":"detect","meaning":"발견하다","ipa":"[dɪˈtekt]","kr":"디텍트","example":"The sensor can detect smoke instantly.","exampleKr":"그 센서는 즉시 연기를 감지할 수 있다.","roots":"de-(제거, 벗기다) + tect(덮다, 라틴어 tegere) → 덮개를 벗겨내다, 발견하다"},{"id":"d2-62","day":2,"word":"measurement","meaning":"측정","ipa":"[ˈmeʒərmənt]","kr":"메저먼트","example":"Accurate measurement is crucial in science.","exampleKr":"정확한 측정은 과학에서 중요하다.","roots":"measur(재다, 라틴어 mensurare) + -ment(명사형) → 재는 것, 측정"},{"id":"d2-63","day":2,"word":"reading","meaning":"측정값","ipa":"[ˈriːdɪŋ]","kr":"리딩","example":"The reading on the thermometer was too high.","exampleKr":"온도계의 측정값이 너무 높았다."},{"id":"d2-64","day":2,"word":"obtain","meaning":"얻다","ipa":"[əbˈteɪn]","kr":"업테인","example":"She obtained permission to use the data.","exampleKr":"그녀는 그 데이터를 사용할 허가를 얻었다.","roots":"ob-(향하여) + tain(잡다, 라틴어 tenere) → 향해 잡아서 얻다"},{"id":"d2-65","day":2,"word":"derive","meaning":"얻어내다","ipa":"[dɪˈraɪv]","kr":"디라이브","example":"This word derives from Latin.","exampleKr":"이 단어는 라틴어에서 유래한다.","roots":"de-(아래로) + rive(강, 라틴어 rivus) → 강에서 물을 끌어내다, 얻어내다"},{"id":"d2-66","day":2,"word":"acquire","meaning":"얻어내다","ipa":"[əˈkwaɪər]","kr":"어콰이어","example":"The company acquired a smaller competitor.","exampleKr":"그 회사는 더 작은 경쟁사를 인수했다.","roots":"ac-(ad-, ~쪽으로) + quire(구하다, 라틴어 quaerere) → ~을 향해 구해서 얻다"},{"id":"d2-67","day":2,"word":"systematic error","meaning":"계통 오차","ipa":"[ˌsɪstəˈmætɪk ˈerər]","kr":"시스터매틱 에러","example":"A systematic error affected all the readings.","exampleKr":"계통 오차가 모든 측정값에 영향을 미쳤다."},{"id":"d2-68","day":2,"word":"eliminate","meaning":"제거하다","ipa":"[ɪˈlɪmɪneɪt]","kr":"일리미네이트","example":"The new process eliminated waste.","exampleKr":"새 공정은 낭비를 제거했다.","roots":"e-(밖으로) + limin(문지방, 라틴어 limen) + -ate → 문지방 밖으로 내쫓다, 제거하다"},{"id":"d2-69","day":2,"word":"manifest","meaning":"드러내다, 명백한","ipa":"[ˈmænɪfest]","kr":"매니페스트","example":"Her anxiety manifested as constant worry.","exampleKr":"그녀의 불안은 끊임없는 걱정으로 드러났다.","roots":"mani(손, 라틴어 manus) + fest(치다, 라틴어 fendere와 관련) → 손에 닿을 만큼 명백히 드러난"},{"id":"d2-70","day":2,"word":"reveal","meaning":"드러내다","ipa":"[rɪˈviːl]","kr":"리빌","example":"The test results revealed a surprising pattern.","exampleKr":"그 검사 결과는 놀라운 패턴을 드러냈다.","roots":"re-(반대로) + veal(가리다, 라틴어 velare) → 가린 것을 걷어내다, 드러내다"},{"id":"d2-71","day":2,"word":"disclose","meaning":"드러내다","ipa":"[dɪsˈkloʊz]","kr":"디스클로우즈","example":"The company failed to disclose the risks.","exampleKr":"그 회사는 위험을 공개하지 않았다.","roots":"dis-(반대) + close(닫다, 라틴어 claudere) → 닫힌 것을 열다, 폭로하다"},{"id":"d2-72","day":2,"word":"quote","meaning":"(값을) 매기다","ipa":"[kwoʊt]","kr":"쿼우트","example":"The dealer quoted a price of $500.","exampleKr":"딜러는 500달러의 가격을 매겼다."},{"id":"d2-73","day":2,"word":"imprecision","meaning":"부정확함","ipa":"[ˌɪmprɪˈsɪʒn]","kr":"임프리시전","example":"The imprecision of the tool caused errors.","exampleKr":"그 도구의 부정확함이 오류를 일으켰다.","roots":"im-(부정) + pre-(미리) + cis(자르다, 라틴어 caedere) + -ion(명사형) → 미리 정확히 잘라내지 못함, 부정확함"},{"id":"d2-74","day":2,"word":"ego","meaning":"자존심, 자아","ipa":"[ˈiːɡoʊ]","kr":"이고우","example":"His ego was hurt by the criticism.","exampleKr":"그의 자존심은 그 비판에 상처받았다."},{"id":"d2-75","day":2,"word":"conceal","meaning":"숨기다","ipa":"[kənˈsiːl]","kr":"컨실","example":"She concealed her disappointment with a smile.","exampleKr":"그녀는 미소로 실망을 숨겼다.","roots":"con-(완전히) + ceal(감추다, 라틴어 celare) → 완전히 감추다, 숨기다"},{"id":"d2-76","day":2,"word":"reliable","meaning":"신뢰도가 높은","ipa":"[rɪˈlaɪəbl]","kr":"릴라이어블","example":"He is known as a reliable worker.","exampleKr":"그는 신뢰도가 높은 직원으로 알려져 있다.","roots":"re-(계속) + li(묶다, 라틴어 ligare) + -able(할 수 있는) → 계속 묶여 의지할 수 있는"},{"id":"d2-77","day":2,"word":"dependable","meaning":"믿을 만한","ipa":"[dɪˈpendəbl]","kr":"디펜더블","example":"Their service is fast and dependable.","exampleKr":"그들의 서비스는 빠르고 믿을 만하다.","roots":"de-(아래로) + pend(매달리다, 라틴어 pendere) + -able → 아래에 매달려 의지할 수 있는"},{"id":"d2-78","day":2,"word":"distinct","meaning":"두드러지는, 독특한","ipa":"[dɪˈstɪŋkt]","kr":"디스팅트","example":"Each region has a distinct culture.","exampleKr":"각 지역마다 뚜렷한 문화를 가지고 있다.","roots":"di-(분리) + stinct(찌르다, 라틴어 stinguere) → 찔러서 구별해낸, 뚜렷한"},{"id":"d2-79","day":2,"word":"trait","meaning":"특징, 특성","ipa":"[treɪt]","kr":"트레이트","example":"Honesty is an important trait in a leader.","exampleKr":"정직함은 리더에게 중요한 특성이다.","roots":"tra(끌다, 라틴어 trahere) + -it(과거분사형, 프랑스어) → 끌어당겨 나온 것, 특징"},{"id":"d2-80","day":2,"word":"nature","meaning":"본성, 속성","ipa":"[ˈneɪtʃər]","kr":"네이처","example":"It is human nature to seek comfort.","exampleKr":"편안함을 추구하는 것은 인간의 본성이다.","roots":"na(태어나다, 라틴어 nasci) + -ture(명사형) → 태어난 그대로의 성질, 본성"},{"id":"d2-81","day":2,"word":"thereby","meaning":"그것으로, 그것에 의해서","ipa":"[ðerˈbaɪ]","kr":"데어바이","example":"He studied hard, thereby earning a scholarship.","exampleKr":"그는 열심히 공부했고, 그것으로 장학금을 받았다."},{"id":"d2-82","day":2,"word":"whereby","meaning":"그것에 의해서","ipa":"[werˈbaɪ]","kr":"웨어바이","example":"They created a system whereby waste is recycled.","exampleKr":"그들은 폐기물이 재활용되는 시스템을 만들었다."},{"id":"d2-83","day":2,"word":"dependability","meaning":"신뢰 가능성","ipa":"[dɪˌpendəˈbɪləti]","kr":"디펜더빌러티","example":"Customers value dependability over price.","exampleKr":"고객들은 가격보다 신뢰 가능성을 중시한다.","roots":"de-(아래로) + pend(매달리다, 라틴어 pendere) + -ability(명사형) → 아래에 매달려 의지할 수 있는 성질"},{"id":"d2-84","day":2,"word":"band","meaning":"무리, 밴드(유목민 집단)","ipa":"[bænd]","kr":"밴드","example":"A band of nomads crossed the desert.","exampleKr":"한 무리의 유목민이 사막을 건넜다."},{"id":"d2-85","day":2,"word":"classifiable","meaning":"분류할 수 있는","ipa":"[ˈklæsɪfaɪəbl]","kr":"클래시파이어블","example":"The data is easily classifiable by age.","exampleKr":"그 데이터는 나이별로 쉽게 분류할 수 있다.","roots":"class(부류, 라틴어 classis) + -ify(동사형) + -able → 부류로 나눌 수 있는"},{"id":"d2-86","day":2,"word":"genus","meaning":"(생물 분류의) 속","ipa":"[ˈdʒiːnəs]","kr":"지너스","example":"Wolves belong to the genus Canis.","exampleKr":"늑대는 캐니스 속에 속한다."},{"id":"d2-87","day":2,"word":"descendant","meaning":"후손","ipa":"[dɪˈsendənt]","kr":"디센던트","example":"She is a descendant of the town's founder.","exampleKr":"그녀는 그 마을 창립자의 후손이다.","roots":"de-(아래로) + scend(오르다, 라틴어 scandere) + -ant → 아래로 내려온 사람, 후손"},{"id":"d2-88","day":2,"word":"hunter gatherer","meaning":"수렵 채집인","ipa":"[ˈhʌntər ˈɡæðərər]","kr":"헌터 개더러","example":"Early humans lived as hunter gatherers.","exampleKr":"초기 인류는 수렵 채집인으로 살았다."},{"id":"d2-89","day":2,"word":"sophisticated","meaning":"잘 발달된, 복잡한","ipa":"[səˈfɪstɪkeɪtɪd]","kr":"서피스티케이티드","example":"The software has a sophisticated design.","exampleKr":"그 소프트웨어는 정교한 설계를 가지고 있다.","roots":"soph(지혜, 그리스어 sophos) + -isticate(동사형) + -ed → 정교하게 다듬어진, 복잡한"},{"id":"d2-90","day":2,"word":"cooperative","meaning":"협력적인","ipa":"[koʊˈɑːpərətɪv]","kr":"코우아퍼러티브","example":"The two nations formed a cooperative alliance.","exampleKr":"두 나라는 협력적인 동맹을 맺었다.","roots":"co-(함께) + oper(일하다, 라틴어 operari) + -ative → 함께 일하는, 협력적인"},{"id":"d2-91","day":2,"word":"in turn","meaning":"그 결과, 차례로","ipa":"[ɪn tɜːrn]","kr":"인 턴","example":"She helped him, and he, in turn, helped her.","exampleKr":"그녀가 그를 도왔고, 그 결과 그도 그녀를 도왔다."},{"id":"d2-92","day":2,"word":"by turns","meaning":"차례로","ipa":"[baɪ tɜːrnz]","kr":"바이 턴즈","example":"The weather was by turns sunny and rainy.","exampleKr":"날씨는 차례로 맑았다 비가 왔다."},{"id":"d2-93","day":2,"word":"empathetic","meaning":"공감할 수 있는","ipa":"[ˌempəˈθetɪk]","kr":"엠퍼세틱","example":"A good nurse is patient and empathetic.","exampleKr":"좋은 간호사는 인내심 있고 공감할 수 있다.","roots":"em-(안으로, 그리스어 en-) + path(느낌, 그리스어 pathos) + -etic → 안으로 느껴 들어가는, 공감하는"},{"id":"d2-94","day":2,"word":"instinct","meaning":"본능","ipa":"[ˈɪnstɪŋkt]","kr":"인스팅트","example":"Her first instinct was to run.","exampleKr":"그녀의 첫 본능은 도망치는 것이었다.","roots":"in-(안으로) + stinct(찌르다, 라틴어 stinguere) → 안에서 찔러 일어나는 충동, 본능"},{"id":"d2-95","day":2,"word":"stir","meaning":"불러일으키다, 환기하다","ipa":"[stɜːr]","kr":"스터","example":"The speech stirred strong emotions in the crowd.","exampleKr":"그 연설은 군중 사이에 강한 감정을 불러일으켰다."},{"id":"d2-96","day":2,"word":"companion","meaning":"동료, 친구","ipa":"[kəmˈpænjən]","kr":"컴패니언","example":"The dog became his loyal companion.","exampleKr":"그 개는 그의 충직한 동료가 되었다.","roots":"com-(함께) + pan(빵, 라틴어 panis) + -ion → 빵을 함께 나누는 사람, 동료"},{"id":"d2-97","day":2,"word":"performance","meaning":"행위, 수행","ipa":"[pərˈfɔːrməns]","kr":"퍼포먼스","example":"The team's performance improved this season.","exampleKr":"그 팀의 수행 능력은 이번 시즌에 향상되었다."},{"id":"d2-98","day":2,"word":"reproduction","meaning":"번식","ipa":"[ˌriːprəˈdʌkʃn]","kr":"리프러덕션","example":"Scientists study the reproduction of coral.","exampleKr":"과학자들은 산호의 번식을 연구한다.","roots":"re-(다시) + pro-(앞으로) + duct(이끌다, 라틴어 ducere) + -ion → 다시 앞으로 이끌어내는 것, 번식"},{"id":"d2-99","day":2,"word":"gossip","meaning":"수다, 험담","ipa":"[ˈɡɑːsɪp]","kr":"가십","example":"She avoids office gossip.","exampleKr":"그녀는 사무실 험담을 피한다."},{"id":"d2-100","day":2,"word":"phenomenon","meaning":"현상(pl.phenomena)","ipa":"[fəˈnɑːmɪnən]","kr":"퍼나머넌","example":"Climate change is a global phenomenon.","exampleKr":"기후 변화는 전 세계적인 현상이다.","roots":"phen(나타나다, 그리스어 phainein) + -omenon(명사형) → 나타나 보이는 것, 현상"},{"id":"d3-1","day":3,"word":"scale up","meaning":"(크기나 규모가)커지다","ipa":"[skeɪl ʌp]","kr":"스케일 업","example":"The company plans to scale up production next year.","exampleKr":"그 회사는 내년에 생산 규모를 키울 계획이다."},{"id":"d3-2","day":3,"word":"be accompanied by","meaning":"~을 수반하다","ipa":"[bi əˈkʌmpənid baɪ]","kr":"비 어컴퍼니드 바이","example":"Growth is often accompanied by growing pains.","exampleKr":"성장은 종종 성장통을 수반한다."},{"id":"d3-3","day":3,"word":"evolution","meaning":"진화, 발전","ipa":"[ˌevəˈluːʃn]","kr":"에벌루션","example":"Darwin's theory explains the evolution of species.","exampleKr":"다윈의 이론은 종의 진화를 설명한다.","roots":"e-(밖으로) + volu(구르다, 라틴어 volvere) + -tion(명사형) → 밖으로 굴러 나와 전개됨, 진화"},{"id":"d3-4","day":3,"word":"natural selection","meaning":"자연도태","ipa":"[ˈnætʃrəl sɪˈlekʃn]","kr":"내추럴 실렉션","example":"Natural selection favors traits that aid survival.","exampleKr":"자연도태는 생존에 도움이 되는 형질을 선호한다."},{"id":"d3-5","day":3,"word":"simplicity","meaning":"단순함","ipa":"[sɪmˈplɪsəti]","kr":"심플리서티","example":"The design is admired for its simplicity.","exampleKr":"그 디자인은 단순함으로 찬사를 받는다.","roots":"simpl(단순한, 라틴어 simplex) + -ity(명사형) → 단순한 상태"},{"id":"d3-6","day":3,"word":"complexity","meaning":"복잡함","ipa":"[kəmˈpleksəti]","kr":"컴플렉서티","example":"The complexity of the system surprised the engineers.","exampleKr":"그 시스템의 복잡함은 엔지니어들을 놀라게 했다.","roots":"com-(함께) + plex(엮다, 라틴어 plectere) + -ity(명사형) → 함께 엮여 복잡한 상태"},{"id":"d3-7","day":3,"word":"intricacy","meaning":"복잡함","ipa":"[ˈɪntrɪkəsi]","kr":"인트리커시","example":"The intricacy of the pattern took months to weave.","exampleKr":"그 무늬의 복잡함은 짜는 데 몇 달이 걸렸다.","roots":"in-(안에) + tric(장애물, 라틴어 tricae) + -acy(명사형) → 장애물이 얽혀 있음, 복잡함"},{"id":"d3-8","day":3,"word":"organism","meaning":"유기체","ipa":"[ˈɔːrɡənɪzəm]","kr":"오거니즘","example":"Every organism needs energy to survive.","exampleKr":"모든 유기체는 생존하기 위해 에너지가 필요하다.","roots":"organ(기관, 그리스어 organon) + -ism(명사형) → 기관들로 이루어진 것, 유기체"},{"id":"d3-9","day":3,"word":"dramatically","meaning":"극적으로","ipa":"[drəˈmætɪkli]","kr":"드러매티클리","example":"Sales dropped dramatically after the scandal.","exampleKr":"스캔들 이후 매출이 극적으로 감소했다.","roots":"dram(행하다, 그리스어 dran) + -a(명사형) + -tic(형용사형) + -ally(부사형) → 행해진 일처럼 극적으로"},{"id":"d3-10","day":3,"word":"skyscraper","meaning":"고층 건물, 마천루","ipa":"[ˈskaɪskreɪpər]","kr":"스카이스크레이퍼","example":"The skyscraper dominates the city skyline.","exampleKr":"그 고층 건물은 도시 스카이라인을 압도한다."},{"id":"d3-11","day":3,"word":"modest","meaning":"보통의, 수수한","ipa":"[ˈmɑːdɪst]","kr":"마디스트","example":"He lives in a modest apartment.","exampleKr":"그는 수수한 아파트에 산다."},{"id":"d3-12","day":3,"word":"underlying principle","meaning":"기본 원리","ipa":"[ˌʌndərˈlaɪɪŋ ˈprɪnsəpl]","kr":"언덜라잉 프린서플","example":"Fairness is the underlying principle of the rule.","exampleKr":"공정함이 그 규칙의 기본 원리다."},{"id":"d3-13","day":3,"word":"construction","meaning":"건축, 건설","ipa":"[kənˈstrʌkʃn]","kr":"컨스트럭션","example":"The construction of the bridge took two years.","exampleKr":"그 다리의 건설은 2년이 걸렸다.","roots":"con-(함께) + struct(짓다, 라틴어 struere) + -ion(명사형) → 함께 쌓아 지은 것"},{"id":"d3-14","day":3,"word":"mechanics","meaning":"역학, 기계학","ipa":"[məˈkænɪks]","kr":"머캐닉스","example":"He studies the mechanics of flight.","exampleKr":"그는 비행의 역학을 연구한다.","roots":"mechan(기계, 그리스어 mekhane) + -ics(학문) → 기계에 관한 학문"},{"id":"d3-15","day":3,"word":"distribution","meaning":"분배, 분포","ipa":"[ˌdɪstrɪˈbjuːʃn]","kr":"디스트리뷰션","example":"The company improved its product distribution.","exampleKr":"그 회사는 제품 분배를 개선했다.","roots":"dis-(각각으로) + tribu(나누어 주다, 라틴어 tribuere) + -tion(명사형) → 각각에게 나누어 줌"},{"id":"d3-16","day":3,"word":"outlet","meaning":"콘센트, 출구","ipa":"[ˈaʊtlet]","kr":"아웃렛","example":"Plug the lamp into the outlet.","exampleKr":"램프를 콘센트에 꽂아라."},{"id":"d3-17","day":3,"word":"water faucet","meaning":"수도꼭지","ipa":"[ˈwɔːtər ˈfɔːsɪt]","kr":"워터 포싯","example":"She turned off the water faucet.","exampleKr":"그녀는 수도꼭지를 잠갔다."},{"id":"d3-18","day":3,"word":"approximately","meaning":"거의","ipa":"[əˈprɑːksɪmətli]","kr":"어프록시머틀리","example":"The building is approximately fifty years old.","exampleKr":"그 건물은 대략 50년 되었다.","roots":"ap-(~쪽으로) + proxim(가까운, 라틴어 proximus) + -ate + -ly → 가까운 쪽으로"},{"id":"d3-19","day":3,"word":"similarly","meaning":"마찬가지로, 비슷하게","ipa":"[ˈsɪmɪlərli]","kr":"시밀럴리","example":"Similarly, the second experiment showed the same result.","exampleKr":"마찬가지로, 두 번째 실험도 같은 결과를 보였다.","roots":"simil(비슷한, 라틴어 similis) + -ar(형용사형) + -ly(부사형) → 비슷하게"},{"id":"d3-20","day":3,"word":"extraordinary","meaning":"놀랄 만한, 대단한","ipa":"[ɪkˈstrɔːrdəneri]","kr":"익스트로디너리","example":"She showed extraordinary courage during the crisis.","exampleKr":"그녀는 위기 동안 대단한 용기를 보였다.","roots":"extra-(밖의) + ordin(순서, 라틴어 ordo) + -ary(형용사형) → 보통 순서를 벗어난"},{"id":"d3-21","day":3,"word":"reflect","meaning":"반영하다, 반사하다","ipa":"[rɪˈflekt]","kr":"리플렉트","example":"The lake reflected the mountains perfectly.","exampleKr":"그 호수는 산을 완벽하게 반사했다.","roots":"re-(다시) + flect(구부리다, 라틴어 flectere) → 다시 구부려 비추다, 반영하다"},{"id":"d3-22","day":3,"word":"fundamental","meaning":"근본적인","ipa":"[ˌfʌndəˈmentl]","kr":"펀더멘틀","example":"Trust is fundamental to any relationship.","exampleKr":"신뢰는 모든 관계에 근본적이다.","roots":"fund(바닥, 라틴어 fundus) + -a + -ment(명사형) + -al(형용사형) → 바탕이 되는"},{"id":"d3-23","day":3,"word":"building block","meaning":"구성 요소","ipa":"[ˈbɪldɪŋ blɑːk]","kr":"빌딩 블록","example":"Proteins are the building blocks of life.","exampleKr":"단백질은 생명의 구성 요소다."},{"id":"d3-24","day":3,"word":"appreciably","meaning":"눈에 띄게, 상당히","ipa":"[əˈpriːʃəbli]","kr":"어프리셔블리","example":"Prices rose appreciably last quarter.","exampleKr":"지난 분기에 물가가 눈에 띄게 올랐다.","roots":"ap-(~쪽으로) + preci(값, 라틴어 pretium) + -able(형용사형) + -ly(부사형) → 값을 매길 수 있을 만큼, 눈에 띄게"},{"id":"d3-25","day":3,"word":"considerably","meaning":"상당히, 꽤","ipa":"[kənˈsɪdərəbli]","kr":"컨시더러블리","example":"Her health improved considerably after the surgery.","exampleKr":"그녀의 건강은 수술 후 상당히 좋아졌다.","roots":"con-(함께, 자세히) + sider(별, 라틴어 sidus) + -able + -ly → 별을 자세히 살펴보듯 꼼꼼히 헤아릴 만큼, 상당히"},{"id":"d3-26","day":3,"word":"substantially","meaning":"상당히","ipa":"[səbˈstænʃəli]","kr":"섭스탠셜리","example":"The budget was substantially reduced.","exampleKr":"예산이 상당히 삭감되었다.","roots":"sub-(아래에) + stan(서다, 라틴어 stare) + -tial(형용사형) + -ly(부사형) → 아래서 든든히 떠받칠 만큼, 상당히"},{"id":"d3-27","day":3,"word":"reasonably","meaning":"상당히","ipa":"[ˈriːznəbli]","kr":"리즈너블리","example":"The plan seems reasonably solid.","exampleKr":"그 계획은 상당히 견고해 보인다.","roots":"reason(이유, 라틴어 ratio) + -able(형용사형) + -ly(부사형) → 이치에 맞을 만큼"},{"id":"d3-28","day":3,"word":"significantly","meaning":"상당히","ipa":"[sɪɡˈnɪfɪkəntli]","kr":"시그니피컨틀리","example":"Traffic has significantly decreased this month.","exampleKr":"이번 달 교통량이 상당히 줄었다.","roots":"sign(표시, 라틴어 signum) + -i + fic(만들다, 라틴어 facere) + -ant + -ly → 뚜렷한 표시를 낼 만큼, 상당히"},{"id":"d3-29","day":3,"word":"author","meaning":"작가, 저자","ipa":"[ˈɔːθər]","kr":"오써","example":"She is the author of three novels.","exampleKr":"그녀는 소설 세 편의 저자다.","roots":"auct(만들어내다, 라틴어 augere) + -or(행위자 명사형) → 무언가를 만들어낸 사람"},{"id":"d3-30","day":3,"word":"intention","meaning":"의도","ipa":"[ɪnˈtenʃn]","kr":"인텐션","example":"His intention was to help, not to harm.","exampleKr":"그의 의도는 해치는 것이 아니라 돕는 것이었다.","roots":"in-(안으로) + tend(뻗다, 라틴어 tendere) + -ion(명사형) → 마음을 안으로 뻗침, 의도"},{"id":"d3-31","day":3,"word":"tremendously","meaning":"엄청나게","ipa":"[trəˈmendəsli]","kr":"트리멘더슬리","example":"The project helped the community tremendously.","exampleKr":"그 프로젝트는 지역 사회에 엄청나게 도움이 되었다.","roots":"tremend(떨릴 만한, 라틴어 tremere) + -ous(형용사형) + -ly(부사형) → 떨릴 만큼 엄청나게"},{"id":"d3-32","day":3,"word":"frustrating","meaning":"좌절감을 주는","ipa":"[ˈfrʌstreɪtɪŋ]","kr":"프러스트레이팅","example":"Waiting in traffic every day is frustrating.","exampleKr":"매일 교통 체증 속에서 기다리는 것은 좌절감을 준다.","roots":"frustra(헛되이, 라틴어 frustra) + -ate(동사형) + -ing → 헛되게 만드는, 좌절시키는"},{"id":"d3-33","day":3,"word":"place worth on","meaning":"~에 가치를 두다","ipa":"[pleɪs wɜːrθ ɑːn]","kr":"플레이스 워쓰 온","example":"She places a lot of worth on honesty.","exampleKr":"그녀는 정직함에 큰 가치를 둔다."},{"id":"d3-34","day":3,"word":"vaguely","meaning":"막연하게, 애매하게","ipa":"[ˈveɪɡli]","kr":"베이글리","example":"He vaguely remembered meeting her before.","exampleKr":"그는 전에 그녀를 만난 것을 막연하게 기억했다.","roots":"vag(떠돌다, 라틴어 vagari) + -ue + -ly(부사형) → 정처 없이 떠돌 듯 막연하게"},{"id":"d3-35","day":3,"word":"faintly","meaning":"희미하게","ipa":"[ˈfeɪntli]","kr":"페인틀리","example":"She smiled faintly at the joke.","exampleKr":"그녀는 그 농담에 희미하게 미소지었다."},{"id":"d3-36","day":3,"word":"dimly","meaning":"희미하게","ipa":"[ˈdɪmli]","kr":"딤리","example":"The room was dimly lit by candles.","exampleKr":"그 방은 촛불로 희미하게 밝혀져 있었다."},{"id":"d3-37","day":3,"word":"apprehend","meaning":"이해하다, 감지하다","ipa":"[ˌæprɪˈhend]","kr":"애프리헨드","example":"He struggled to apprehend the new concept.","exampleKr":"그는 새 개념을 이해하는 데 어려움을 겪었다.","roots":"ap-(~을 향해) + prehend(붙잡다, 라틴어 prehendere) → 붙잡아 이해하다"},{"id":"d3-38","day":3,"word":"comprehend","meaning":"이해하다","ipa":"[ˌkɑːmprɪˈhend]","kr":"캄프리헨드","example":"Young children can't fully comprehend death.","exampleKr":"어린아이들은 죽음을 완전히 이해할 수 없다.","roots":"com-(완전히) + prehend(붙잡다, 라틴어 prehendere) → 완전히 붙잡아 이해하다"},{"id":"d3-39","day":3,"word":"seize","meaning":"이해하다","ipa":"[siːz]","kr":"시즈","example":"It took a moment to seize the meaning.","exampleKr":"그 의미를 이해하는 데 잠시 걸렸다."},{"id":"d3-40","day":3,"word":"grasp","meaning":"이해하다","ipa":"[ɡræsp]","kr":"그래스프","example":"She quickly grasped the main idea.","exampleKr":"그녀는 핵심 아이디어를 빠르게 이해했다."},{"id":"d3-41","day":3,"word":"figure out","meaning":"이해하다","ipa":"[ˈfɪɡjər aʊt]","kr":"피겨 아웃","example":"He finally figured out the puzzle.","exampleKr":"그는 마침내 그 퍼즐을 이해했다."},{"id":"d3-42","day":3,"word":"presence","meaning":"존재, 실재","ipa":"[ˈprezns]","kr":"프레즌스","example":"Her calm presence reassured the team.","exampleKr":"그녀의 차분한 존재감은 팀을 안심시켰다.","roots":"prae-(앞에) + s(있다, 라틴어 esse) + -ence(명사형) → 앞에 있음, 존재"},{"id":"d3-43","day":3,"word":"absence","meaning":"부재","ipa":"[ˈæbsəns]","kr":"앱슨스","example":"His absence was noticed immediately.","exampleKr":"그의 부재는 즉시 눈에 띄었다.","roots":"ab-(떨어져) + s(있다, 라틴어 esse) + -ence(명사형) → 떨어져 있음, 부재"},{"id":"d3-44","day":3,"word":"nominal","meaning":"명의상의, 이름의","ipa":"[ˈnɑːmɪnl]","kr":"나미널","example":"He is the nominal head of the company.","exampleKr":"그는 그 회사의 명목상의 대표다.","roots":"nomin(이름, 라틴어 nomen) + -al(형용사형) → 이름뿐인, 명의상의"},{"id":"d3-45","day":3,"word":"admire","meaning":"감탄하다","ipa":"[ədˈmaɪər]","kr":"어드마이어","example":"Everyone admired her dedication.","exampleKr":"모두가 그녀의 헌신에 감탄했다.","roots":"ad-(~을 향해) + mir(놀라며 바라보다, 라틴어 mirari) → ~을 향해 놀라며 바라보다, 감탄하다"},{"id":"d3-46","day":3,"word":"jacket","meaning":"(책의)표지","ipa":"[ˈdʒækɪt]","kr":"재킷","example":"The book jacket features a striking illustration.","exampleKr":"그 책 표지는 인상적인 삽화를 담고 있다."},{"id":"d3-47","day":3,"word":"spine","meaning":"책등, 척추","ipa":"[spaɪn]","kr":"스파인","example":"The title is printed on the spine.","exampleKr":"제목이 책등에 인쇄되어 있다."},{"id":"d3-48","day":3,"word":"title page","meaning":"(책의)속표지","ipa":"[ˈtaɪtl peɪdʒ]","kr":"타이틀 페이지","example":"Check the title page for the publication date.","exampleKr":"속표지에서 출판일을 확인해라."},{"id":"d3-49","day":3,"word":"regularly","meaning":"보통은, 규칙적으로","ipa":"[ˈreɡjələrli]","kr":"레귤럴리","example":"She exercises regularly every morning.","exampleKr":"그녀는 매일 아침 규칙적으로 운동한다.","roots":"regul(자, 규칙, 라틴어 regula) + -ar(형용사형) + -ly(부사형) → 규칙에 맞게"},{"id":"d3-50","day":3,"word":"quote","meaning":"~의 말을 인용하다","ipa":"[kwoʊt]","kr":"쿼우트","example":"She quoted a famous poet in her speech.","exampleKr":"그녀는 연설에서 유명한 시인의 말을 인용했다."},{"id":"d3-51","day":3,"word":"athlete","meaning":"운동선수","ipa":"[ˈæθliːt]","kr":"애슬리트","example":"The athlete trained for years before the Olympics.","exampleKr":"그 운동선수는 올림픽 전에 수년간 훈련했다.","roots":"athl(경기, 그리스어 athlon) + -ete(행위자 명사형) → 경기를 하는 사람"},{"id":"d3-52","day":3,"word":"innate","meaning":"내재된, 타고난","ipa":"[ɪˈneɪt]","kr":"이네이트","example":"Curiosity is an innate human trait.","exampleKr":"호기심은 인간의 타고난 특성이다.","roots":"in-(안에) + nat(태어나다, 라틴어 nasci) + -e → 태어날 때부터 안에 있는"},{"id":"d3-53","day":3,"word":"intrinsic","meaning":"내재된, 타고난","ipa":"[ɪnˈtrɪnzɪk]","kr":"인트린직","example":"Money has no intrinsic value without trust.","exampleKr":"신뢰 없이는 돈은 내재된 가치가 없다.","roots":"intra-(안쪽의) + sec(따르다, 라틴어 secus) + -ic(형용사형) → 안쪽에 속하여 따르는"},{"id":"d3-54","day":3,"word":"inherent","meaning":"내재된, 타고난","ipa":"[ɪnˈherənt]","kr":"인헤런트","example":"There is an inherent risk in every investment.","exampleKr":"모든 투자에는 내재된 위험이 있다.","roots":"in-(안에) + haer(붙다, 라틴어 haerere) + -ent(형용사형) → 안에 붙어 있는"},{"id":"d3-55","day":3,"word":"implicit","meaning":"내재된, 타고난","ipa":"[ɪmˈplɪsɪt]","kr":"임플리싯","example":"There was an implicit agreement between them.","exampleKr":"그들 사이에는 암묵적인 합의가 있었다.","roots":"im-(안으로) + plic(접다, 라틴어 plicare) + -it(형용사형) → 안으로 접혀 들어간, 암묵적인"},{"id":"d3-56","day":3,"word":"hardwired","meaning":"내재된, 타고난","ipa":"[ˌhɑːrdˈwaɪərd]","kr":"하드와이어드","example":"Fear of loud noises seems hardwired in infants.","exampleKr":"큰 소리에 대한 두려움은 유아에게 타고난 것 같다."},{"id":"d3-57","day":3,"word":"indigenous","meaning":"내재된, 타고난","ipa":"[ɪnˈdɪdʒənəs]","kr":"인디저너스","example":"The plant is indigenous to South America.","exampleKr":"그 식물은 남미가 원산지다.","roots":"indi-(안에) + gen(태어나다, 라틴어 gignere) + -ous(형용사형) → 그 땅 안에서 태어난, 토착의"},{"id":"d3-58","day":3,"word":"preference","meaning":"선호","ipa":"[ˈprefrəns]","kr":"프레퍼런스","example":"She has a strong preference for tea over coffee.","exampleKr":"그녀는 커피보다 차를 강하게 선호한다.","roots":"prae-(먼저) + fer(나르다, 라틴어 ferre) + -ence(명사형) → 먼저 가져오는 것, 선호"},{"id":"d3-59","day":3,"word":"orientation","meaning":"(~을 지향하는)성향","ipa":"[ˌɔːriənˈteɪʃn]","kr":"오리엔테이션","example":"New students attend an orientation session.","exampleKr":"신입생들은 오리엔테이션 세션에 참석한다.","roots":"ori(뜨다, 라틴어 oriri) + -ent + -ation(명사형) → 해가 뜨는 쪽을 향함, 방향을 잡음"},{"id":"d3-60","day":3,"word":"come in contact with","meaning":"~과 접하게 되다","ipa":"[kʌm ɪn ˈkɑːntækt wɪð]","kr":"컴 인 컨택트 위드","example":"Wash your hands after coming in contact with the soil.","exampleKr":"흙과 접촉한 후 손을 씻어라."},{"id":"d3-61","day":3,"word":"consistently","meaning":"일관되게, 지속해서","ipa":"[kənˈsɪstəntli]","kr":"컨시스턴틀리","example":"She consistently arrives early to work.","exampleKr":"그녀는 일관되게 직장에 일찍 도착한다.","roots":"con-(함께) + sist(서다, 라틴어 sistere) + -ent + -ly → 함께 굳게 서있는, 일관되게"},{"id":"d3-62","day":3,"word":"constantly","meaning":"일관되게, 지속해서","ipa":"[ˈkɑːnstəntli]","kr":"칸스턴틀리","example":"He is constantly checking his phone.","exampleKr":"그는 지속적으로 휴대폰을 확인한다.","roots":"con-(함께) + stant(서다, 라틴어 stare) + -ly(부사형) → 함께 굳게 서 있는, 한결같이"},{"id":"d3-63","day":3,"word":"persistently","meaning":"일관되게, 지속해서","ipa":"[pərˈsɪstəntli]","kr":"퍼시스턴틀리","example":"The reporter persistently asked follow-up questions.","exampleKr":"그 기자는 지속적으로 후속 질문을 했다.","roots":"per-(끝까지) + sist(서다, 라틴어 sistere) + -ent + -ly → 끝까지 서 있는, 끈질기게"},{"id":"d3-64","day":3,"word":"coherently","meaning":"일관되게, 지속해서","ipa":"[koʊˈhɪrəntli]","kr":"코우히런틀리","example":"He explained the plan coherently.","exampleKr":"그는 그 계획을 일관되게 설명했다.","roots":"co-(함께) + here(붙다, 라틴어 haerere) + -nt + -ly → 함께 붙어 일관된"},{"id":"d3-65","day":3,"word":"praise","meaning":"칭찬","ipa":"[preɪz]","kr":"프레이즈","example":"The teacher gave the student high praise.","exampleKr":"선생님은 그 학생에게 큰 칭찬을 했다."},{"id":"d3-66","day":3,"word":"appraise","meaning":"평가하다","ipa":"[əˈpreɪz]","kr":"어프레이즈","example":"The jeweler appraised the ring's value.","exampleKr":"보석상은 그 반지의 가치를 평가했다.","roots":"ap-(~을 향해) + praise(값을 매기다, 라틴어 pretiare) → 값을 매기다, 평가하다"},{"id":"d3-67","day":3,"word":"recognition","meaning":"인정","ipa":"[ˌrekəɡˈnɪʃn]","kr":"레커그니션","example":"She finally received recognition for her work.","exampleKr":"그녀는 마침내 자신의 일에 대한 인정을 받았다.","roots":"re-(다시) + cogn(알다, 라틴어 cognoscere) + -ition(명사형) → 다시 알아봄, 인정"},{"id":"d3-68","day":3,"word":"foster","meaning":"기르다, 육성하다","ipa":"[ˈfɔːstər]","kr":"포스터","example":"The program fosters creativity in children.","exampleKr":"그 프로그램은 아이들의 창의성을 기른다."},{"id":"d3-69","day":3,"word":"be associated with","meaning":"~과 관련되어 있다","ipa":"[bi əˈsoʊsieɪtɪd wɪð]","kr":"비 어쏘시에이티드 위드","example":"Smoking is associated with lung disease.","exampleKr":"흡연은 폐 질환과 관련되어 있다."},{"id":"d3-70","day":3,"word":"mastery","meaning":"숙달","ipa":"[ˈmæstəri]","kr":"매스터리","example":"It takes years to achieve mastery of a language.","exampleKr":"언어의 숙달을 이루는 데는 수년이 걸린다.","roots":"master(스승, 라틴어 magister) + -y(명사형) → 스승의 경지에 이름, 숙달"},{"id":"d3-71","day":3,"word":"reward","meaning":"보상","ipa":"[rɪˈwɔːrd]","kr":"리워드","example":"Hard work often brings its own reward.","exampleKr":"노력은 종종 그 자체로 보상을 가져온다.","roots":"re-(다시) + ward(지켜보다, 고대 프랑스어 warder) → 다시 돌아보며 챙겨줌, 보상"},{"id":"d3-72","day":3,"word":"non selection","meaning":"미선발, 탈락","ipa":"[nɑːn sɪˈlekʃn]","kr":"논 실렉션","example":"Applicants were notified of their non selection by email.","exampleKr":"지원자들은 이메일로 탈락 통보를 받았다.","roots":"non-(부정) + se-(따로) + lect(고르다, 라틴어 legere) + -ion(명사형) → 따로 골라내지 않음, 미선발"},{"id":"d3-73","day":3,"word":"hand out","meaning":"~을 건네다","ipa":"[hænd aʊt]","kr":"핸드 아웃","example":"The teacher handed out the test papers.","exampleKr":"선생님은 시험지를 나눠주었다."},{"id":"d3-74","day":3,"word":"unequal","meaning":"불균등한","ipa":"[ʌnˈiːkwəl]","kr":"언이퀄","example":"The distribution of wealth is highly unequal.","exampleKr":"부의 분배는 매우 불균등하다.","roots":"un-(부정) + equal(같은, 라틴어 aequalis) → 같지 않은, 불균등한"},{"id":"d3-75","day":3,"word":"unjust","meaning":"불균등한","ipa":"[ʌnˈdʒʌst]","kr":"언저스트","example":"The court ruled the law unjust.","exampleKr":"법원은 그 법이 부당하다고 판결했다.","roots":"un-(부정) + just(올바른, 라틴어 justus) → 올바르지 않은, 불공정한"},{"id":"d3-76","day":3,"word":"flourish","meaning":"번성하다","ipa":"[ˈflɜːrɪʃ]","kr":"플러리시","example":"Small businesses flourished in the new market.","exampleKr":"작은 사업체들이 새 시장에서 번성했다.","roots":"flor(꽃 피다, 라틴어 florere) + -ish(동사형) → 꽃을 피우다, 번성하다"},{"id":"d3-77","day":3,"word":"thrive","meaning":"번성하다","ipa":"[θraɪv]","kr":"쓰라이브","example":"Plants thrive in warm, sunny climates.","exampleKr":"식물은 따뜻하고 햇살 좋은 기후에서 번성한다."},{"id":"d3-78","day":3,"word":"prosper","meaning":"번성하다","ipa":"[ˈprɑːspər]","kr":"프라스퍼","example":"The town prospered after the railroad arrived.","exampleKr":"철도가 들어온 후 그 마을은 번성했다.","roots":"pro-(~에 따라) + sper(희망, 라틴어 spes) → 바라던 대로 잘 되다, 번영하다"},{"id":"d3-79","day":3,"word":"endeavor","meaning":"수고, 노력, 애씀","ipa":"[ɪnˈdevər]","kr":"인데버","example":"Their endeavor to save the forest succeeded.","exampleKr":"숲을 구하려는 그들의 노력은 성공했다.","roots":"en-(~하게 만들다) + devoir(의무, 프랑스어, 라틴어 debere) → 의무를 다하려 애쓰다"},{"id":"d3-80","day":3,"word":"simplify","meaning":"단순화하다","ipa":"[ˈsɪmplɪfaɪ]","kr":"심플리파이","example":"The new app simplifies the checkout process.","exampleKr":"새 앱은 결제 과정을 단순화한다.","roots":"simpl(단순한, 라틴어 simplex) + -i + fy(만들다, 라틴어 facere) → 단순하게 만들다"},{"id":"d3-81","day":3,"word":"western","meaning":"서부 영화, 서부극","ipa":"[ˈwestərn]","kr":"웨스턴","example":"He loves watching old western films.","exampleKr":"그는 오래된 서부극 영화를 즐겨 본다."},{"id":"d3-82","day":3,"word":"convention","meaning":"관례","ipa":"[kənˈvenʃn]","kr":"컨벤션","example":"It is a convention to shake hands when greeting.","exampleKr":"인사할 때 악수를 하는 것이 관례다.","roots":"con-(함께) + vent(오다, 라틴어 venire) + -ion(명사형) → 함께 모여옴, 관습"},{"id":"d3-83","day":3,"word":"appearance","meaning":"외모","ipa":"[əˈpɪrəns]","kr":"어피어런스","example":"Her appearance changed a lot over the years.","exampleKr":"그녀의 외모는 몇 년 동안 많이 변했다.","roots":"ap-(~쪽으로) + par(보이다, 라틴어 parere) + -ance(명사형) → 겉으로 드러나 보이는 것"},{"id":"d3-84","day":3,"word":"manner","meaning":"(행동)방식","ipa":"[ˈmænər]","kr":"매너","example":"He spoke in a calm manner.","exampleKr":"그는 차분한 방식으로 말했다.","roots":"man(손, 라틴어 manus) + -ner → 손으로 다루는 방식"},{"id":"d3-85","day":3,"word":"sidekick","meaning":"조수, 동료","ipa":"[ˈsaɪdkɪk]","kr":"사이드킥","example":"Every hero needs a loyal sidekick.","exampleKr":"모든 영웅에게는 충직한 조수가 필요하다."},{"id":"d3-86","day":3,"word":"villain","meaning":"악당, 악역","ipa":"[ˈvɪlən]","kr":"빌런","example":"The villain was defeated in the final scene.","exampleKr":"그 악당은 마지막 장면에서 패배했다.","roots":"vill(농장, 라틴어 villa) + -ain → 농장에 사는 사람, (경멸적으로) 악당"},{"id":"d3-87","day":3,"word":"on sight","meaning":"보자마자","ipa":"[ɑːn saɪt]","kr":"온 사이트","example":"Security recognized him on sight.","exampleKr":"보안 요원은 그를 보자마자 알아봤다."},{"id":"d3-88","day":3,"word":"assume","meaning":"생각하다, 추정하다","ipa":"[əˈsuːm]","kr":"어숨","example":"Don't assume he agrees with you.","exampleKr":"그가 너에게 동의한다고 추정하지 마라.","roots":"as-(~에) + sum(취하다, 라틴어 sumere) → 자기 것으로 취하다, 떠맡다"},{"id":"d3-89","day":3,"word":"violate","meaning":"저버리다, 위반하다","ipa":"[ˈvaɪəleɪt]","kr":"바이얼레이트","example":"The company violated environmental regulations.","exampleKr":"그 회사는 환경 규정을 위반했다.","roots":"viol(폭력, 라틴어 vis) + -ate(동사형) → 폭력을 가하다, 위반하다"},{"id":"d3-90","day":3,"word":"familiarity","meaning":"익숙함","ipa":"[fəˌmɪliˈærəti]","kr":"퍼밀리애러티","example":"His familiarity with the topic impressed everyone.","exampleKr":"그 주제에 대한 그의 익숙함은 모두를 감탄시켰다.","roots":"famili(가족, 라틴어 familia) + -ar(형용사형) + -ity(명사형) → 가족처럼 친숙한 상태"},{"id":"d3-91","day":3,"word":"establish","meaning":"확립하다","ipa":"[ɪˈstæblɪʃ]","kr":"이스태블리시","example":"They worked hard to establish trust.","exampleKr":"그들은 신뢰를 확립하기 위해 열심히 노력했다.","roots":"e-(밖으로) + stabl(세우다, 라틴어 stabilire) + -ish(동사형) → 굳건히 세우다, 확립하다"},{"id":"d3-92","day":3,"word":"intensify","meaning":"강화하다","ipa":"[ɪnˈtensɪfaɪ]","kr":"인텐시파이","example":"The storm is expected to intensify tonight.","exampleKr":"그 폭풍은 오늘 밤 강화될 것으로 예상된다.","roots":"intens(팽팽한, 라틴어 intendere) + -i + fy(만들다) → 팽팽하게 만들다, 강화하다"},{"id":"d3-93","day":3,"word":"reinforce","meaning":"강화하다","ipa":"[ˌriːɪnˈfɔːrs]","kr":"리인포스","example":"The lesson reinforced what she already knew.","exampleKr":"그 수업은 그녀가 이미 알던 것을 강화했다.","roots":"re-(다시) + force(힘, 라틴어 fortis) → 다시 힘을 더하다, 강화하다"},{"id":"d3-94","day":3,"word":"innovation","meaning":"혁신","ipa":"[ˌɪnəˈveɪʃn]","kr":"이노베이션","example":"The company is known for constant innovation.","exampleKr":"그 회사는 끊임없는 혁신으로 알려져 있다.","roots":"in-(안으로) + nov(새로운, 라틴어 novus) + -ation(명사형) → 안에 새로운 것을 들임, 혁신"},{"id":"d3-95","day":3,"word":"decade","meaning":"십 년","ipa":"[ˈdekeɪd]","kr":"데케이드","example":"The city has changed a lot in the last decade.","exampleKr":"그 도시는 지난 십 년 동안 많이 변했다.","roots":"dec(10, 그리스어 deka) + -ade → 십 년"},{"id":"d3-96","day":3,"word":"integral","meaning":"필수 불가결한","ipa":"[ˈɪntɪɡrəl]","kr":"인티그럴","example":"Trust is integral to a healthy relationship.","exampleKr":"신뢰는 건강한 관계에 필수 불가결하다.","roots":"in-(부정) + teg(손대다, 라틴어 tangere) + -ral(형용사형) → 손대지 않아 온전한, 필수 불가결한"},{"id":"d3-97","day":3,"word":"keenly","meaning":"예민하게, 열심히","ipa":"[ˈkiːnli]","kr":"킨리","example":"She is keenly aware of the risks.","exampleKr":"그녀는 그 위험을 예민하게 인식하고 있다."},{"id":"d3-98","day":3,"word":"responsive","meaning":"반응하는, 대답하는","ipa":"[rɪˈspɑːnsɪv]","kr":"리스판시브","example":"The new manager is very responsive to feedback.","exampleKr":"새 매니저는 피드백에 매우 잘 반응한다.","roots":"re-(다시) + spons(약속하다, 라틴어 spondere) + -ive(형용사형) → 다시 답하는, 반응하는"},{"id":"d3-99","day":3,"word":"refinement","meaning":"정제, 순화","ipa":"[rɪˈfaɪnmənt]","kr":"리파인먼트","example":"The design went through several rounds of refinement.","exampleKr":"그 디자인은 여러 차례의 정제 과정을 거쳤다.","roots":"re-(다시) + fin(순수한, 고대 프랑스어 fin) + -e + -ment(명사형) → 다시 다듬어 순수하게 함, 정제"},{"id":"d3-100","day":3,"word":"exceed","meaning":"넘어서다, 능가하다","ipa":"[ɪkˈsiːd]","kr":"익시드","example":"Sales exceeded expectations this year.","exampleKr":"올해 매출이 기대치를 넘어섰다.","roots":"ex-(밖으로) + ced(가다, 라틴어 cedere) → 밖으로 넘어가다, 초과하다"},{"id":"d4-1","day":4,"word":"obsessed about","meaning":"~에 사로잡힌","ipa":"[əbˈsest əˈbaʊt]","kr":"업세스트 어바웃","example":"He is obsessed about keeping his desk clean.","exampleKr":"그는 책상을 깨끗하게 유지하는 것에 사로잡혀 있다.","roots":"ob-(맞서) + sess(앉다, 라틴어 sedere) → 맞서 눌러앉다, 사로잡히다"},{"id":"d4-2","day":4,"word":"swamp","meaning":"늪, 습지","ipa":"[swɑːmp]","kr":"스왐프","example":"Alligators live in the swamp.","exampleKr":"악어는 늪에 산다."},{"id":"d4-3","day":4,"word":"elusive","meaning":"(기억)흐릿한, 애매한","ipa":"[iˈluːsɪv]","kr":"일루시브","example":"The memory of that day remained elusive.","exampleKr":"그날의 기억은 흐릿한 채로 남았다.","roots":"e-(밖으로) + lus(놀다, 라틴어 ludere) + -ive → 놀듯이 빠져나가는, 잡히지 않는"},{"id":"d4-4","day":4,"word":"indefinable","meaning":"애매한","ipa":"[ˌɪndɪˈfaɪnəbl]","kr":"인디파이너블","example":"There was an indefinable sadness in her voice.","exampleKr":"그녀의 목소리에는 애매한 슬픔이 있었다.","roots":"in-(부정) + de-(완전히) + fin(경계, 라틴어 finis) + -able → 경계를 지을 수 없는"},{"id":"d4-5","day":4,"word":"ambiguous","meaning":"애매한","ipa":"[æmˈbɪɡjuəs]","kr":"앰비규어스","example":"His answer was deliberately ambiguous.","exampleKr":"그의 대답은 일부러 애매했다.","roots":"ambi-(양쪽으로) + ig(몰다, 라틴어 agere) → 양쪽으로 오가는, 애매한"},{"id":"d4-6","day":4,"word":"field mark","meaning":"눈에 띄는 특징","ipa":"[fiːld mɑːrk]","kr":"필드 마크","example":"Birdwatchers look for field marks to identify species.","exampleKr":"조류 관찰자들은 종을 식별하기 위해 눈에 띄는 특징을 찾는다."},{"id":"d4-7","day":4,"word":"vivid","meaning":"선명한","ipa":"[ˈvɪvɪd]","kr":"비비드","example":"She has vivid memories of her childhood home.","exampleKr":"그녀는 어린 시절 집에 대한 선명한 기억을 가지고 있다.","roots":"viv(살다, 라틴어 vivere) + -id → 생생하게 살아있는"},{"id":"d4-8","day":4,"word":"distinct","meaning":"뚜렷한","ipa":"[dɪˈstɪŋkt]","kr":"디스팅트","example":"The two flavors are quite distinct.","exampleKr":"두 맛은 꽤 뚜렷하게 다르다.","roots":"di-(따로) + sting(찌르다, 라틴어 stinguere) → 따로 떼어 표시한, 뚜렷한"},{"id":"d4-9","day":4,"word":"plain","meaning":"명백한","ipa":"[pleɪn]","kr":"플레인","example":"It was plain that he was upset.","exampleKr":"그가 화났다는 것은 명백했다."},{"id":"d4-10","day":4,"word":"evident","meaning":"명백한","ipa":"[ˈevɪdənt]","kr":"에비던트","example":"Her talent was evident from an early age.","exampleKr":"그녀의 재능은 어릴 때부터 명백했다.","roots":"e-(밖으로) + vid(보다, 라틴어 videre) + -ent → 밖으로 드러나 보이는"},{"id":"d4-11","day":4,"word":"manifest","meaning":"명백한","ipa":"[ˈmænɪfest]","kr":"매니페스트","example":"His anger began to manifest in his tone.","exampleKr":"그의 분노는 말투에서 드러나기 시작했다.","roots":"mani(손, 라틴어 manus) + fest(잡힌, 라틴어 -festus) → 손에 잡힐 만큼 명백한"},{"id":"d4-12","day":4,"word":"conspicuous","meaning":"명백한","ipa":"[kənˈspɪkjuəs]","kr":"컨스피큐어스","example":"The red car was conspicuous in the parking lot.","exampleKr":"그 빨간 차는 주차장에서 눈에 띄었다.","roots":"con-(강조) + spic(보다, 라틴어 specere) + -uous → 눈에 확 띄게 보이는"},{"id":"d4-13","day":4,"word":"obvious","meaning":"명백한","ipa":"[ˈɑːbviəs]","kr":"아비어스","example":"It was obvious that she was tired.","exampleKr":"그녀가 피곤하다는 것은 명백했다.","roots":"ob-(앞에) + vi(길, 라틴어 via) + -ous → 길 앞에 놓여 잘 보이는"},{"id":"d4-14","day":4,"word":"comprehend","meaning":"이해하다","ipa":"[ˌkɑːmprɪˈhend]","kr":"캄프리헨드","example":"He struggled to comprehend the instructions.","exampleKr":"그는 설명을 이해하는 데 어려움을 겪었다.","roots":"com-(함께) + prehend(붙잡다, 라틴어 prehendere) → 함께 붙잡아 이해하다"},{"id":"d4-15","day":4,"word":"passion","meaning":"열정","ipa":"[ˈpæʃn]","kr":"패션","example":"She has a passion for painting.","exampleKr":"그녀는 그림에 대한 열정이 있다.","roots":"pass(겪다, 라틴어 pati) + -ion → 겪어내는 강한 감정, 열정"},{"id":"d4-16","day":4,"word":"enthusiasm","meaning":"열정","ipa":"[ɪnˈθuːziæzəm]","kr":"인쑤지애즘","example":"The team showed great enthusiasm for the project.","exampleKr":"그 팀은 그 프로젝트에 큰 열정을 보였다.","roots":"en-(안에) + theos(신, 그리스어 theos) + -iasm(상태) → 신이 들어온 상태, 열광"},{"id":"d4-17","day":4,"word":"eagerness","meaning":"열정","ipa":"[ˈiːɡərnəs]","kr":"이거너스","example":"He answered with obvious eagerness.","exampleKr":"그는 분명한 열정으로 대답했다.","roots":"eager(날카로운, 고프랑스어 aigre) + -ness → 날카롭게 원하는 마음, 열정"},{"id":"d4-18","day":4,"word":"apathy","meaning":"무관심","ipa":"[ˈæpəθi]","kr":"애퍼씨","example":"Voter apathy is a growing concern.","exampleKr":"유권자의 무관심은 커지는 우려 사항이다.","roots":"a-(없음, 그리스어) + path(감정, 그리스어 pathos) + -y → 감정이 없음, 무관심"},{"id":"d4-19","day":4,"word":"accumulate","meaning":"모으다, 축적하다","ipa":"[əˈkjuːmjəleɪt]","kr":"어큐멸레이트","example":"Dust accumulated on the shelf.","exampleKr":"먼지가 선반에 쌓였다.","roots":"ac-(~쪽으로) + cumul(더미, 라틴어 cumulus) + -ate → 더미로 쌓다"},{"id":"d4-20","day":4,"word":"pile up","meaning":"모으다, 축적하다","ipa":"[paɪl ʌp]","kr":"파일 업","example":"Work piled up while she was on vacation.","exampleKr":"그녀가 휴가 간 사이 일이 쌓였다."},{"id":"d4-21","day":4,"word":"heap up","meaning":"모으다, 축적하다","ipa":"[hiːp ʌp]","kr":"힙 업","example":"Leaves heaped up in the corner of the yard.","exampleKr":"나뭇잎이 마당 구석에 쌓였다."},{"id":"d4-22","day":4,"word":"assemble","meaning":"모으다, 축적하다","ipa":"[əˈsembl]","kr":"어셈블","example":"Workers assembled the furniture quickly.","exampleKr":"작업자들은 가구를 빠르게 조립했다.","roots":"as-(~쪽으로) + sembl(같은, 라틴어 simul) + -e → 같은 쪽으로 모으다"},{"id":"d4-23","day":4,"word":"populate","meaning":"가득 채우다","ipa":"[ˈpɑːpjuleɪt]","kr":"파퓰레이트","example":"Robots may soon populate our homes.","exampleKr":"로봇이 곧 우리 집을 채울지도 모른다.","roots":"popul(사람들, 라틴어 populus) + -ate → 사람들로 채우다"},{"id":"d4-24","day":4,"word":"attic","meaning":"다락","ipa":"[ˈætɪk]","kr":"애틱","example":"They found old photos in the attic.","exampleKr":"그들은 다락에서 오래된 사진을 발견했다."},{"id":"d4-25","day":4,"word":"distinct from","meaning":"~과 다른","ipa":"[dɪˈstɪŋkt frəm]","kr":"디스팅트 프럼","example":"This case is distinct from the previous one.","exampleKr":"이 사건은 이전 사건과 다르다."},{"id":"d4-26","day":4,"word":"compress","meaning":"압축하다","ipa":"[kəmˈpres]","kr":"컴프레스","example":"The software compresses large files.","exampleKr":"그 소프트웨어는 큰 파일을 압축한다.","roots":"com-(함께) + press(누르다, 라틴어 premere) → 함께 눌러 압축하다"},{"id":"d4-27","day":4,"word":"specifically","meaning":"구체적으로 말하자면","ipa":"[spəˈsɪfɪkli]","kr":"스퍼시피클리","example":"She specifically asked for a window seat.","exampleKr":"그녀는 구체적으로 창가 좌석을 요청했다.","roots":"speci(모습, 라틴어 species) + -fic(만들다, 라틴어 facere) + -ally → 특정한 모습으로 만들어"},{"id":"d4-28","day":4,"word":"pause","meaning":"짧은 멈춤","ipa":"[pɔːz]","kr":"포즈","example":"There was a brief pause before he answered.","exampleKr":"그가 대답하기 전에 짧은 멈춤이 있었다."},{"id":"d4-29","day":4,"word":"characterize","meaning":"특징짓다","ipa":"[ˈkærəktəraɪz]","kr":"캐릭터라이즈","example":"Kindness characterizes her personality.","exampleKr":"친절함이 그녀의 성격을 특징짓는다.","roots":"character(성격, 그리스어 kharakter) + -ize → 성격을 부여하다, 특징짓다"},{"id":"d4-30","day":4,"word":"accent","meaning":"특색, 특성","ipa":"[ˈæksent]","kr":"액센트","example":"Humor is an accent of his writing style.","exampleKr":"유머는 그의 글쓰기 스타일의 특징이다.","roots":"ac-(~에) + cent(노래, 라틴어 canere) → 소리에 얹은 노래, 강세"},{"id":"d4-31","day":4,"word":"namely","meaning":"즉, 다시 말해","ipa":"[ˈneɪmli]","kr":"네임리","example":"Two students, namely Tom and Anna, were absent.","exampleKr":"두 학생, 즉 톰과 애나가 결석했다."},{"id":"d4-32","day":4,"word":"to put it another way","meaning":"다른 말로 하자면","ipa":"[tuː pʊt ɪt əˈnʌðər weɪ]","kr":"투 풋 잇 어나더 웨이","example":"To put it another way, we need more time.","exampleKr":"다른 말로 하자면, 우리는 더 많은 시간이 필요하다."},{"id":"d4-33","day":4,"word":"in other words","meaning":"다른 말로 하자면","ipa":"[ɪn ˈʌðər wɜːrdz]","kr":"인 아더 워즈","example":"In other words, the plan failed.","exampleKr":"다른 말로 하자면, 그 계획은 실패했다."},{"id":"d4-34","day":4,"word":"that is (to say)","meaning":"말하자면","ipa":"[ðæt ɪz tuː seɪ]","kr":"댓 이즈 투 세이","example":"He quit, that is to say, he was fired.","exampleKr":"그는 그만뒀다, 말하자면, 해고당했다."},{"id":"d4-35","day":4,"word":"bold","meaning":"굵은 활자체의","ipa":"[boʊld]","kr":"보울드","example":"The headline was printed in bold letters.","exampleKr":"그 헤드라인은 굵은 활자체로 인쇄되었다."},{"id":"d4-36","day":4,"word":"boxed","meaning":"네모 표시된","ipa":"[bɑːkst]","kr":"박스트","example":"Important terms are boxed in the textbook.","exampleKr":"중요한 용어는 교재에서 네모 표시되어 있다."},{"id":"d4-37","day":4,"word":"temporal","meaning":"시간의","ipa":"[ˈtempərəl]","kr":"템퍼럴","example":"The story mixes temporal and spatial elements.","exampleKr":"그 이야기는 시간적 요소와 공간적 요소를 섞는다.","roots":"tempor(시간, 라틴어 tempus) + -al → 시간에 관한"},{"id":"d4-38","day":4,"word":"dimension","meaning":"특성","ipa":"[dɪˈmenʃn]","kr":"디멘션","example":"Honesty adds a new dimension to their friendship.","exampleKr":"정직함은 그들의 우정에 새로운 특성을 더한다.","roots":"di-(나누어) + mens(재다, 라틴어 metiri) + -ion → 나누어 잰 것, 크기의 특성"},{"id":"d4-39","day":4,"word":"performer","meaning":"연기자","ipa":"[pərˈfɔːrmər]","kr":"퍼포머","example":"The performer received a standing ovation.","exampleKr":"그 연기자는 기립 박수를 받았다."},{"id":"d4-40","day":4,"word":"graphic","meaning":"생생하게 표현된","ipa":"[ˈɡræfɪk]","kr":"그래픽","example":"The novel contains graphic descriptions of war.","exampleKr":"그 소설은 전쟁에 대한 생생한 묘사를 담고 있다.","roots":"graph(그리다, 그리스어 graphein) + -ic → 그림처럼 생생하게 그려진"},{"id":"d4-41","day":4,"word":"metaphor","meaning":"비유적 표현","ipa":"[ˈmetəfər]","kr":"메터퍼","example":"\"Time is money\" is a common metaphor.","exampleKr":"\"시간은 돈이다\"는 흔한 비유적 표현이다.","roots":"meta-(넘어서) + phor(옮기다, 그리스어 pherein) → 의미를 넘어 옮기는 것, 비유"},{"id":"d4-42","day":4,"word":"analogy","meaning":"비유","ipa":"[əˈnælədʒi]","kr":"어낼러지","example":"The teacher used an analogy to explain gravity.","exampleKr":"선생님은 중력을 설명하기 위해 비유를 사용했다.","roots":"ana-(~에 따라) + log(비율, 그리스어 logos) + -y → 비율에 따라 견주는 것, 비유"},{"id":"d4-43","day":4,"word":"rapid","meaning":"빠른, 신속한","ipa":"[ˈræpɪd]","kr":"래피드","example":"The city experienced rapid growth.","exampleKr":"그 도시는 빠른 성장을 경험했다.","roots":"rap(휩쓸다, 라틴어 rapere) + -id → 휩쓸어가듯 빠른"},{"id":"d4-44","day":4,"word":"swift","meaning":"빠른, 신속한","ipa":"[swɪft]","kr":"스위프트","example":"The team gave a swift response to the crisis.","exampleKr":"그 팀은 위기에 신속한 대응을 했다."},{"id":"d4-45","day":4,"word":"in the abstract","meaning":"일반적인 의미로는","ipa":"[ɪn ði ˈæbstrækt]","kr":"인 디 앱스트랙트","example":"The idea sounds good in the abstract.","exampleKr":"그 아이디어는 일반적인 의미로는 좋게 들린다."},{"id":"d4-46","day":4,"word":"critic","meaning":"비평가","ipa":"[ˈkrɪtɪk]","kr":"크리틱","example":"The film received praise from critics.","exampleKr":"그 영화는 비평가들의 찬사를 받았다.","roots":"krit(가려내다, 그리스어 krinein) + -ic → 가려내어 판단하는 사람, 비평가"},{"id":"d4-47","day":4,"word":"demand","meaning":"요구하다","ipa":"[dɪˈmænd]","kr":"디맨드","example":"The job demands strong communication skills.","exampleKr":"그 직업은 강한 의사소통 능력을 요구한다.","roots":"de-(강하게) + mand(맡기다, 라틴어 mandare) → 강하게 맡겨 요구하다"},{"id":"d4-48","day":4,"word":"call for","meaning":"요구하다","ipa":"[kɔːl fɔːr]","kr":"콜 포","example":"The situation calls for immediate action.","exampleKr":"그 상황은 즉각적인 조치를 요구한다."},{"id":"d4-49","day":4,"word":"ask for","meaning":"요구하다","ipa":"[æsk fɔːr]","kr":"애스크 포","example":"He asked for a raise.","exampleKr":"그는 임금 인상을 요구했다."},{"id":"d4-50","day":4,"word":"require","meaning":"요구하다","ipa":"[rɪˈkwaɪər]","kr":"리콰이어","example":"The course requires a lot of reading.","exampleKr":"그 과정은 많은 독서를 요구한다.","roots":"re-(다시) + quir(구하다, 라틴어 quaerere) → 다시 구하다, 요구하다"},{"id":"d4-51","day":4,"word":"sociologist","meaning":"사회학자","ipa":"[ˌsoʊsiˈɑːlədʒɪst]","kr":"소시알러지스트","example":"The sociologist studied urban migration patterns.","exampleKr":"그 사회학자는 도시 이주 패턴을 연구했다.","roots":"soci(사회, 라틴어 socius) + log(학문, 그리스어 logos) + -ist → 사회를 연구하는 사람"},{"id":"d4-52","day":4,"word":"correct","meaning":"바로잡다","ipa":"[kəˈrekt]","kr":"커렉트","example":"She corrected the mistake in the report.","exampleKr":"그녀는 보고서의 실수를 바로잡았다.","roots":"cor-(완전히) + rect(바르게 하다, 라틴어 regere) → 완전히 바로잡다"},{"id":"d4-53","day":4,"word":"claim","meaning":"주장","ipa":"[kleɪm]","kr":"클레임","example":"He made a bold claim without evidence.","exampleKr":"그는 증거 없이 대담한 주장을 했다."},{"id":"d4-54","day":4,"word":"insistence","meaning":"주장","ipa":"[ɪnˈsɪstəns]","kr":"인시스턴스","example":"Despite her insistence, they refused to change plans.","exampleKr":"그녀의 주장에도 불구하고, 그들은 계획을 바꾸기를 거부했다.","roots":"in-(위에) + sist(서다, 라틴어 sistere) + -ence → 위에 서서 굽히지 않음, 주장"},{"id":"d4-55","day":4,"word":"argument","meaning":"주장","ipa":"[ˈɑːrɡjumənt]","kr":"아규먼트","example":"They had a heated argument about money.","exampleKr":"그들은 돈 문제로 격렬한 다툼을 벌였다.","roots":"argu(밝히다, 라틴어 arguere) + -ment → 밝혀 논하는 것, 주장"},{"id":"d4-56","day":4,"word":"significant","meaning":"중요한","ipa":"[sɪɡˈnɪfɪkənt]","kr":"시그니피컨트","example":"The results showed a significant improvement.","exampleKr":"그 결과는 중요한 향상을 보였다.","roots":"sign(표시, 라틴어 signum) + -fic(만들다, 라틴어 facere) + -ant → 표시를 만들어내는, 중요한"},{"id":"d4-57","day":4,"word":"notable","meaning":"두드러진","ipa":"[ˈnoʊtəbl]","kr":"노터블","example":"There were several notable changes this year.","exampleKr":"올해 몇 가지 두드러진 변화가 있었다.","roots":"not(알다, 라틴어 notare) + -able → 알아볼 만한, 두드러진"},{"id":"d4-58","day":4,"word":"laboratory","meaning":"실험실","ipa":"[ˈlæbrətɔːri]","kr":"래브러토리","example":"The samples were tested in a laboratory.","exampleKr":"그 샘플들은 실험실에서 검사되었다.","roots":"labor(일하다, 라틴어 laborare) + -atory → 일하는 곳, 실험실"},{"id":"d4-59","day":4,"word":"bias","meaning":"편향, 편견","ipa":"[ˈbaɪəs]","kr":"바이어스","example":"The study may contain some bias.","exampleKr":"그 연구는 어느 정도 편향을 포함할 수 있다."},{"id":"d4-60","day":4,"word":"stereotype","meaning":"고정관념","ipa":"[ˈsteriətaɪp]","kr":"스테리어타입","example":"The movie relies on outdated stereotypes.","exampleKr":"그 영화는 낡은 고정관념에 의존한다.","roots":"stereo(단단한, 그리스어 stereos) + type(틀, 그리스어 typos) → 고정된 틀, 고정관념"},{"id":"d4-61","day":4,"word":"endeavor","meaning":"노력","ipa":"[ɪnˈdevər]","kr":"인데버","example":"Their endeavor to build the bridge took ten years.","exampleKr":"그 다리를 건설하려는 그들의 노력은 10년이 걸렸다.","roots":"en-(~하게 만들다) + devoir(의무, 고프랑스어 devoir) → 의무로 여겨 애쓰다, 노력"},{"id":"d4-62","day":4,"word":"par excellence","meaning":"최상의","ipa":"[pɑːr ˈeksələns]","kr":"파 엑설런스","example":"He is a chef par excellence.","exampleKr":"그는 최고의 셰프다."},{"id":"d4-63","day":4,"word":"stress","meaning":"강조하다","ipa":"[stres]","kr":"스트레스","example":"The report stresses the need for reform.","exampleKr":"그 보고서는 개혁의 필요성을 강조한다."},{"id":"d4-64","day":4,"word":"underline","meaning":"강조하다","ipa":"[ˌʌndərˈlaɪn]","kr":"언덜라인","example":"She underlined the key points in the text.","exampleKr":"그녀는 텍스트에서 핵심 사항을 강조했다.","roots":"under-(아래) + line(선, 라틴어 linea) → 아래에 선을 그어 강조하다"},{"id":"d4-65","day":4,"word":"measurement","meaning":"측정","ipa":"[ˈmeʒərmənt]","kr":"메저먼트","example":"Precise measurement is needed for the design.","exampleKr":"그 설계에는 정확한 측정이 필요하다.","roots":"measure(재다, 라틴어 mensurare) + -ment → 잰 것, 측정"},{"id":"d4-66","day":4,"word":"rule out","meaning":"~을 배제하다","ipa":"[ruːl aʊt]","kr":"룰 아웃","example":"Doctors ruled out any serious illness.","exampleKr":"의사들은 심각한 질병을 배제했다."},{"id":"d4-67","day":4,"word":"exclude","meaning":"~을 배제하다","ipa":"[ɪkˈskluːd]","kr":"익스클루드","example":"The offer excludes shipping costs.","exampleKr":"그 제안은 배송비를 배제한다.","roots":"ex-(밖으로) + clud(닫다, 라틴어 claudere) → 밖으로 닫아 배제하다"},{"id":"d4-68","day":4,"word":"discount","meaning":"~을 배제하다","ipa":"[dɪˈskaʊnt]","kr":"디스카운트","example":"We can discount that rumor as false.","exampleKr":"우리는 그 소문을 거짓으로 배제할 수 있다.","roots":"dis-(제외하여) + count(세다, 라틴어 computare) → 세지 않고 제외하다"},{"id":"d4-69","day":4,"word":"contrast","meaning":"대조적이다","ipa":"[kənˈtræst]","kr":"컨트래스트","example":"Her calm voice contrasts with his loud one.","exampleKr":"그녀의 차분한 목소리는 그의 큰 목소리와 대조적이다.","roots":"contra-(반대로) + st(서다, 라틴어 stare) → 반대로 서서 대조되다"},{"id":"d4-70","day":4,"word":"replace","meaning":"대체하다","ipa":"[rɪˈpleɪs]","kr":"리플레이스","example":"The old bridge will be replaced next year.","exampleKr":"그 오래된 다리는 내년에 대체될 것이다.","roots":"re-(다시) + place(자리, 그리스어 plateia) → 다시 자리를 채우다, 대체하다"},{"id":"d4-71","day":4,"word":"substitute","meaning":"대체하다","ipa":"[ˈsʌbstɪtuːt]","kr":"섭스티튜트","example":"He used a substitute teacher for the day.","exampleKr":"그는 그날 대체 교사를 이용했다.","roots":"sub-(대신) + stitu(세우다, 라틴어 statuere) → 대신 세우다, 대체하다"},{"id":"d4-72","day":4,"word":"alternate","meaning":"대체하다","ipa":"[ˈɔːltərneɪt]","kr":"올터네이트","example":"The plan has an alternate route in case of delay.","exampleKr":"그 계획은 지연될 경우 대체 경로가 있다.","roots":"alter(다른, 라틴어 alter) + -ate → 다른 것으로 번갈아 바꾸다"},{"id":"d4-73","day":4,"word":"weaver","meaning":"직조공","ipa":"[ˈwiːvər]","kr":"위버","example":"The weaver worked on the rug for months.","exampleKr":"그 직조공은 몇 달 동안 그 러그를 짰다."},{"id":"d4-74","day":4,"word":"existing","meaning":"기존의","ipa":"[ɪɡˈzɪstɪŋ]","kr":"이그지스팅","example":"The rule applies to all existing members.","exampleKr":"그 규칙은 모든 기존 회원에게 적용된다.","roots":"ex-(밖으로) + sist(서다, 라틴어 sistere) → 밖으로 나와 서 있는, 존재하는"},{"id":"d4-75","day":4,"word":"established","meaning":"기존의","ipa":"[ɪˈstæblɪʃt]","kr":"이스태블리쉬트","example":"He runs an established business downtown.","exampleKr":"그는 시내에서 기존의 사업체를 운영한다.","roots":"stabl(안정된, 라틴어 stabilis) + -ish → 안정되게 세우다, 확립하다"},{"id":"d4-76","day":4,"word":"task","meaning":"작업","ipa":"[tæsk]","kr":"태스크","example":"She finished the task ahead of schedule.","exampleKr":"그녀는 일정보다 앞서 그 작업을 끝냈다."},{"id":"d4-77","day":4,"word":"prompt","meaning":"유발하다","ipa":"[prɑːmpt]","kr":"프람프트","example":"The alarm prompted everyone to leave the building.","exampleKr":"그 경보는 모두를 건물 밖으로 나가게 했다.","roots":"pro-(앞으로) + empt(취하다, 라틴어 emere) → 앞으로 꺼내다, 촉발하다"},{"id":"d4-78","day":4,"word":"trigger","meaning":"유발하다, 촉발하다","ipa":"[ˈtrɪɡər]","kr":"트리거","example":"Stress can trigger headaches.","exampleKr":"스트레스는 두통을 유발할 수 있다."},{"id":"d4-79","day":4,"word":"spark","meaning":"유발하다, 촉발하다","ipa":"[spɑːrk]","kr":"스파크","example":"The comment sparked a heated debate.","exampleKr":"그 발언은 격렬한 토론을 촉발했다."},{"id":"d4-80","day":4,"word":"arouse","meaning":"유발하다","ipa":"[əˈraʊz]","kr":"어라우즈","example":"Her unusual behavior aroused suspicion.","exampleKr":"그녀의 이상한 행동은 의심을 유발했다."},{"id":"d4-81","day":4,"word":"lead to","meaning":"유발하다","ipa":"[liːd tuː]","kr":"리드 투","example":"Poor sleep can lead to health problems.","exampleKr":"수면 부족은 건강 문제로 이어질 수 있다."},{"id":"d4-82","day":4,"word":"induce","meaning":"유발하다","ipa":"[ɪnˈduːs]","kr":"인듀스","example":"The medicine induced drowsiness.","exampleKr":"그 약은 졸음을 유발했다.","roots":"in-(안으로) + duc(이끌다, 라틴어 ducere) → 안으로 이끌어 유발하다"},{"id":"d4-83","day":4,"word":"income","meaning":"수입","ipa":"[ˈɪnkʌm]","kr":"인컴","example":"Her income increased after the promotion.","exampleKr":"그녀의 수입은 승진 후 늘었다."},{"id":"d4-84","day":4,"word":"outcome","meaning":"결과","ipa":"[ˈaʊtkʌm]","kr":"아웃컴","example":"The outcome of the vote was close.","exampleKr":"그 투표의 결과는 근소했다."},{"id":"d4-85","day":4,"word":"upcoming","meaning":"다가오는","ipa":"[ˈʌpkʌmɪŋ]","kr":"업커밍","example":"She is preparing for the upcoming exam.","exampleKr":"그녀는 다가오는 시험을 준비하고 있다."},{"id":"d4-86","day":4,"word":"outgoing","meaning":"외향적인","ipa":"[ˈaʊtɡoʊɪŋ]","kr":"아웃고잉","example":"He has an outgoing personality.","exampleKr":"그는 외향적인 성격을 가지고 있다."},{"id":"d4-87","day":4,"word":"attitude","meaning":"태도","ipa":"[ˈætɪtuːd]","kr":"애티튜드","example":"Her positive attitude inspires the whole team.","exampleKr":"그녀의 긍정적인 태도는 팀 전체에 영감을 준다.","roots":"apt(적합한, 라틴어 aptus) + -itude → 적합하게 갖춘 자세, 태도"},{"id":"d4-88","day":4,"word":"aptitude","meaning":"적성","ipa":"[ˈæptɪtuːd]","kr":"앱티튜드","example":"He has a natural aptitude for math.","exampleKr":"그는 수학에 타고난 적성이 있다.","roots":"apt(적합한, 라틴어 aptus) + -itude → 적합한 능력, 적성"},{"id":"d4-89","day":4,"word":"altitude","meaning":"고도","ipa":"[ˈæltɪtuːd]","kr":"앨티튜드","example":"The plane climbed to a higher altitude.","exampleKr":"그 비행기는 더 높은 고도로 상승했다.","roots":"alt(높은, 라틴어 altus) + -itude → 높음, 고도"},{"id":"d4-90","day":4,"word":"economist","meaning":"경제학자","ipa":"[ɪˈkɑːnəmɪst]","kr":"이카너미스트","example":"The economist predicted a mild recession.","exampleKr":"그 경제학자는 완만한 경기 침체를 예측했다.","roots":"eco(집, 그리스어 oikos) + nom(법칙, 그리스어 nomos) + -ist → 집안을 다스리는 법을 연구하는 사람"},{"id":"d4-91","day":4,"word":"astronomer","meaning":"천문학자","ipa":"[əˈstrɑːnəmər]","kr":"어스트라너머","example":"The astronomer discovered a new comet.","exampleKr":"그 천문학자는 새로운 혜성을 발견했다.","roots":"astro(별, 그리스어 astron) + nom(법칙, 그리스어 nomos) + -er → 별의 법칙을 연구하는 사람"},{"id":"d4-92","day":4,"word":"gaze","meaning":"바라보다, 응시하다","ipa":"[ɡeɪz]","kr":"게이즈","example":"She gazed out the window in silence.","exampleKr":"그녀는 조용히 창밖을 바라보았다."},{"id":"d4-93","day":4,"word":"glimpse","meaning":"언뜻 봄, 잠깐 봄","ipa":"[ɡlɪmps]","kr":"글림프스","example":"He caught a glimpse of the sunset.","exampleKr":"그는 노을을 언뜻 봤다."},{"id":"d4-94","day":4,"word":"glance","meaning":"언뜻 봄, 잠깐 봄","ipa":"[ɡlæns]","kr":"글랜스","example":"She gave him a quick glance and smiled.","exampleKr":"그녀는 그를 잠깐 보고 미소지었다."},{"id":"d4-95","day":4,"word":"stare","meaning":"응시","ipa":"[ster]","kr":"스테어","example":"Don't stare at strangers.","exampleKr":"낯선 사람을 응시하지 마라."},{"id":"d4-96","day":4,"word":"moon","meaning":"위성, 달","ipa":"[muːn]","kr":"문","example":"The moon was full last night.","exampleKr":"어젯밤 달은 보름달이었다."},{"id":"d4-97","day":4,"word":"Jupiter","meaning":"목성","ipa":"[ˈdʒuːpɪtər]","kr":"주피터","example":"Jupiter is the largest planet in our solar system.","exampleKr":"목성은 태양계에서 가장 큰 행성이다.","roots":"Jov(하늘의 신, 라틴어 Iuppiter의 어근 Iov-) + pater(아버지, 라틴어 pater) → 하늘의 아버지 신 → 목성"},{"id":"d4-98","day":4,"word":"displace","meaning":"쫓아내다, 해직하다","ipa":"[dɪsˈpleɪs]","kr":"디스플레이스","example":"The flood displaced hundreds of families.","exampleKr":"그 홍수는 수백 가구를 쫓아냈다.","roots":"dis-(떨어져) + place(자리, 그리스어 plateia) → 자리에서 떼어내다, 쫓아내다"},{"id":"d4-99","day":4,"word":"dismiss","meaning":"쫓아내다, 해직하다","ipa":"[dɪsˈmɪs]","kr":"디스미스","example":"He was dismissed from his job for lateness.","exampleKr":"그는 지각 때문에 해고당했다.","roots":"dis-(멀리) + miss(보내다, 라틴어 mittere) → 멀리 보내버리다, 해직하다"},{"id":"d4-100","day":4,"word":"expel","meaning":"쫓아내다","ipa":"[ɪkˈspel]","kr":"익스펠","example":"The student was expelled from school.","exampleKr":"그 학생은 학교에서 퇴학당했다.","roots":"ex-(밖으로) + pel(몰다, 라틴어 pellere) → 밖으로 몰아내다, 쫓아내다"},{"id":"d5-1","day":5,"word":"laborer","meaning":"노동자","ipa":"[ˈleɪbərər]","kr":"레이버러","example":"The laborer worked long hours in the field.","exampleKr":"그 노동자는 밭에서 장시간 일했다.","roots":"labor(일하다, 라틴어 labor) + -er(사람) → 일하는 사람"},{"id":"d5-2","day":5,"word":"previously","meaning":"이전에","ipa":"[ˈpriːviəsli]","kr":"프리비어슬리","example":"She previously worked as a teacher.","exampleKr":"그녀는 이전에 교사로 일했다.","roots":"pre-(미리) + vi(a)(길, 라틴어 via) + -ous + -ly → 미리 길을 감, 이전에"},{"id":"d5-3","day":5,"word":"formerly","meaning":"이전에","ipa":"[ˈfɔːrmərli]","kr":"포멀리","example":"He was formerly the CEO of the company.","exampleKr":"그는 이전에 그 회사의 CEO였다."},{"id":"d5-4","day":5,"word":"precedently","meaning":"이전에","ipa":"[ˈpresɪdəntli]","kr":"프레시던틀리","example":"The rule had never been applied precedently.","exampleKr":"그 규칙은 이전에 적용된 적이 없었다.","roots":"pre-(앞서) + ced(가다, 라틴어 cedere) + -ent + -ly → 앞서 가는"},{"id":"d5-5","day":5,"word":"capital","meaning":"자본","ipa":"[ˈkæpɪtl]","kr":"캐피틀","example":"The startup needs more capital to grow.","exampleKr":"그 스타트업은 성장하기 위해 더 많은 자본이 필요하다.","roots":"capit(머리, 라틴어 caput) + -al → 으뜸이 되는 것, 자본"},{"id":"d5-6","day":5,"word":"adoption","meaning":"채택","ipa":"[əˈdɑːpʃn]","kr":"어답션","example":"The adoption of the new policy took months.","exampleKr":"그 새 정책의 채택은 몇 달이 걸렸다.","roots":"ad-(~쪽으로) + opt(선택하다, 라틴어 optare) + -ion → 선택하여 취함, 채택"},{"id":"d5-7","day":5,"word":"frictionless","meaning":"마찰이 없는","ipa":"[ˈfrɪkʃnləs]","kr":"프릭션리스","example":"The app offers a frictionless checkout experience.","exampleKr":"그 앱은 마찰 없는 결제 경험을 제공한다.","roots":"fric(문지르다, 라틴어 fricare) + -tion + -less(없는) → 마찰이 없는"},{"id":"d5-8","day":5,"word":"inevitable","meaning":"불가피한","ipa":"[ɪnˈevɪtəbl]","kr":"인에비터블","example":"Change is inevitable in any business.","exampleKr":"변화는 모든 사업에서 불가피하다.","roots":"in-(부정) + e-(밖으로, 라틴어 ex-) + vit(피하다, 라틴어 vitare) + -able → 피할 수 없는"},{"id":"d5-9","day":5,"word":"unavoidable","meaning":"불가피한","ipa":"[ˌʌnəˈvɔɪdəbl]","kr":"언어보이더블","example":"Some delays are simply unavoidable.","exampleKr":"어떤 지연은 단순히 불가피하다.","roots":"un-(부정) + avoid(피하다, 고프랑스어 vuider, 라틴어 vacuus 빈) + -able → 비워서 피할 수 없는"},{"id":"d5-10","day":5,"word":"thrive","meaning":"번성하다, 성공하다","ipa":"[θraɪv]","kr":"쓰라이브","example":"The garden thrives in full sunlight.","exampleKr":"그 정원은 온전한 햇빛 속에서 번성한다."},{"id":"d5-11","day":5,"word":"flourish","meaning":"번성하다, 성공하다","ipa":"[ˈflɜːrɪʃ]","kr":"플러리시","example":"Their friendship flourished over the years.","exampleKr":"그들의 우정은 수년에 걸쳐 번성했다.","roots":"flor(꽃, 라틴어 florere) + -ish → 꽃피다, 번성하다"},{"id":"d5-12","day":5,"word":"prosper","meaning":"번성하다, 성공하다","ipa":"[ˈprɑːspər]","kr":"프라스퍼","example":"The village prospered thanks to tourism.","exampleKr":"그 마을은 관광 덕분에 번성했다.","roots":"pro-(~에 맞게) + sper(희망, 라틴어 spes) → 희망에 맞다, 번성하다"},{"id":"d5-13","day":5,"word":"bloom","meaning":"번성하다","ipa":"[bluːm]","kr":"블룸","example":"The flowers bloom every spring.","exampleKr":"그 꽃들은 매년 봄에 핀다."},{"id":"d5-14","day":5,"word":"blossom","meaning":"번성하다","ipa":"[ˈblɑːsəm]","kr":"블라섬","example":"Her career blossomed after the award.","exampleKr":"그녀의 경력은 그 상 이후 번성했다."},{"id":"d5-15","day":5,"word":"intellectual","meaning":"지적인","ipa":"[ˌɪntəˈlektʃuəl]","kr":"인텔렉추얼","example":"He enjoys intellectual conversations.","exampleKr":"그는 지적인 대화를 즐긴다.","roots":"inter-(사이에서) + lect(고르다, 라틴어 legere) + -ual → 사이에서 골라내는, 지적인"},{"id":"d5-16","day":5,"word":"knowledgeable","meaning":"지적인","ipa":"[ˈnɑːlɪdʒəbl]","kr":"날리저블","example":"The guide was very knowledgeable about local history.","exampleKr":"그 가이드는 지역 역사에 대해 매우 박식했다."},{"id":"d5-17","day":5,"word":"enlightened","meaning":"지적인","ipa":"[ɪnˈlaɪtnd]","kr":"인라이튼드","example":"Her enlightened views surprised the older generation.","exampleKr":"그녀의 지적인 관점은 기성 세대를 놀라게 했다."},{"id":"d5-18","day":5,"word":"sophisticated","meaning":"지적인","ipa":"[səˈfɪstɪkeɪtɪd]","kr":"서피스티케이티드","example":"The device has a sophisticated design.","exampleKr":"그 기기는 정교한 설계를 가지고 있다.","roots":"soph(지혜, 그리스어 sophos) + -ist + -ic + -ate → 지혜롭게 다듬어진, 세련된"},{"id":"d5-19","day":5,"word":"authority","meaning":"권위","ipa":"[əˈθɔːrəti]","kr":"어쏘러티","example":"She speaks with authority on the subject.","exampleKr":"그녀는 그 주제에 대해 권위 있게 말한다.","roots":"auth(or)(창시자, 라틴어 auctor) + -ity → 창시자로서의 힘, 권위"},{"id":"d5-20","day":5,"word":"prestige","meaning":"권위","ipa":"[preˈstiːʒ]","kr":"프레스티지","example":"The award brought great prestige to the school.","exampleKr":"그 상은 학교에 큰 권위를 가져다주었다.","roots":"pre-(앞서) + stig(조이다, 라틴어 stringere) → 눈속임, 위세/명성"},{"id":"d5-21","day":5,"word":"authoritarian","meaning":"권위적인","ipa":"[əˌθɔːrəˈteriən]","kr":"어쏘러테리언","example":"The regime was known for its authoritarian rule.","exampleKr":"그 정권은 권위적인 통치로 알려져 있었다.","roots":"auth(or)(창시자, 라틴어 auctor) + -ity + -arian → 권위를 내세우는"},{"id":"d5-22","day":5,"word":"insecure","meaning":"자신 없는","ipa":"[ˌɪnsɪˈkjʊr]","kr":"인시큐어","example":"He felt insecure about his new job.","exampleKr":"그는 새 직장에 대해 자신이 없었다.","roots":"in-(부정) + se-(~없이) + cur(돌봄, 라틴어 cura) → 걱정에서 벗어나지 못한, 자신 없는"},{"id":"d5-23","day":5,"word":"hesitant","meaning":"자신 없는","ipa":"[ˈhezɪtənt]","kr":"헤지턴트","example":"She was hesitant to speak in public.","exampleKr":"그녀는 대중 앞에서 말하기를 주저했다.","roots":"haesit(달라붙다, 라틴어 haerere) + -ant → 머뭇거리는, 자신 없는"},{"id":"d5-24","day":5,"word":"secure","meaning":"자신 있는","ipa":"[səˈkjʊr]","kr":"시큐어","example":"He felt secure with his savings.","exampleKr":"그는 저축을 하고 나서 자신감을 느꼈다.","roots":"se-(~없이) + cur(돌봄, 라틴어 cura) → 걱정 없는, 안전한/자신 있는"},{"id":"d5-25","day":5,"word":"sensitivity","meaning":"세심함","ipa":"[ˌsensəˈtɪvəti]","kr":"센서티버티","example":"The topic requires sensitivity and care.","exampleKr":"그 주제는 세심함과 배려가 필요하다.","roots":"sens(느끼다, 라틴어 sentire) + -itive + -ity → 잘 느낌, 세심함"},{"id":"d5-26","day":5,"word":"sensitive","meaning":"세심한, 민감한","ipa":"[ˈsensətɪv]","kr":"센서티브","example":"Her skin is sensitive to sunlight.","exampleKr":"그녀의 피부는 햇빛에 민감하다.","roots":"sens(느끼다, 라틴어 sentire) + -itive → 잘 느끼는, 민감한"},{"id":"d5-27","day":5,"word":"sensible","meaning":"합리적인, 논리적인","ipa":"[ˈsensəbl]","kr":"센서블","example":"It was a sensible decision to save money.","exampleKr":"돈을 저축하기로 한 것은 합리적인 결정이었다.","roots":"sens(느끼다, 라틴어 sentire) + -ible → 느낄 수 있는, 합리적인"},{"id":"d5-28","day":5,"word":"sensory","meaning":"감각의","ipa":"[ˈsensəri]","kr":"센서리","example":"The museum offers a sensory experience for kids.","exampleKr":"그 박물관은 아이들에게 감각적인 경험을 제공한다.","roots":"sens(느끼다, 라틴어 sentire) + -ory → 느낌에 관한, 감각의"},{"id":"d5-29","day":5,"word":"withdraw","meaning":"움츠러들다, 위축시키다","ipa":"[wɪðˈdrɔː]","kr":"위드드로","example":"He withdrew from the competition due to injury.","exampleKr":"그는 부상으로 경기에서 물러났다."},{"id":"d5-30","day":5,"word":"shrink","meaning":"움츠러들다","ipa":"[ʃrɪŋk]","kr":"슈링크","example":"The sweater shrank after washing.","exampleKr":"그 스웨터는 세탁 후 줄어들었다."},{"id":"d5-31","day":5,"word":"contract","meaning":"움츠러들다, 수축하다","ipa":"[kənˈtrækt]","kr":"컨트랙트","example":"Metal contracts when it gets cold.","exampleKr":"금속은 차가워지면 수축한다.","roots":"con-(함께) + tract(끌다, 라틴어 trahere) → 함께 끌어당기다, 수축하다"},{"id":"d5-32","day":5,"word":"let alone","meaning":"~은 말할 것도 없이","ipa":"[let əˈloʊn]","kr":"렛 얼론","example":"He can't even walk, let alone run.","exampleKr":"그는 걷지도 못하는데, 뛰는 것은 말할 것도 없다."},{"id":"d5-33","day":5,"word":"not to mention","meaning":"~은 말할 것도 없이","ipa":"[nɑːt tuː ˈmenʃn]","kr":"낫 투 멘션","example":"The hotel was expensive, not to mention noisy.","exampleKr":"그 호텔은 비쌌고, 시끄러운 것은 말할 것도 없었다."},{"id":"d5-34","day":5,"word":"to say nothing of","meaning":"~은 말할 것도 없이","ipa":"[tuː seɪ ˈnʌθɪŋ əv]","kr":"투 세이 낫씽 오브","example":"The trip was tiring, to say nothing of the cost.","exampleKr":"그 여행은 피곤했고, 비용은 말할 것도 없었다."},{"id":"d5-35","day":5,"word":"potential","meaning":"잠재력, 가능성","ipa":"[pəˈtenʃl]","kr":"퍼텐셜","example":"The coach saw great potential in the young player.","exampleKr":"코치는 그 젊은 선수에게서 큰 잠재력을 봤다.","roots":"pot(할 수 있는, 라틴어 posse) + -ent + -ial → 할 수 있는 힘, 잠재력"},{"id":"d5-36","day":5,"word":"odds","meaning":"가능성","ipa":"[ɑːdz]","kr":"아즈","example":"The odds of winning the lottery are very low.","exampleKr":"복권에 당첨될 가능성은 매우 낮다."},{"id":"d5-37","day":5,"word":"likelihood","meaning":"가능성","ipa":"[ˈlaɪklihʊd]","kr":"라이클리후드","example":"There is a high likelihood of rain tomorrow.","exampleKr":"내일 비가 올 가능성이 높다."},{"id":"d5-38","day":5,"word":"probability","meaning":"가능성","ipa":"[ˌprɑːbəˈbɪləti]","kr":"프라버빌러티","example":"The probability of success increased with practice.","exampleKr":"성공 가능성은 연습과 함께 높아졌다.","roots":"prob(입증하다, 라틴어 probare) + -abil(ity) → 입증될 수 있음, 가능성"},{"id":"d5-39","day":5,"word":"chance","meaning":"가능성","ipa":"[tʃæns]","kr":"챈스","example":"There's a good chance she will accept the offer.","exampleKr":"그녀가 제안을 수락할 가능성이 높다."},{"id":"d5-40","day":5,"word":"prospect","meaning":"가능성","ipa":"[ˈprɑːspekt]","kr":"프라스펙트","example":"The job offers a good career prospect.","exampleKr":"그 일자리는 좋은 경력 가능성을 제공한다.","roots":"pro-(앞으로) + spect(보다, 라틴어 specere) → 앞을 내다봄, 가능성"},{"id":"d5-41","day":5,"word":"risky","meaning":"모험적인, 위험한","ipa":"[ˈrɪski]","kr":"리스키","example":"Investing all your money in one stock is risky.","exampleKr":"한 주식에 모든 돈을 투자하는 것은 위험하다."},{"id":"d5-42","day":5,"word":"hazardous","meaning":"위험한","ipa":"[ˈhæzərdəs]","kr":"해저더스","example":"The chemicals are hazardous if not handled properly.","exampleKr":"그 화학물질은 제대로 다루지 않으면 위험하다."},{"id":"d5-43","day":5,"word":"perilous","meaning":"위험한","ipa":"[ˈperələs]","kr":"페럴러스","example":"They made a perilous journey through the mountains.","exampleKr":"그들은 산을 통과하는 위험한 여정을 떠났다.","roots":"peril(위험, 라틴어 periculum) + -ous → 위험한"},{"id":"d5-44","day":5,"word":"interpretation","meaning":"해석","ipa":"[ɪnˌtɜːrprɪˈteɪʃn]","kr":"인터프리테이션","example":"Her interpretation of the poem was unique.","exampleKr":"그 시에 대한 그녀의 해석은 독특했다.","roots":"inter-(사이에) + pret(설명하다, 라틴어 interpres) + -ation → 사이에서 설명해 줌, 해석"},{"id":"d5-45","day":5,"word":"for the sake of","meaning":"~을 위해","ipa":"[fɔːr ðə seɪk əv]","kr":"포 더 세이크 오브","example":"He stayed for the sake of his children.","exampleKr":"그는 아이들을 위해 남았다."},{"id":"d5-46","day":5,"word":"advisable","meaning":"권장할 만한","ipa":"[ədˈvaɪzəbl]","kr":"어드바이저블","example":"It is advisable to see a doctor soon.","exampleKr":"곧 병원에 가는 것이 권장할 만하다.","roots":"ad-(~에게) + vis(보다, 라틴어 videre) + -able → 살펴보고 권할 만한"},{"id":"d5-47","day":5,"word":"desirable","meaning":"권장할 만한","ipa":"[dɪˈzaɪərəbl]","kr":"디자이어러블","example":"A quiet neighborhood is highly desirable.","exampleKr":"조용한 동네는 매우 바람직하다.","roots":"de-(~로부터) + sir(별, 라틴어 sidus) + -able → 별에서 바라는 것, 바람직한"},{"id":"d5-48","day":5,"word":"approach","meaning":"접근(법)","ipa":"[əˈproʊtʃ]","kr":"어프로우치","example":"She took a gentle approach with the students.","exampleKr":"그녀는 학생들에게 부드러운 접근법을 취했다.","roots":"ap-(~쪽으로) + proch(가까운, 라틴어 prope) → 가까이 다가감"},{"id":"d5-49","day":5,"word":"at stake","meaning":"문제가 되는","ipa":"[æt steɪk]","kr":"앳 스테이크","example":"Millions of dollars are at stake in this deal.","exampleKr":"이 거래에는 수백만 달러가 걸려 있다."},{"id":"d5-50","day":5,"word":"questionable","meaning":"문제가 되는","ipa":"[ˈkwestʃənəbl]","kr":"퀘스처너블","example":"His motives seemed questionable.","exampleKr":"그의 동기는 의심스러워 보였다.","roots":"quest(묻다, 라틴어 quaerere) + -ion + -able → 물어볼 만한, 의심스러운"},{"id":"d5-51","day":5,"word":"demonstrate","meaning":"보여 주다, 입증하다","ipa":"[ˈdemənstreɪt]","kr":"데먼스트레이트","example":"The results demonstrate clear progress.","exampleKr":"그 결과는 명확한 진전을 보여준다.","roots":"de-(강조) + monstr(보여주다, 라틴어 monstrare) + -ate → 완전히 보여 주다"},{"id":"d5-52","day":5,"word":"manifest","meaning":"보여 주다","ipa":"[ˈmænɪfest]","kr":"매니페스트","example":"Success does not manifest overnight.","exampleKr":"성공은 하룻밤 사이에 나타나지 않는다.","roots":"mani(손, 라틴어 manus) + fest(붙잡힌, 라틴어 -festus) → 손에 잡힐 만큼 명백한"},{"id":"d5-53","day":5,"word":"exemplify","meaning":"예를 들어 입증하다","ipa":"[ɪɡˈzemplɪfaɪ]","kr":"이그젬플리파이","example":"Her actions exemplify true leadership.","exampleKr":"그녀의 행동은 진정한 리더십을 잘 보여준다.","roots":"ex-(밖으로) + empl(본보기, 라틴어 exemplum) + -ify(만들다) → 본보기를 꺼내 보여주다"},{"id":"d5-54","day":5,"word":"validate","meaning":"입증하다","ipa":"[ˈvælɪdeɪt]","kr":"밸리데이트","example":"The experiment validated their hypothesis.","exampleKr":"그 실험은 그들의 가설을 입증했다.","roots":"val(가치 있는, 라틴어 valere) + -id + -ate → 가치 있게 만들다, 입증하다"},{"id":"d5-55","day":5,"word":"verify","meaning":"입증하다","ipa":"[ˈverɪfaɪ]","kr":"베리파이","example":"Please verify your email address.","exampleKr":"이메일 주소를 확인해 주세요.","roots":"ver(진실한, 라틴어 verus) + -ify(만들다) → 진실하게 만들다, 입증하다"},{"id":"d5-56","day":5,"word":"superiority","meaning":"우월성","ipa":"[suːˌpɪriˈɔːrəti]","kr":"수피리오러티","example":"He never claimed superiority over his teammates.","exampleKr":"그는 팀원들보다 우월하다고 주장한 적이 없다.","roots":"super(위에, 라틴어 super) + -ior + -ity → 위에 있음, 우월성"},{"id":"d5-57","day":5,"word":"hierarchy","meaning":"서열","ipa":"[ˈhaɪərɑːrki]","kr":"하이어라키","example":"The company has a clear hierarchy.","exampleKr":"그 회사는 명확한 서열을 가지고 있다.","roots":"hier(신성한, 그리스어 hieros) + arch(다스림, 그리스어 arkhein) + -y → 신성한 다스림, 서열"},{"id":"d5-58","day":5,"word":"pecking order","meaning":"서열","ipa":"[ˈpekɪŋ ˈɔːrdər]","kr":"페킹 오더","example":"Everyone knew their place in the pecking order.","exampleKr":"모두가 서열에서 자신의 위치를 알고 있었다."},{"id":"d5-59","day":5,"word":"realization","meaning":"실감","ipa":"[ˌriːələˈzeɪʃn]","kr":"리얼러제이션","example":"The realization hit her suddenly.","exampleKr":"그 실감이 그녀에게 갑자기 다가왔다.","roots":"real(실제의, 라틴어 res) + -ize + -ation → 실제로 만듦, 실감"},{"id":"d5-60","day":5,"word":"investigate","meaning":"탐색하다, 조사하다","ipa":"[ɪnˈvestɪɡeɪt]","kr":"인베스티게이트","example":"Police are investigating the incident.","exampleKr":"경찰이 그 사건을 조사하고 있다.","roots":"in-(안으로) + vestig(발자국, 라틴어 vestigium) + -ate → 발자국을 따라가다, 조사하다"},{"id":"d5-61","day":5,"word":"exercise","meaning":"행사하다","ipa":"[ˈeksərsaɪz]","kr":"엑서사이즈","example":"He exercises his right to vote every year.","exampleKr":"그는 매년 투표할 권리를 행사한다.","roots":"ex-(밖으로) + erc(가두다, 라틴어 arcere) + -ise → 가둔 것을 풀어내다, 행사하다"},{"id":"d5-62","day":5,"word":"clinical","meaning":"임상의","ipa":"[ˈklɪnɪkl]","kr":"클리니컬","example":"She works in a clinical setting.","exampleKr":"그녀는 임상 환경에서 일한다.","roots":"clin(눕다/기울다, 그리스어 klinein) + -ical → 침상 곁에서의, 임상의"},{"id":"d5-63","day":5,"word":"psychologist","meaning":"심리학자","ipa":"[saɪˈkɑːlədʒɪst]","kr":"사이칼러지스트","example":"The psychologist helped him manage his anxiety.","exampleKr":"그 심리학자는 그가 불안을 관리하도록 도왔다.","roots":"psych(정신, 그리스어 psykhe) + log(학문, 그리스어 logos) + -ist → 정신을 연구하는 사람"},{"id":"d5-64","day":5,"word":"seek","meaning":"찾다","ipa":"[siːk]","kr":"시크","example":"They sought shelter from the storm.","exampleKr":"그들은 폭풍을 피할 곳을 찾았다."},{"id":"d5-65","day":5,"word":"therapy","meaning":"치료","ipa":"[ˈθerəpi]","kr":"세러피","example":"She started therapy after the accident.","exampleKr":"그녀는 사고 후 치료를 시작했다.","roots":"therap(돌보다, 그리스어 therapeuein) + -y → 돌봄, 치료"},{"id":"d5-66","day":5,"word":"organized","meaning":"조직화 된","ipa":"[ˈɔːrɡənaɪzd]","kr":"오거나이즈드","example":"He keeps his desk very organized.","exampleKr":"그는 책상을 매우 정돈되게 유지한다.","roots":"organ(기관, 그리스어 organon) + -ize + -ed → 기관처럼 짜여지게 하다, 조직화된"},{"id":"d5-67","day":5,"word":"self controlled","meaning":"자기 통제적인","ipa":"[self kənˈtroʊld]","kr":"셀프 컨트로울드","example":"She remained self controlled during the argument.","exampleKr":"그녀는 다툼 동안 자기 통제적이었다."},{"id":"d5-68","day":5,"word":"subconscious","meaning":"잠재의식","ipa":"[ˌsʌbˈkɑːnʃəs]","kr":"섭칸셔스","example":"Dreams reveal our subconscious thoughts.","exampleKr":"꿈은 우리의 잠재의식적 생각을 드러낸다.","roots":"sub-(아래) + con-(함께) + sci(알다, 라틴어 scire) + -ous → 함께 아는 것 아래에 있는, 잠재의식"},{"id":"d5-69","day":5,"word":"make sense","meaning":"이치에 맞다","ipa":"[meɪk sens]","kr":"메이크 센스","example":"His explanation didn't make sense to me.","exampleKr":"그의 설명은 내게 이치에 맞지 않았다."},{"id":"d5-70","day":5,"word":"design","meaning":"설계하다","ipa":"[dɪˈzaɪn]","kr":"디자인","example":"The bridge was designed by a famous engineer.","exampleKr":"그 다리는 유명한 엔지니어가 설계했다.","roots":"de-(아래로) + sign(표시하다, 라틴어 signare) → 표시를 그려 넣다, 설계하다"},{"id":"d5-71","day":5,"word":"cue","meaning":"단서","ipa":"[kjuː]","kr":"큐","example":"The music was a cue for the actors to enter.","exampleKr":"그 음악은 배우들이 등장할 단서였다."},{"id":"d5-72","day":5,"word":"clue","meaning":"단서","ipa":"[kluː]","kr":"클루","example":"The detective found a crucial clue.","exampleKr":"그 형사는 중요한 단서를 찾았다."},{"id":"d5-73","day":5,"word":"starvation","meaning":"아사, 굶주림","ipa":"[stɑːrˈveɪʃn]","kr":"스타베이션","example":"Many faced starvation during the war.","exampleKr":"많은 사람들이 전쟁 동안 굶주림에 직면했다."},{"id":"d5-74","day":5,"word":"catastrophic","meaning":"재앙의","ipa":"[ˌkætəˈstrɑːfɪk]","kr":"캐터스트라픽","example":"The earthquake caused catastrophic damage.","exampleKr":"그 지진은 재앙적인 피해를 일으켰다.","roots":"cata-(아래로) + stroph(뒤집다, 그리스어 strephein) + -ic → 아래로 뒤집힘, 재앙적인"},{"id":"d5-75","day":5,"word":"end up","meaning":"결국 ~이 되다","ipa":"[end ʌp]","kr":"엔드 업","example":"He ended up quitting his job.","exampleKr":"그는 결국 직장을 그만두게 되었다."},{"id":"d5-76","day":5,"word":"wind up","meaning":"결국 ~이 되다","ipa":"[waɪnd ʌp]","kr":"와인드 업","example":"She wound up moving to another city.","exampleKr":"그녀는 결국 다른 도시로 이사하게 되었다."},{"id":"d5-77","day":5,"word":"adaptive","meaning":"적응하는","ipa":"[əˈdæptɪv]","kr":"어댑티브","example":"Humans are highly adaptive creatures.","exampleKr":"인간은 매우 적응하는 생물이다.","roots":"ad-(~쪽으로) + apt(맞추다, 라틴어 aptare) + -ive → 맞추어 가는, 적응하는"},{"id":"d5-78","day":5,"word":"niche","meaning":"틈새, 영역","ipa":"[nɪtʃ]","kr":"니치","example":"The company found a niche in eco-friendly products.","exampleKr":"그 회사는 친환경 제품 틈새시장을 찾았다."},{"id":"d5-79","day":5,"word":"commonality","meaning":"공통점","ipa":"[ˌkɑːməˈnæləti]","kr":"카머낼러티","example":"Despite their differences, they found commonality.","exampleKr":"차이에도 불구하고, 그들은 공통점을 찾았다.","roots":"com-(함께) + mun(의무, 라틴어 munis) + -al + -ity → 함께 의무를 나누는 것, 공통점"},{"id":"d5-80","day":5,"word":"inhibit","meaning":"억제하다, 방지하다","ipa":"[ɪnˈhɪbɪt]","kr":"인히빗","example":"Fear can inhibit creativity.","exampleKr":"두려움은 창의성을 억제할 수 있다.","roots":"in-(안에) + hib(잡다, 라틴어 habere) → 안에 붙잡아 두다, 억제하다"},{"id":"d5-81","day":5,"word":"inhabit","meaning":"거주하다","ipa":"[ɪnˈhæbɪt]","kr":"인해빗","example":"Few people inhabit this remote island.","exampleKr":"이 외딴 섬에는 거주하는 사람이 거의 없다.","roots":"in-(안에) + habit(살다, 라틴어 habitare) → 안에서 살다, 거주하다"},{"id":"d5-82","day":5,"word":"prohibit","meaning":"억제하다, 금지하다","ipa":"[proʊˈhɪbɪt]","kr":"프로히빗","example":"Smoking is prohibited in the building.","exampleKr":"그 건물에서는 흡연이 금지되어 있다.","roots":"pro-(앞에) + hib(잡다, 라틴어 habere) → 앞을 막아 잡다, 금지하다"},{"id":"d5-83","day":5,"word":"hinder","meaning":"방해하다","ipa":"[ˈhɪndər]","kr":"힌더","example":"Poor internet access hinders remote learning.","exampleKr":"열악한 인터넷 접속은 원격 학습을 방해한다."},{"id":"d5-84","day":5,"word":"hamper","meaning":"방해하다","ipa":"[ˈhæmpər]","kr":"햄퍼","example":"Bad weather hampered the rescue effort.","exampleKr":"나쁜 날씨는 구조 활동을 방해했다."},{"id":"d5-85","day":5,"word":"surfer","meaning":"서퍼, 파도 타는 사람","ipa":"[ˈsɜːrfər]","kr":"서퍼","example":"The surfer waited for the perfect wave.","exampleKr":"그 서퍼는 완벽한 파도를 기다렸다."},{"id":"d5-86","day":5,"word":"pass through","meaning":"~을 지나가다","ipa":"[pæs θruː]","kr":"패스 쓰루","example":"The train passes through three cities.","exampleKr":"그 기차는 세 도시를 지나간다."},{"id":"d5-87","day":5,"word":"paddle","meaning":"물을 저어 가다","ipa":"[ˈpædl]","kr":"패들","example":"He paddled the canoe across the lake.","exampleKr":"그는 호수를 가로질러 카누를 저었다."},{"id":"d5-88","day":5,"word":"wave","meaning":"파도","ipa":"[weɪv]","kr":"웨이브","example":"A huge wave crashed onto the shore.","exampleKr":"거대한 파도가 해안에 부딪혔다."},{"id":"d5-89","day":5,"word":"shore","meaning":"해안","ipa":"[ʃɔːr]","kr":"쇼어","example":"They walked along the shore at sunset.","exampleKr":"그들은 일몰에 해안을 따라 걸었다."},{"id":"d5-90","day":5,"word":"out of the way","meaning":"방해가 되지 않게","ipa":"[aʊt əv ðə weɪ]","kr":"아웃 오브 더 웨이","example":"Please keep your bags out of the way.","exampleKr":"가방을 방해가 되지 않게 치워 주세요."},{"id":"d5-91","day":5,"word":"farewell","meaning":"작별 인사하다","ipa":"[ˌferˈwel]","kr":"페어웰","example":"They said their farewells at the airport.","exampleKr":"그들은 공항에서 작별 인사를 했다."},{"id":"d5-92","day":5,"word":"swell","meaning":"(파도) 너울, 팽창","ipa":"[swel]","kr":"스웰","example":"The swell made surfing dangerous today.","exampleKr":"오늘은 너울 때문에 서핑이 위험했다."},{"id":"d5-93","day":5,"word":"beachfront","meaning":"(도시 등의)해변 지역","ipa":"[ˈbiːtʃfrʌnt]","kr":"비치프런트","example":"They bought a beachfront property.","exampleKr":"그들은 해변 지역 부동산을 샀다."},{"id":"d5-94","day":5,"word":"as ever","meaning":"여전히, 변함없이","ipa":"[æz ˈevər]","kr":"애즈 에버","example":"She was cheerful, as ever.","exampleKr":"그녀는 여전히 쾌활했다."},{"id":"d5-95","day":5,"word":"eager","meaning":"간절히 바라는","ipa":"[ˈiːɡər]","kr":"이거","example":"He was eager to start his new job.","exampleKr":"그는 새 직장을 시작하기를 간절히 바랐다."},{"id":"d5-96","day":5,"word":"keen","meaning":"간절히 바라는","ipa":"[kiːn]","kr":"킨","example":"She is keen to learn new languages.","exampleKr":"그녀는 새 언어를 배우기를 간절히 바란다."},{"id":"d5-97","day":5,"word":"further","meaning":"더 멀리","ipa":"[ˈfɜːrðər]","kr":"퍼더","example":"The store is a bit further down the street.","exampleKr":"그 가게는 길을 따라 조금 더 멀리 있다."},{"id":"d5-98","day":5,"word":"dusk","meaning":"황혼","ipa":"[dʌsk]","kr":"더스크","example":"They arrived just before dusk.","exampleKr":"그들은 황혼 직전에 도착했다."},{"id":"d5-99","day":5,"word":"twilight","meaning":"황혼, 해질녘","ipa":"[ˈtwaɪlaɪt]","kr":"트와일라잇","example":"The sky turned pink at twilight.","exampleKr":"하늘은 황혼 무렵 분홍빛으로 물들었다."},{"id":"d6-1","day":6,"word":"purchase","meaning":"구입하다","ipa":"[ˈpɜːrtʃəs]","kr":"퍼처스","example":"He made the purchase online.","exampleKr":"그는 온라인으로 구입했다.","roots":"pur-(철저히, 라틴어 pro-) + chase(뒤쫓다, 고대 프랑스어 chacier) → 뒤쫓아 손에 넣다, 구입하다"},{"id":"d6-2","day":6,"word":"neighborhood","meaning":"지역","ipa":"[ˈneɪbərhʊd]","kr":"네이버후드","example":"They moved to a quiet neighborhood.","exampleKr":"그들은 조용한 지역으로 이사했다."},{"id":"d6-3","day":6,"word":"be forced to","meaning":"어쩔 수 없이 ~하다","ipa":"[bi fɔːrst tuː]","kr":"비 포스트 투","example":"She was forced to cancel the trip.","exampleKr":"그녀는 어쩔 수 없이 여행을 취소했다."},{"id":"d6-4","day":6,"word":"be obliged to","meaning":"어쩔 수 없이 ~하다","ipa":"[bi əˈblaɪdʒd tuː]","kr":"비 어블라이지드 투","example":"He was obliged to attend the meeting.","exampleKr":"그는 어쩔 수 없이 회의에 참석해야 했다."},{"id":"d6-5","day":6,"word":"be compelled to","meaning":"어쩔 수 없이 ~하다","ipa":"[bi kəmˈpeld tuː]","kr":"비 컴펠드 투","example":"They were compelled to leave the country.","exampleKr":"그들은 어쩔 수 없이 나라를 떠나야 했다."},{"id":"d6-6","day":6,"word":"hazard","meaning":"위험","ipa":"[ˈhæzərd]","kr":"해저드","example":"Loose wires are a serious hazard.","exampleKr":"느슨한 전선은 심각한 위험이다."},{"id":"d6-7","day":6,"word":"peril","meaning":"위험","ipa":"[ˈperəl]","kr":"페럴","example":"The sailors faced great peril at sea.","exampleKr":"선원들은 바다에서 큰 위험에 직면했다."},{"id":"d6-8","day":6,"word":"jeopardy","meaning":"위험","ipa":"[ˈdʒepərdi]","kr":"제퍼디","example":"His comment put the deal in jeopardy.","exampleKr":"그의 발언은 그 거래를 위험에 빠뜨렸다."},{"id":"d6-9","day":6,"word":"infrastructure","meaning":"사회기반 시설","ipa":"[ˈɪnfrəstrʌktʃər]","kr":"인프러스트럭처","example":"The city invested in new infrastructure.","exampleKr":"그 도시는 새로운 사회기반 시설에 투자했다.","roots":"infra-(아래에) + structure(짓다, 라틴어 struere) → 아래에서 떠받치는 기반 시설"},{"id":"d6-10","day":6,"word":"threatened","meaning":"위태로운","ipa":"[ˈθretnd]","kr":"쓰레튼드","example":"The species is threatened by habitat loss.","exampleKr":"그 종은 서식지 손실로 위태롭다."},{"id":"d6-11","day":6,"word":"concern","meaning":"염려","ipa":"[kənˈsɜːrn]","kr":"컨선","example":"Safety is our main concern.","exampleKr":"안전이 우리의 주요 염려 사항이다.","roots":"con-(함께) + cern(구별하다, 라틴어 cernere) → 함께 관련지어 살피다, 염려"},{"id":"d6-12","day":6,"word":"consideration","meaning":"배려","ipa":"[kənˌsɪdəˈreɪʃn]","kr":"컨시더레이션","example":"He showed great consideration for others.","exampleKr":"그는 다른 사람들에 대한 큰 배려를 보였다.","roots":"con-(함께) + sider(별, 라틴어 sidus) + -ation → 별을 함께 관찰하듯 깊이 살핌, 배려"},{"id":"d6-13","day":6,"word":"enormous","meaning":"거대한","ipa":"[ɪˈnɔːrməs]","kr":"이노머스","example":"The project required an enormous amount of effort.","exampleKr":"그 프로젝트는 엄청난 노력을 필요로 했다.","roots":"e-(밖으로) + norm(표준, 라틴어 norma) + -ous → 표준을 벗어난, 거대한"},{"id":"d6-14","day":6,"word":"massive","meaning":"거대한","ipa":"[ˈmæsɪv]","kr":"매시브","example":"The company suffered massive losses.","exampleKr":"그 회사는 거대한 손실을 입었다."},{"id":"d6-15","day":6,"word":"immense","meaning":"거대한","ipa":"[ɪˈmens]","kr":"이멘스","example":"She felt immense relief after the exam.","exampleKr":"그녀는 시험 후 거대한 안도감을 느꼈다.","roots":"im-(부정) + mens(측정된, 라틴어 metiri) → 측정할 수 없는, 거대한"},{"id":"d6-16","day":6,"word":"stare down at","meaning":"빤히 내려다 보다","ipa":"[ster daʊn æt]","kr":"스테어 다운 앳","example":"He stared down at the letter in disbelief.","exampleKr":"그는 믿을 수 없다는 듯 편지를 빤히 내려다봤다."},{"id":"d6-17","day":6,"word":"pound","meaning":"쿵쾅거리다","ipa":"[paʊnd]","kr":"파운드","example":"Her heart pounded with excitement.","exampleKr":"그녀의 심장은 흥분으로 쿵쾅거렸다."},{"id":"d6-18","day":6,"word":"clasp","meaning":"꽉 쥐다","ipa":"[klæsp]","kr":"클래스프","example":"She clasped his hand tightly.","exampleKr":"그녀는 그의 손을 꽉 쥐었다."},{"id":"d6-19","day":6,"word":"grasp","meaning":"꽉 쥐다","ipa":"[ɡræsp]","kr":"그래스프","example":"He grasped the rope firmly.","exampleKr":"그는 밧줄을 꽉 쥐었다."},{"id":"d6-20","day":6,"word":"grip","meaning":"꽉 쥐다","ipa":"[ɡrɪp]","kr":"그립","example":"The child gripped her mother's hand.","exampleKr":"그 아이는 엄마의 손을 꽉 쥐었다."},{"id":"d6-21","day":6,"word":"trickle down","meaning":"흘러내리다","ipa":"[ˈtrɪkl daʊn]","kr":"트리클 다운","example":"Rainwater trickled down the window.","exampleKr":"빗물이 창문 아래로 흘러내렸다."},{"id":"d6-22","day":6,"word":"anxiously","meaning":"불안해하며","ipa":"[ˈæŋkʃəsli]","kr":"앵셔슬리","example":"She waited anxiously for the results.","exampleKr":"그녀는 불안해하며 결과를 기다렸다.","roots":"anx(조이다, 라틴어 angere) + -ious + -ly → 마음이 조여드는 듯 불안하게"},{"id":"d6-23","day":6,"word":"well-meaning","meaning":"선의를 담은","ipa":"[wel ˈmiːnɪŋ]","kr":"웰 미닝","example":"His well-meaning advice was unhelpful.","exampleKr":"그의 선의를 담은 조언은 도움이 되지 않았다."},{"id":"d6-24","day":6,"word":"vague","meaning":"모호한, 애매한","ipa":"[veɪɡ]","kr":"베이그","example":"She gave a vague answer to the question.","exampleKr":"그녀는 그 질문에 모호한 대답을 했다."},{"id":"d6-25","day":6,"word":"obscure","meaning":"모호한","ipa":"[əbˈskjʊr]","kr":"업스큐어","example":"The reference was too obscure for most readers.","exampleKr":"그 언급은 대부분의 독자들에게 너무 모호했다."},{"id":"d6-26","day":6,"word":"blurred","meaning":"모호한","ipa":"[blɜːrd]","kr":"블러드","example":"The photo was blurred due to movement.","exampleKr":"그 사진은 움직임 때문에 흐릿했다."},{"id":"d6-27","day":6,"word":"fuzzy","meaning":"모호한","ipa":"[ˈfʌzi]","kr":"퍼지","example":"His memory of that night is fuzzy.","exampleKr":"그날 밤에 대한 그의 기억은 모호하다."},{"id":"d6-28","day":6,"word":"for the sake of","meaning":"~을 위해서","ipa":"[fɔːr ðə seɪk əv]","kr":"포 더 세이크 오브","example":"She apologized for the sake of peace.","exampleKr":"그녀는 평화를 위해서 사과했다."},{"id":"d6-29","day":6,"word":"politeness","meaning":"예의","ipa":"[pəˈlaɪtnəs]","kr":"펄라이트니스","example":"He answered out of politeness.","exampleKr":"그는 예의상 대답했다.","roots":"polit(닦다, 라틴어 polire) + -e + -ness → 매끄럽게 다듬어진 태도, 예의"},{"id":"d6-30","day":6,"word":"overwhelming","meaning":"버거운, 감당하기 힘든","ipa":"[ˌoʊvərˈwelmɪŋ]","kr":"오버웰밍","example":"The support from fans was overwhelming.","exampleKr":"팬들의 지지는 감당하기 힘들 정도였다."},{"id":"d6-31","day":6,"word":"a grocery run","meaning":"장보기","ipa":"[ə ˈɡroʊsəri rʌn]","kr":"어 그로서리 런","example":"I need to do a quick grocery run.","exampleKr":"나는 빠르게 장을 봐야 한다."},{"id":"d6-32","day":6,"word":"principle","meaning":"법칙, 원리","ipa":"[ˈprɪnsəpl]","kr":"프린서플","example":"She lives by strong moral principles.","exampleKr":"그녀는 확고한 도덕적 원리에 따라 산다.","roots":"prin(첫째, 라틴어 primus) + cip(잡다, 라틴어 capere) + -le → 맨 처음 잡아야 할 것, 원리"},{"id":"d6-33","day":6,"word":"in the case of","meaning":"~의 경우에","ipa":"[ɪn ðə keɪs əv]","kr":"인 더 케이스 오브","example":"In the case of an emergency, call this number.","exampleKr":"비상 상황의 경우, 이 번호로 전화해라."},{"id":"d6-34","day":6,"word":"minor","meaning":"작은, 사소한","ipa":"[ˈmaɪnər]","kr":"마이너","example":"It was only a minor injury.","exampleKr":"그것은 단지 작은 부상이었다."},{"id":"d6-35","day":6,"word":"trivial","meaning":"하찮은, 사소한","ipa":"[ˈtrɪviəl]","kr":"트리비얼","example":"The mistake was trivial and easily fixed.","exampleKr":"그 실수는 사소했고 쉽게 고쳐졌다.","roots":"tri-(셋) + via(길, 라틴어 via) + -al → 세 갈래 길이 만나는(누구나 아는) 곳, 하찮은"},{"id":"d6-36","day":6,"word":"trifling","meaning":"하찮은, 사소한","ipa":"[ˈtraɪflɪŋ]","kr":"트라이플링","example":"He got upset over a trifling issue.","exampleKr":"그는 하찮은 문제로 화를 냈다."},{"id":"d6-37","day":6,"word":"gland","meaning":"분비샘","ipa":"[ɡlænd]","kr":"글랜드","example":"The thyroid gland regulates metabolism.","exampleKr":"갑상선 분비샘은 신진대사를 조절한다."},{"id":"d6-38","day":6,"word":"compound","meaning":"화합물, 혼합물","ipa":"[ˈkɑːmpaʊnd]","kr":"캄파운드","example":"Water is a compound of hydrogen and oxygen.","exampleKr":"물은 수소와 산소의 화합물이다.","roots":"com-(함께) + pound(놓다, 라틴어 ponere) → 함께 놓은 것, 화합물"},{"id":"d6-39","day":6,"word":"signpost","meaning":"알리다","ipa":"[ˈsaɪnpoʊst]","kr":"사인포스트","example":"The road signpost pointed toward the town.","exampleKr":"도로 이정표는 마을 쪽을 알렸다."},{"id":"d6-40","day":6,"word":"colony","meaning":"군집","ipa":"[ˈkɑːləni]","kr":"칼러니","example":"The ants built a large colony underground.","exampleKr":"개미들은 지하에 큰 군집을 만들었다.","roots":"col(경작하다, 라틴어 colere) + -ony → 경작하러 정착한 곳, 군집"},{"id":"d6-41","day":6,"word":"tell ~ apart","meaning":"구별하다","ipa":"[tel əˈpɑːrt]","kr":"텔 어파트","example":"It's hard to tell the twins apart.","exampleKr":"그 쌍둥이를 구별하기는 어렵다."},{"id":"d6-42","day":6,"word":"aroma","meaning":"냄새, 향","ipa":"[əˈroʊmə]","kr":"어로우마","example":"The aroma of fresh coffee filled the kitchen.","exampleKr":"신선한 커피 향이 부엌을 가득 채웠다."},{"id":"d6-43","day":6,"word":"odor","meaning":"냄새","ipa":"[ˈoʊdər]","kr":"오우더","example":"A strange odor came from the fridge.","exampleKr":"냉장고에서 이상한 냄새가 났다."},{"id":"d6-44","day":6,"word":"scent","meaning":"냄새, 향","ipa":"[sent]","kr":"센트","example":"She recognized his scent immediately.","exampleKr":"그녀는 즉시 그의 냄새를 알아챘다."},{"id":"d6-45","day":6,"word":"identity","meaning":"정체성","ipa":"[aɪˈdentəti]","kr":"아이덴터티","example":"He struggled to find his identity.","exampleKr":"그는 자신의 정체성을 찾는 데 어려움을 겪었다.","roots":"ident(같은, 라틴어 idem) + -ity(명사형) → 같음, 정체성"},{"id":"d6-46","day":6,"word":"emblem","meaning":"상징","ipa":"[ˈembləm]","kr":"엠블럼","example":"The eagle is an emblem of freedom.","exampleKr":"독수리는 자유의 상징이다.","roots":"em-(안으로) + blem(던지다, 그리스어 ballein) → 안에 끼워 넣은 것, 상징"},{"id":"d6-47","day":6,"word":"hydrocarbons","meaning":"탄화수소","ipa":"[ˌhaɪdrəˈkɑːrbənz]","kr":"하이드러카본즈","example":"Fuel is made mostly of hydrocarbons.","exampleKr":"연료는 대부분 탄화수소로 만들어진다.","roots":"hydro-(수소, 그리스어 hydor '물') + carbon(탄소, 라틴어 carbo) → 수소와 탄소로 이루어진 화합물"},{"id":"d6-48","day":6,"word":"admit","meaning":"인정하다","ipa":"[ədˈmɪt]","kr":"어드밋","example":"He admitted his mistake right away.","exampleKr":"그는 즉시 자신의 실수를 인정했다.","roots":"ad-(~쪽으로) + mit(보내다, 라틴어 mittere) → 안으로 들여보내다, 인정하다"},{"id":"d6-49","day":6,"word":"recognize","meaning":"인정하다","ipa":"[ˈrekəɡnaɪz]","kr":"레커그나이즈","example":"She recognized him from the photo.","exampleKr":"그녀는 사진에서 그를 알아봤다.","roots":"re-(다시) + cogn(알다, 라틴어 cognoscere) + -ize → 다시 알아보다, 인정하다"},{"id":"d6-50","day":6,"word":"acknowledge","meaning":"인정하다","ipa":"[əkˈnɑːlɪdʒ]","kr":"억날리지","example":"The company acknowledged the error publicly.","exampleKr":"그 회사는 그 오류를 공개적으로 인정했다."},{"id":"d6-51","day":6,"word":"flag pin","meaning":"국기 배지","ipa":"[flæɡ pɪn]","kr":"플래그 핀","example":"He wore a small flag pin on his jacket.","exampleKr":"그는 재킷에 작은 국기 배지를 달았다."},{"id":"d6-52","day":6,"word":"detect","meaning":"감지하다","ipa":"[dɪˈtekt]","kr":"디텍트","example":"The dog can detect the smell of drugs.","exampleKr":"그 개는 마약 냄새를 감지할 수 있다.","roots":"de-(제거) + tect(덮다, 라틴어 tegere) → 덮개를 벗기다, 감지하다"},{"id":"d6-53","day":6,"word":"defect","meaning":"결점","ipa":"[ˈdiːfekt]","kr":"디펙트","example":"The product was returned due to a defect.","exampleKr":"그 제품은 결점 때문에 반품되었다.","roots":"de-(잘못된 방향으로) + fect(만들다, 라틴어 facere) → 잘못 만들어진 것, 결점"},{"id":"d6-54","day":6,"word":"defer","meaning":"연기하다","ipa":"[dɪˈfɜːr]","kr":"디퍼","example":"They decided to defer the decision.","exampleKr":"그들은 그 결정을 연기하기로 했다."},{"id":"d6-55","day":6,"word":"deter","meaning":"단념시키다, 막다","ipa":"[dɪˈtɜːr]","kr":"디터","example":"Higher prices may deter buyers.","exampleKr":"높은 가격은 구매자를 단념시킬 수 있다.","roots":"de-(멀리) + ter(겁주다, 라틴어 terrere) → 겁주어 멀리하게 하다, 단념시키다"},{"id":"d6-56","day":6,"word":"alien","meaning":"이질적인, 이국적인","ipa":"[ˈeɪliən]","kr":"에일리언","example":"The customs felt alien to the newcomers.","exampleKr":"그 관습은 신입자들에게 이질적으로 느껴졌다.","roots":"ali(다른, 라틴어 alius) + -en(형용사형) → 다른 것에 속한, 이질적인"},{"id":"d6-57","day":6,"word":"exotic","meaning":"이국적인","ipa":"[ɪɡˈzɑːtɪk]","kr":"이그자틱","example":"They tasted exotic fruits on their trip.","exampleKr":"그들은 여행에서 이국적인 과일을 맛봤다.","roots":"ex-(밖) + ot(바깥의, 그리스어 exo) + -ic → 바깥에서 온, 이국적인"},{"id":"d6-58","day":6,"word":"surrender","meaning":"항복","ipa":"[səˈrendər]","kr":"서렌더","example":"The army refused to surrender.","exampleKr":"그 군대는 항복을 거부했다.","roots":"sur-(완전히, 라틴어 super-) + render(돌려주다, 고대 프랑스어 rendre) → 완전히 돌려줌, 항복"},{"id":"d6-59","day":6,"word":"more often than not","meaning":"대개, 자주","ipa":"[mɔːr ˈɔːfən ðæn nɑːt]","kr":"모어 오펀 댄 낫","example":"More often than not, the bus is late.","exampleKr":"대개, 그 버스는 늦는다."},{"id":"d6-60","day":6,"word":"state","meaning":"말하다, 진술하다","ipa":"[steɪt]","kr":"스테이트","example":"He stated his opinion clearly.","exampleKr":"그는 자신의 의견을 명확하게 말했다."},{"id":"d6-61","day":6,"word":"available","meaning":"이용가능한","ipa":"[əˈveɪləbl]","kr":"어베일러블","example":"Tickets are still available online.","exampleKr":"티켓은 아직 온라인으로 이용 가능하다.","roots":"a-(~을 향해, 라틴어 ad-) + vail(가치있다, 라틴어 valere) + -able → 가치 있게 쓸 수 있는, 이용 가능한"},{"id":"d6-62","day":6,"word":"completion","meaning":"완수","ipa":"[kəmˈpliːʃn]","kr":"컴플리션","example":"The project neared completion.","exampleKr":"그 프로젝트는 완수에 가까워졌다.","roots":"com-(완전히) + ple(채우다, 라틴어 plere) + -tion → 완전히 채움, 완수"},{"id":"d6-63","day":6,"word":"allot","meaning":"할당하다","ipa":"[əˈlɑːt]","kr":"얼랏","example":"Each team was allotted an hour to present.","exampleKr":"각 팀에게 발표 시간이 한 시간 할당되었다."},{"id":"d6-64","day":6,"word":"assign","meaning":"할당하다","ipa":"[əˈsaɪn]","kr":"어사인","example":"The teacher assigned homework for the weekend.","exampleKr":"선생님은 주말 숙제를 할당했다.","roots":"as-(~에게, 라틴어 ad-) + sign(표시하다, 라틴어 signare) → ~에게 표시해 주다, 할당하다"},{"id":"d6-65","day":6,"word":"allocate","meaning":"할당하다","ipa":"[ˈæləkeɪt]","kr":"앨러케이트","example":"The budget was allocated to different departments.","exampleKr":"그 예산은 여러 부서에 할당되었다.","roots":"al-(~에게, 라틴어 ad-) + loc(장소, 라틴어 locus) + -ate → 자리를 정해 주다, 할당하다"},{"id":"d6-66","day":6,"word":"impose","meaning":"부과하다","ipa":"[ɪmˈpoʊz]","kr":"임포우즈","example":"The government imposed new taxes.","exampleKr":"정부는 새로운 세금을 부과했다.","roots":"im-(위에) + pos(e)(놓다, 라틴어 ponere) → 위에 놓다, 부과하다"},{"id":"d6-67","day":6,"word":"define","meaning":"규정하다","ipa":"[dɪˈfaɪn]","kr":"디파인","example":"Success is hard to define.","exampleKr":"성공을 규정하기는 어렵다.","roots":"de-(완전히) + fin(경계, 라틴어 finis) + -e → 경계를 완전히 짓다, 규정하다"},{"id":"d6-68","day":6,"word":"refine","meaning":"정제하다, 개선하다","ipa":"[rɪˈfaɪn]","kr":"리파인","example":"She refined her essay before submitting it.","exampleKr":"그녀는 제출하기 전에 에세이를 다듬었다.","roots":"re-(다시) + fin(끝/순수함, 라틴어 finis) + -e → 다시 순수하게 다듬다, 정제하다"},{"id":"d6-69","day":6,"word":"confine","meaning":"제한하다","ipa":"[kənˈfaɪn]","kr":"컨파인","example":"The patient was confined to bed rest.","exampleKr":"그 환자는 침대 안정에 제한되었다.","roots":"con-(완전히) + fin(경계, 라틴어 finis) + -e → 경계 안에 가두다, 제한하다"},{"id":"d6-70","day":6,"word":"challenging","meaning":"도전적인, 어려운","ipa":"[ˈtʃælɪndʒɪŋ]","kr":"챌린징","example":"The exam was more challenging than expected.","exampleKr":"그 시험은 예상보다 더 도전적이었다."},{"id":"d6-71","day":6,"word":"competition","meaning":"경쟁","ipa":"[ˌkɑːmpəˈtɪʃn]","kr":"캄퍼티션","example":"There is fierce competition in the market.","exampleKr":"그 시장에는 치열한 경쟁이 있다.","roots":"com-(함께) + pet(추구하다, 라틴어 petere) + -ition → 함께 추구함, 경쟁"},{"id":"d6-72","day":6,"word":"accomplishment","meaning":"성취(감)","ipa":"[əˈkɑːmplɪʃmənt]","kr":"어캄플리시먼트","example":"Graduating was a great accomplishment for her.","exampleKr":"졸업은 그녀에게 큰 성취였다.","roots":"ac-(~을 향해, 라틴어 ad-) + compl(채우다, 라틴어 complere) + -ish + -ment → 완전히 채워 이룸, 성취(감)"},{"id":"d6-73","day":6,"word":"at hand","meaning":"당면한, 직면한","ipa":"[æt hænd]","kr":"앳 핸드","example":"The tools were kept close at hand.","exampleKr":"도구들은 가까이 당면하게 보관되었다."},{"id":"d6-74","day":6,"word":"internal","meaning":"내면의","ipa":"[ɪnˈtɜːrnl]","kr":"인터늘","example":"The company faced internal conflicts.","exampleKr":"그 회사는 내부적인 갈등에 직면했다."},{"id":"d6-75","day":6,"word":"external","meaning":"외부의","ipa":"[ɪkˈstɜːrnl]","kr":"익스터늘","example":"External factors affected the stock price.","exampleKr":"외부 요인이 주가에 영향을 미쳤다."},{"id":"d6-76","day":6,"word":"motivate","meaning":"동기부여하다","ipa":"[ˈmoʊtɪveɪt]","kr":"모우티베이트","example":"Bonuses can motivate employees to work harder.","exampleKr":"보너스는 직원들이 더 열심히 일하도록 동기부여할 수 있다.","roots":"mot(움직이다, 라틴어 movere) + -ive + -ate → 움직이게 만들다, 동기부여하다"},{"id":"d6-77","day":6,"word":"in the long run","meaning":"결국","ipa":"[ɪn ðə lɔːŋ rʌn]","kr":"인 더 롱 런","example":"Saving money helps in the long run.","exampleKr":"돈을 저축하는 것은 결국 도움이 된다."},{"id":"d6-78","day":6,"word":"appreciate","meaning":"진가를 알아보다","ipa":"[əˈpriːʃieɪt]","kr":"어프리시에이트","example":"She appreciates good music.","exampleKr":"그녀는 좋은 음악의 진가를 안다.","roots":"ap-(~쪽으로, 라틴어 ad-) + preci(값, 라틴어 pretium) + -ate → 가치를 매기다, 진가를 알아보다"},{"id":"d6-79","day":6,"word":"vastly","meaning":"대단히","ipa":"[ˈvæstli]","kr":"배스틀리","example":"The two plans are vastly different.","exampleKr":"그 두 계획은 대단히 다르다."},{"id":"d6-80","day":6,"word":"sophisticated","meaning":"복잡한","ipa":"[səˈfɪstɪkeɪtɪd]","kr":"서피스티케이티드","example":"The city has a sophisticated transit system.","exampleKr":"그 도시는 복잡한 교통 시스템을 가지고 있다.","roots":"soph(지혜, 그리스어 sophos) + -isticate + -ed → 기교를 부려 다듬어진, 복잡한"},{"id":"d6-81","day":6,"word":"intricate","meaning":"복잡한","ipa":"[ˈɪntrɪkət]","kr":"인트리컷","example":"The necklace has an intricate design.","exampleKr":"그 목걸이는 복잡한 디자인을 가지고 있다.","roots":"in-(안으로) + tric(성가신 일, 라틴어 tricae) + -ate → 안으로 얽혀 든, 복잡한"},{"id":"d6-82","day":6,"word":"underlying","meaning":"기저에 있는","ipa":"[ˌʌndərˈlaɪɪŋ]","kr":"언덜라잉","example":"There is an underlying issue we need to address.","exampleKr":"우리가 다뤄야 할 기저에 있는 문제가 있다."},{"id":"d6-83","day":6,"word":"be devoted to","meaning":"~에 전념하다","ipa":"[bi dɪˈvoʊtɪd tuː]","kr":"비 디보우티드 투","example":"She is devoted to her family.","exampleKr":"그녀는 가족에게 전념한다."},{"id":"d6-84","day":6,"word":"unambiguously","meaning":"명확하게","ipa":"[ˌʌnæmˈbɪɡjuəsli]","kr":"언앰비규어슬리","example":"He unambiguously supported the proposal.","exampleKr":"그는 명확하게 그 제안을 지지했다.","roots":"un-(부정) + ambi-(양쪽으로) + ig(이끌다, 라틴어 agere) + -ous + -ly → 양쪽으로 헷갈리지 않게, 명확하게"},{"id":"d6-85","day":6,"word":"interpret","meaning":"해석하다","ipa":"[ɪnˈtɜːrprɪt]","kr":"인터프릿","example":"She interpreted his silence as agreement.","exampleKr":"그녀는 그의 침묵을 동의로 해석했다.","roots":"inter-(사이에서) + pret(중개하다, 라틴어 interpres) → 사이에서 중개하여 설명하다, 해석하다"},{"id":"d6-86","day":6,"word":"photons","meaning":"빛의 요소가 되는 입자","ipa":"[ˈfoʊtɑːnz]","kr":"포우탄즈","example":"Photons carry light energy.","exampleKr":"광자는 빛 에너지를 나른다.","roots":"phot(빛, 그리스어 phos) + -on(입자 접미사) → 빛의 입자"},{"id":"d6-87","day":6,"word":"stream into","meaning":"~로 흘러들어 가다","ipa":"[striːm ˈɪntuː]","kr":"스트림 인투","example":"Sunlight streamed into the room.","exampleKr":"햇빛이 방으로 흘러들어 왔다."},{"id":"d6-88","day":6,"word":"strictly speaking","meaning":"엄밀하게 말해서","ipa":"[ˈstrɪktli ˈspiːkɪŋ]","kr":"스트릭틀리 스피킹","example":"Strictly speaking, a tomato is a fruit.","exampleKr":"엄밀하게 말해서, 토마토는 과일이다."},{"id":"d6-89","day":6,"word":"go through","meaning":"겪다","ipa":"[ɡoʊ θruː]","kr":"고우 쓰루","example":"She went through the documents carefully.","exampleKr":"그녀는 서류를 꼼꼼히 검토했다."},{"id":"d6-90","day":6,"word":"undergo","meaning":"겪다","ipa":"[ˌʌndərˈɡoʊ]","kr":"언더고우","example":"The company underwent major changes.","exampleKr":"그 회사는 큰 변화를 겪었다."},{"id":"d6-91","day":6,"word":"suffer","meaning":"겪다","ipa":"[ˈsʌfər]","kr":"서퍼","example":"He suffered a minor injury during practice.","exampleKr":"그는 연습 중에 작은 부상을 겪었다.","roots":"suf-(아래에서, 라틴어 sub-) + fer(나르다, 라틴어 ferre) → 아래에서 짊어지고 나르다, 겪다"},{"id":"d6-92","day":6,"word":"ambiguous","meaning":"모호한","ipa":"[æmˈbɪɡjuəs]","kr":"앰비규어스","example":"The instructions were ambiguous.","exampleKr":"그 설명은 모호했다.","roots":"ambi-(양쪽으로) + ig(이끌다, 라틴어 agere) + -ous → 양쪽으로 이끌리는, 모호한"},{"id":"d6-93","day":6,"word":"disambiguate","meaning":"명확하게 하다","ipa":"[ˌdɪsæmˈbɪɡjueɪt]","kr":"디스앰비규에이트","example":"The editor added notes to disambiguate the term.","exampleKr":"편집자는 그 용어를 명확하게 하기 위해 메모를 추가했다.","roots":"dis-(제거) + ambigu(모호한, 라틴어 ambiguus) + -ate → 모호함을 없애다, 명확하게 하다"},{"id":"d6-94","day":6,"word":"take ~ into account","meaning":"~을 고려하다","ipa":"[teɪk ˈɪntuː əˈkaʊnt]","kr":"테이크 인투 어카운트","example":"You should take her feelings into account.","exampleKr":"너는 그녀의 감정을 고려해야 한다."},{"id":"d6-95","day":6,"word":"assumption","meaning":"가정","ipa":"[əˈsʌmpʃn]","kr":"어섬션","example":"His argument was based on a false assumption.","exampleKr":"그의 주장은 잘못된 가정에 근거했다.","roots":"as-(~에게, 라틴어 ad-) + sump(취하다, 라틴어 sumere) + -tion → 자기 것으로 취함, 가정"},{"id":"d6-96","day":6,"word":"effortlessly","meaning":"쉽게","ipa":"[ˈefərtləsli]","kr":"에퍼틀리슬리","example":"She solved the problem effortlessly.","exampleKr":"그녀는 그 문제를 쉽게 풀었다.","roots":"ef-(밖으로, 라틴어 ex-) + fort(강한, 라틴어 fortis) + -less + -ly → 힘을 쏟지 않고, 쉽게"},{"id":"d6-97","day":6,"word":"demonstrate","meaning":"증명하다","ipa":"[ˈdemənstreɪt]","kr":"데먼스트레이트","example":"The video demonstrates how the machine works.","exampleKr":"그 영상은 그 기계가 어떻게 작동하는지 설명한다.","roots":"de-(완전히) + monstr(보여주다, 라틴어 monstrare) + -ate → 완전히 보여주다, 증명하다"},{"id":"d6-98","day":6,"word":"surgically","meaning":"수술로, 외과적으로","ipa":"[ˈsɜːrdʒɪkli]","kr":"서지클리","example":"The tumor was surgically removed.","exampleKr":"그 종양은 수술로 제거되었다.","roots":"cheir(손, 그리스어 kheir) + urg(일하다, 그리스어 ergon) + -ical + -ly → 손으로 작업하듯, 수술로"},{"id":"d6-99","day":6,"word":"chaotic","meaning":"혼란스러운","ipa":"[keɪˈɑːtɪk]","kr":"케이아틱","example":"The scene at the airport was chaotic.","exampleKr":"공항의 상황은 혼란스러웠다."},{"id":"d6-100","day":6,"word":"optics of the eyes","meaning":"시력, 눈의 광학","ipa":"[ˈɑːptɪks əv ði aɪz]","kr":"압틱스 오브 디 아이즈","example":"The lecture covered the optics of the eyes.","exampleKr":"그 강의는 눈의 광학을 다뤘다."},{"id":"d7-1","day":7,"word":"integrated","meaning":"통합된","ipa":"[ˈɪntɪɡreɪtɪd]","kr":"인티그레이티드","example":"The school offers an integrated curriculum.","exampleKr":"그 학교는 통합된 교과 과정을 제공한다.","roots":"in-(부정, ~않은) + tegr(건드리다, 라틴어 tangere) + -ate(동사형) → 손대지 않아 온전하게 하나로 만들다, 통합하다"},{"id":"d7-2","day":7,"word":"integral","meaning":"완전한, 중요한","ipa":"[ˈɪntɪɡrəl]","kr":"인티그럴","example":"Teamwork is integral to our success.","exampleKr":"팀워크는 우리 성공에 필수적이다.","roots":"in-(부정) + tegr(건드리다, 라틴어 tangere) + -al(형용사형) → 손대지 않아 온전한, 완전한·중요한"},{"id":"d7-3","day":7,"word":"realign","meaning":"재정렬하다","ipa":"[ˌriːəˈlaɪn]","kr":"리얼라인","example":"The company had to realign its strategy.","exampleKr":"그 회사는 전략을 재정렬해야 했다.","roots":"re-(다시) + align(한 줄로 맞추다, 프랑스어 aligner, 라틴어 linea 선) → 다시 정렬하다"},{"id":"d7-4","day":7,"word":"assessment","meaning":"평가","ipa":"[əˈsesmənt]","kr":"어세스먼트","example":"The teacher gave a fair assessment of her work.","exampleKr":"선생님은 그녀의 작업에 대해 공정한 평가를 했다.","roots":"as-(~옆에) + sess(앉다, 라틴어 sedere) + -ment(명사형) → 옆에 앉아 살피는 것, 평가"},{"id":"d7-5","day":7,"word":"appraisal","meaning":"평가","ipa":"[əˈpreɪzl]","kr":"어프레이즐","example":"The house received a positive appraisal.","exampleKr":"그 집은 긍정적인 평가를 받았다.","roots":"ap-(~에게) + prais(e)(값을 매기다, 라틴어 pretiare) + -al(명사형) → 값을 매기는 것, 평가"},{"id":"d7-6","day":7,"word":"evaluation","meaning":"평가","ipa":"[ɪˌvæljuˈeɪʃn]","kr":"이밸류에이션","example":"The employee's evaluation was excellent.","exampleKr":"그 직원의 평가는 뛰어났다.","roots":"e-(밖으로) + valu(e)(가치, 라틴어 valere) + -ation(명사형) → 가치를 끌어내어 매기는 것, 평가"},{"id":"d7-7","day":7,"word":"carry weight","meaning":"중요한 의미를 갖다","ipa":"[ˈkæri weɪt]","kr":"캐리 웨이트","example":"His opinion carries a lot of weight here.","exampleKr":"그의 의견은 여기서 중요한 의미를 갖는다."},{"id":"d7-8","day":7,"word":"override","meaning":"~보다 우선시 하다","ipa":"[ˌoʊvərˈraɪd]","kr":"오버라이드","example":"The manager overrode the committee's decision.","exampleKr":"그 매니저는 위원회의 결정보다 우선시했다."},{"id":"d7-9","day":7,"word":"reverse","meaning":"뒤집다, 반대의","ipa":"[rɪˈvɜːrs]","kr":"리버스","example":"He reversed the car out of the driveway.","exampleKr":"그는 차를 후진시켜 진입로를 빠져나갔다.","roots":"re-(뒤로) + vers(e)(돌다, 라틴어 vertere) → 뒤로 돌리다, 뒤집다"},{"id":"d7-10","day":7,"word":"adverse","meaning":"반대의","ipa":"[ˈædvɜːrs]","kr":"애드버스","example":"The drug has some adverse side effects.","exampleKr":"그 약은 몇 가지 반대의 부작용이 있다.","roots":"ad-(~을 향해) + vers(e)(돌다, 라틴어 vertere) → ~을 향해 거스르며 돌아선, 반대의"},{"id":"d7-11","day":7,"word":"converse","meaning":"반대의, 대화하다","ipa":"[ˈkɑːnvɜːrs]","kr":"칸버스","example":"The converse of the statement is also true.","exampleKr":"그 진술의 반대도 사실이다.","roots":"con-(함께/반대로) + vers(e)(돌다, 라틴어 vertere) → 함께 돌며 말을 주고받다(대화하다), 돌아서 마주한(반대의)"},{"id":"d7-12","day":7,"word":"contrary","meaning":"반대의","ipa":"[ˈkɑːntreri]","kr":"칸트레리","example":"Contrary to expectations, the plan succeeded.","exampleKr":"예상과는 반대로, 그 계획은 성공했다.","roots":"contra-(반대로, 라틴어 contra) + -ary(형용사형) → 반대되는"},{"id":"d7-13","day":7,"word":"counter","meaning":"반대의","ipa":"[ˈkaʊntər]","kr":"카운터","example":"His argument ran counter to the facts.","exampleKr":"그의 주장은 사실과 반대로 진행되었다."},{"id":"d7-14","day":7,"word":"striking","meaning":"두드러진","ipa":"[ˈstraɪkɪŋ]","kr":"스트라이킹","example":"There was a striking similarity between the two paintings.","exampleKr":"두 그림 사이에는 두드러진 유사성이 있었다."},{"id":"d7-15","day":7,"word":"prominent","meaning":"두드러진","ipa":"[ˈprɑːmɪnənt]","kr":"프라미넌트","example":"She holds a prominent position in the industry.","exampleKr":"그녀는 업계에서 두드러진 위치를 가지고 있다.","roots":"pro-(앞으로) + min(돌출하다, 라틴어 minere) + -ent(형용사형) → 앞으로 튀어나온, 두드러진"},{"id":"d7-16","day":7,"word":"remarkable","meaning":"두드러진","ipa":"[rɪˈmɑːrkəbl]","kr":"리마커블","example":"He made a remarkable recovery after surgery.","exampleKr":"그는 수술 후 놀랄 만한 회복을 했다.","roots":"re-(강조) + mark(표시하다, 프랑스어 remarquer) + -able(~할 수 있는) → 표시해 둘 만큼 눈에 띄는, 두드러진"},{"id":"d7-17","day":7,"word":"be paired with","meaning":"~와 짝을 이루다","ipa":"[bi perd wɪð]","kr":"비 페어드 위드","example":"Red wine is often paired with steak.","exampleKr":"레드와인은 종종 스테이크와 짝을 이룬다."},{"id":"d7-18","day":7,"word":"vice versa","meaning":"그 반대도 마찬가지이다","ipa":"[ˌvaɪsəˈvɜːrsə]","kr":"바이서버서","example":"He helps her, and vice versa.","exampleKr":"그는 그녀를 돕고, 그 반대도 마찬가지이다."},{"id":"d7-19","day":7,"word":"impression","meaning":"감상, 인상","ipa":"[ɪmˈpreʃn]","kr":"임프레션","example":"She made a good first impression.","exampleKr":"그녀는 좋은 첫인상을 남겼다.","roots":"im-(안으로) + press(누르다, 라틴어 premere) + -ion(명사형) → 안으로 눌러 새겨진 것, 인상"},{"id":"d7-20","day":7,"word":"reliably","meaning":"확실히","ipa":"[rɪˈlaɪəbli]","kr":"릴라이어블리","example":"The results reliably predict future outcomes.","exampleKr":"그 결과는 확실히 미래 결과를 예측한다.","roots":"re-(강조) + ly(묶다, 프랑스어 lier, 라틴어 ligare) + -able + -ly → 굳게 묶여 의지할 만하게, 확실히"},{"id":"d7-21","day":7,"word":"obviously","meaning":"확실히","ipa":"[ˈɑːbviəsli]","kr":"압비어슬리","example":"Obviously, she was upset about the news.","exampleKr":"확실히, 그녀는 그 소식에 화가 났다.","roots":"ob-(앞에) + vi(a)(길, 라틴어 via) + -ous + -ly → 길 앞에 나와 있어 뚜렷하게, 확실히"},{"id":"d7-22","day":7,"word":"definitely","meaning":"확실히","ipa":"[ˈdefɪnətli]","kr":"데퍼니틀리","example":"I will definitely attend the wedding.","exampleKr":"나는 확실히 결혼식에 참석할 것이다.","roots":"de-(완전히) + fin(경계, 라틴어 finis) + -ite + -ly → 경계를 확실히 지어, 분명히"},{"id":"d7-23","day":7,"word":"architect","meaning":"건축가","ipa":"[ˈɑːrkɪtekt]","kr":"아키텍트","example":"The architect designed the new museum.","exampleKr":"그 건축가는 새 박물관을 설계했다.","roots":"archi-(으뜸, 그리스어 arkhi) + tect(짓는 사람, 그리스어 tekton) → 으뜸가는 건축 기술자"},{"id":"d7-24","day":7,"word":"excel in","meaning":"~에서 뛰어나다","ipa":"[ɪkˈsel ɪn]","kr":"익셀 인","example":"She excels in mathematics.","exampleKr":"그녀는 수학에서 뛰어나다.","roots":"ex-(밖으로/위로) + cel(l)(높은, 라틴어 celsus) → 남들보다 위로 뛰어나다"},{"id":"d7-25","day":7,"word":"athletics","meaning":"운동, 육상경기","ipa":"[æθˈletɪks]","kr":"애쓸레틱스","example":"He was a star in high school athletics.","exampleKr":"그는 고등학교 육상경기에서 스타였다.","roots":"athl(경기를 겨루다·상, 그리스어 athlon) + -et(e) + -ics(활동 접미사) → 상을 걸고 겨루는 것, 운동경기"},{"id":"d7-26","day":7,"word":"apply to","meaning":"~에 지원하다","ipa":"[əˈplaɪ tuː]","kr":"어플라이 투","example":"She applied to five universities.","exampleKr":"그녀는 다섯 개 대학에 지원했다.","roots":"ap-(~에) + ply(접다·붙이다, 라틴어 plicare) → ~에 갖다 붙이다, 지원하다"},{"id":"d7-27","day":7,"word":"admission","meaning":"입학","ipa":"[ədˈmɪʃn]","kr":"어드미션","example":"Admission to the university is highly competitive.","exampleKr":"그 대학의 입학은 경쟁이 매우 치열하다.","roots":"ad-(~로) + miss(보내다, 라틴어 mittere) + -ion(명사형) → 안으로 들여보냄, 입학"},{"id":"d7-28","day":7,"word":"architectural","meaning":"건축(분야)의","ipa":"[ˌɑːrkɪˈtektʃərəl]","kr":"아키텍처럴","example":"The building has unique architectural details.","exampleKr":"그 건물은 독특한 건축적 세부 요소를 가지고 있다.","roots":"archi-(으뜸, 그리스어 arkhi) + tect(짓는 사람, 그리스어 tekton) + -ural(형용사형) → 건축과 관련된"},{"id":"d7-29","day":7,"word":"contribute to","meaning":"~에 기여하다","ipa":"[kənˈtrɪbjuːt tuː]","kr":"컨트리뷰트 투","example":"Exercise contributes to good health.","exampleKr":"운동은 좋은 건강에 기여한다.","roots":"con-(함께) + tribut(e)(나누어주다, 라틴어 tribuere) → 함께 나누어 보태다, 기여하다"},{"id":"d7-30","day":7,"word":"lend oneself to","meaning":"~에 기여하다","ipa":"[lend wʌnˈself tuː]","kr":"렌드 원셀프 투","example":"The story lends itself to a film adaptation.","exampleKr":"그 이야기는 영화화에 적합하다."},{"id":"d7-31","day":7,"word":"urban","meaning":"도시의","ipa":"[ˈɜːrbən]","kr":"어번","example":"Urban areas are growing rapidly.","exampleKr":"도시 지역은 빠르게 성장하고 있다.","roots":"urb(도시, 라틴어 urbs) + -an(형용사형) → 도시의"},{"id":"d7-32","day":7,"word":"suburb","meaning":"교외","ipa":"[ˈsʌbɜːrb]","kr":"서버브","example":"They moved to a suburb outside the city.","exampleKr":"그들은 도시 외곽의 교외로 이사했다.","roots":"sub-(아래·근처) + urb(도시, 라틴어 urbs) → 도시 근처, 교외"},{"id":"d7-33","day":7,"word":"outskirt","meaning":"교외","ipa":"[ˈaʊtskɜːrt]","kr":"아웃스커트","example":"The factory is located on the outskirts of town.","exampleKr":"그 공장은 마을 교외에 위치해 있다."},{"id":"d7-34","day":7,"word":"rural","meaning":"시골의","ipa":"[ˈrʊrəl]","kr":"루럴","example":"They enjoy the peace of rural life.","exampleKr":"그들은 시골 생활의 평화를 즐긴다.","roots":"rur(시골, 라틴어 rus) + -al(형용사형) → 시골의"},{"id":"d7-35","day":7,"word":"triangular","meaning":"삼각형 모양의","ipa":"[traɪˈæŋɡjələr]","kr":"트라이앵귤러","example":"The sign has a triangular shape.","exampleKr":"그 표지판은 삼각형 모양이다.","roots":"tri-(셋, 라틴어) + angul(각, 라틴어 angulus) + -ar(형용사형) → 세 개의 각을 가진, 삼각형의"},{"id":"d7-36","day":7,"word":"extensively","meaning":"광범위하게","ipa":"[ɪkˈstensɪvli]","kr":"익스텐시블리","example":"The topic has been studied extensively.","exampleKr":"그 주제는 광범위하게 연구되었다.","roots":"ex-(밖으로) + tens(뻗다, 라틴어 tendere) + -ive + -ly → 밖으로 널리 뻗어서, 광범위하게"},{"id":"d7-37","day":7,"word":"far-reaching","meaning":"광범위한","ipa":"[ˌfɑːrˈriːtʃɪŋ]","kr":"파리칭","example":"The policy had far-reaching effects.","exampleKr":"그 정책은 광범위한 영향을 미쳤다."},{"id":"d7-38","day":7,"word":"a range of","meaning":"광범위한","ipa":"[ə reɪndʒ əv]","kr":"어 레인지 오브","example":"The gym offers a range of classes.","exampleKr":"그 헬스장은 광범위한 수업을 제공한다."},{"id":"d7-39","day":7,"word":"by the time","meaning":"~할 무렵에","ipa":"[baɪ ðə taɪm]","kr":"바이 더 타임","example":"By the time we arrived, the show had started.","exampleKr":"우리가 도착할 무렵, 공연은 시작되어 있었다."},{"id":"d7-40","day":7,"word":"significant","meaning":"중요한, 상당한","ipa":"[sɪɡˈnɪfɪkənt]","kr":"시그니피컨트","example":"There was a significant increase in sales.","exampleKr":"매출에 상당한 증가가 있었다.","roots":"sign(표시, 라틴어 signum) + -i- + -fic(만들다, 라틴어 facere) + -ant(형용사형) → 표시를 만들어 내는, 중요한·상당한"},{"id":"d7-41","day":7,"word":"substantial","meaning":"중요한, 상당한","ipa":"[səbˈstænʃl]","kr":"섭스탠셜","example":"They made substantial progress this month.","exampleKr":"그들은 이번 달에 상당한 진전을 이뤘다.","roots":"sub-(아래에) + stan(서다, 라틴어 stare) + -tial(형용사형) → 아래에 굳건히 서 있는, 실체가 있는·중요한"},{"id":"d7-42","day":7,"word":"integral","meaning":"중요한","ipa":"[ˈɪntɪɡrəl]","kr":"인티그럴","example":"Data is integral to decision-making.","exampleKr":"데이터는 의사 결정에 중요하다.","roots":"in-(부정) + tegr(건드리다, 라틴어 tangere) + -al(형용사형) → 손대지 않아 온전한, 중요한"},{"id":"d7-43","day":7,"word":"on-ice","meaning":"빙상의","ipa":"[ɑːn aɪs]","kr":"온 아이스","example":"The team held an on-ice practice session.","exampleKr":"그 팀은 빙상 연습 세션을 가졌다."},{"id":"d7-44","day":7,"word":"registration","meaning":"등록","ipa":"[ˌredʒɪˈstreɪʃn]","kr":"레지스트레이션","example":"Registration for the class closes on Friday.","exampleKr":"그 수업 등록은 금요일에 마감된다.","roots":"re-(다시) + gist(er)(기록하다·나르다, 라틴어 gerere) + -ation(명사형) → 다시 기록해 넣음, 등록"},{"id":"d7-45","day":7,"word":"regular price","meaning":"정상가격, 정가","ipa":"[ˈreɡjələr praɪs]","kr":"레귤러 프라이스","example":"The item is now half of the regular price.","exampleKr":"그 물건은 이제 정상가격의 절반이다.","roots":"regul(자·규칙, 라틴어 regula) + -ar(형용사형) → 규칙에 맞는, 정상[가격]의"},{"id":"d7-46","day":7,"word":"rental fee","meaning":"대여료","ipa":"[ˈrentl fiː]","kr":"렌틀 피","example":"The rental fee includes insurance.","exampleKr":"대여료에는 보험이 포함된다."},{"id":"d7-47","day":7,"word":"gear","meaning":"장비","ipa":"[ɡɪr]","kr":"기어","example":"He packed all his camping gear.","exampleKr":"그는 캠핑 장비를 모두 챙겼다."},{"id":"d7-48","day":7,"word":"apparatus","meaning":"장치, 기구","ipa":"[ˌæpəˈrætəs]","kr":"애퍼래터스","example":"The lab uses complex apparatus for testing.","exampleKr":"그 실험실은 검사를 위해 복잡한 장치를 사용한다.","roots":"ap-(~쪽으로) + para(t)(준비하다, 라틴어 parare) + -us(명사형) → 준비해 갖춘 것, 장치"},{"id":"d7-49","day":7,"word":"device","meaning":"장치","ipa":"[dɪˈvaɪs]","kr":"디바이스","example":"She bought a new device to track her sleep.","exampleKr":"그녀는 수면을 추적할 새 장치를 샀다.","roots":"de-(분리) + vis(e)(나누어 고안하다, 고대 프랑스어 deviser, 라틴어 dividere 나누다) → 나누어 고안해 낸 것, 장치"},{"id":"d7-50","day":7,"word":"gadget","meaning":"장치","ipa":"[ˈɡædʒɪt]","kr":"개짓","example":"He loves buying the latest tech gadgets.","exampleKr":"그는 최신 기술 장치를 사는 것을 좋아한다."},{"id":"d7-51","day":7,"word":"occasion","meaning":"행사","ipa":"[əˈkeɪʒn]","kr":"어케이전","example":"The party was held for a special occasion.","exampleKr":"그 파티는 특별한 행사를 위해 열렸다.","roots":"oc-(~쪽으로) + cas(떨어지다, 라틴어 cadere) + -ion(명사형) → 우연히 닥쳐오는 일, 행사·경우"},{"id":"d7-52","day":7,"word":"feature","meaning":"~을 특징으로 하다","ipa":"[ˈfiːtʃər]","kr":"피처","example":"The car features an advanced safety system.","exampleKr":"그 차는 첨단 안전 시스템을 특징으로 한다.","roots":"feat(만들다, 고대 프랑스어 faiture, 라틴어 facere) + -ure(명사형) → 만들어진 모습, 특징(으로 하다)"},{"id":"d7-53","day":7,"word":"scenic","meaning":"경치의, 경치가 좋은","ipa":"[ˈsiːnɪk]","kr":"시닉","example":"They took the scenic route along the coast.","exampleKr":"그들은 해안을 따라 경치가 좋은 길로 갔다.","roots":"scen(무대, 그리스어 skene) + -ic(형용사형) → 무대처럼 아름다운, 경치의"},{"id":"d7-54","day":7,"word":"grooming","meaning":"몸단장, 미용, 그루밍","ipa":"[ˈɡruːmɪŋ]","kr":"그루밍","example":"He spends a lot of time on grooming.","exampleKr":"그는 몸단장에 많은 시간을 쓴다."},{"id":"d7-55","day":7,"word":"panel","meaning":"패널, 전문가집단","ipa":"[ˈpænl]","kr":"패늘","example":"A panel of experts discussed the issue.","exampleKr":"전문가 패널이 그 문제를 논의했다."},{"id":"d7-56","day":7,"word":"vaccinate","meaning":"예방접종 하다","ipa":"[ˈvæksɪneɪt]","kr":"백시네이트","example":"Parents were urged to vaccinate their children.","exampleKr":"부모들은 아이들에게 예방접종을 하도록 권장받았다.","roots":"vacc(암소, 라틴어 vacca) + -ine + -ate(동사형) → 소(우두)에서 얻어낸 것을 접종하다, 예방접종하다"},{"id":"d7-57","day":7,"word":"in advance","meaning":"미리, 사전에","ipa":"[ɪn ədˈvæns]","kr":"인 어드밴스","example":"Please pay in advance.","exampleKr":"미리 결제해 주세요.","roots":"ab-(~로부터) + ante(앞, 라틴어) → 앞으로 나아가, 미리"},{"id":"d7-58","day":7,"word":"prior to","meaning":"~에 앞서","ipa":"[ˈpraɪər tuː]","kr":"프라이어 투","example":"Arrive prior to the scheduled time.","exampleKr":"예정된 시간에 앞서 도착해라."},{"id":"d7-59","day":7,"word":"beforehand","meaning":"미리","ipa":"[bɪˈfɔːrhænd]","kr":"비포핸드","example":"She called beforehand to confirm the reservation.","exampleKr":"그녀는 예약을 확인하기 위해 미리 전화했다."},{"id":"d7-60","day":7,"word":"mental imagery","meaning":"심상","ipa":"[ˈmentl ˈɪmɪdʒri]","kr":"멘틀 이미저리","example":"Athletes often use mental imagery to prepare.","exampleKr":"운동선수들은 준비를 위해 종종 심상을 사용한다."},{"id":"d7-61","day":7,"word":"mental representation","meaning":"심적 표상","ipa":"[ˈmentl ˌreprɪzenˈteɪʃn]","kr":"멘틀 레프리젠테이션","example":"The brain creates a mental representation of the world.","exampleKr":"뇌는 세상에 대한 심적 표상을 만든다."},{"id":"d7-62","day":7,"word":"differentiate","meaning":"구분 짓다","ipa":"[ˌdɪfəˈrenʃieɪt]","kr":"디퍼렌시에이트","example":"Students learned to differentiate the two species.","exampleKr":"학생들은 두 종을 구분하는 법을 배웠다.","roots":"dif-(따로) + fer(나르다, 라틴어 ferre) + -ent + -iate(동사형) → 따로따로 갈라놓다, 구분 짓다"},{"id":"d7-63","day":7,"word":"distinguish","meaning":"구분짓다, 차별화하다","ipa":"[dɪˈstɪŋɡwɪʃ]","kr":"디스팅귀시","example":"It's hard to distinguish the copies from the originals.","exampleKr":"복사본과 원본을 구분하기는 어렵다.","roots":"di-(따로) + sting(u)(찌르다·표시하다, 라틴어 stinguere) → 찔러 표시해 따로 구별하다"},{"id":"d7-64","day":7,"word":"single out","meaning":"구분짓다, 차별화하다","ipa":"[ˈsɪŋɡl aʊt]","kr":"싱글 아웃","example":"The teacher singled out one student for praise.","exampleKr":"선생님은 칭찬을 위해 한 학생을 골라냈다."},{"id":"d7-65","day":7,"word":"set apart","meaning":"구분짓다, 차별화하다","ipa":"[set əˈpɑːrt]","kr":"셋 어파트","example":"Her passion sets her apart from other candidates.","exampleKr":"그녀의 열정은 그녀를 다른 후보들과 차별화한다.","roots":"a-(~로) + part(부분, 라틴어 pars) → 부분부분 떼어놓다, 구분 짓다"},{"id":"d7-66","day":7,"word":"lesser","meaning":"(실력이)더 못한","ipa":"[ˈlesər]","kr":"레서","example":"He was seen as the lesser of the two evils.","exampleKr":"그는 둘 중 더 못한 쪽으로 여겨졌다."},{"id":"d7-67","day":7,"word":"advanced","meaning":"상급의","ipa":"[ədˈvænst]","kr":"어드밴스트","example":"She joined the advanced yoga class.","exampleKr":"그녀는 상급 요가 수업에 등록했다.","roots":"ab-(~로부터) + ante(앞, 라틴어) + -ed → 앞으로 나아간, 상급의"},{"id":"d7-68","day":7,"word":"beginner","meaning":"초급자","ipa":"[bɪˈɡɪnər]","kr":"비기너","example":"This course is designed for beginners.","exampleKr":"이 강좌는 초급자를 위해 설계되었다."},{"id":"d7-69","day":7,"word":"novice","meaning":"초급자","ipa":"[ˈnɑːvɪs]","kr":"나비스","example":"He is still a novice at chess.","exampleKr":"그는 아직 체스 초급자다.","roots":"nov(새로운, 라틴어 novus) + -ice(명사형) → 새로 들어온 사람, 초보자"},{"id":"d7-70","day":7,"word":"intermediate","meaning":"중급의","ipa":"[ˌɪntərˈmiːdiət]","kr":"인터미디엇","example":"She moved up to the intermediate level.","exampleKr":"그녀는 중급 수준으로 올라갔다.","roots":"inter-(사이에) + medi(중간, 라틴어 medius) + -ate(형용사형) → 사이 중간에 있는, 중급의"},{"id":"d7-71","day":7,"word":"crude","meaning":"투박한","ipa":"[kruːd]","kr":"크루드","example":"The tool was crude but effective.","exampleKr":"그 도구는 투박했지만 효과적이었다."},{"id":"d7-72","day":7,"word":"coarse","meaning":"투박한","ipa":"[kɔːrs]","kr":"코어스","example":"The fabric felt coarse against her skin.","exampleKr":"그 천은 피부에 닿았을 때 투박하게 느껴졌다."},{"id":"d7-73","day":7,"word":"clumsy","meaning":"투박한","ipa":"[ˈklʌmzi]","kr":"클럼지","example":"He made a clumsy attempt to fix the sink.","exampleKr":"그는 싱크대를 고치려는 서투른 시도를 했다."},{"id":"d7-74","day":7,"word":"unsophisticated","meaning":"투박한","ipa":"[ˌʌnsəˈfɪstɪkeɪtɪd]","kr":"언서피스티케이티드","example":"The early design was simple and unsophisticated.","exampleKr":"초기 디자인은 단순하고 투박했다.","roots":"un-(부정) + sophist(궤변가·기교, 그리스어 sophistes) + -ic + -ate + -ed → 정교한 기교를 부리지 않은, 투박한"},{"id":"d7-75","day":7,"word":"identify","meaning":"알아내다","ipa":"[aɪˈdentɪfaɪ]","kr":"아이덴티파이","example":"She identified the bird by its call.","exampleKr":"그녀는 울음소리로 그 새를 알아냈다.","roots":"ident(같은, 라틴어 idem) + -i- + -fy(만들다, 라틴어 facere) → 같게 만들다, 알아내다"},{"id":"d7-76","day":7,"word":"subtle","meaning":"미묘한","ipa":"[ˈsʌtl]","kr":"서틀","example":"There was a subtle change in his tone.","exampleKr":"그의 말투에는 미묘한 변화가 있었다.","roots":"sub-(아래·촘촘히) + til(e)(짜다, 라틴어 tela 실·천) → 촘촘히 짜인 것처럼 정교한, 미묘한"},{"id":"d7-77","day":7,"word":"delicate","meaning":"미묘한","ipa":"[ˈdelɪkət]","kr":"델리컷","example":"Handle the antique vase with delicate care.","exampleKr":"그 골동품 화병은 섬세하게 다뤄라.","roots":"de-(강조) + lic(유혹하다, 라틴어 lacere) + -ate(형용사형) → 유혹적일 만큼 곱고 세밀한, 미묘한"},{"id":"d7-78","day":7,"word":"costly","meaning":"비용이 많이 드는","ipa":"[ˈkɔːstli]","kr":"코스틀리","example":"Repairing the roof was costly.","exampleKr":"지붕을 수리하는 것은 비용이 많이 들었다.","roots":"cost(비용, 고대 프랑스어 coust, 라틴어 constare) + -ly(형용사형) → 값이 매겨진, 비용이 많이 드는"},{"id":"d7-79","day":7,"word":"forage","meaning":"먹이를 찾아다니다","ipa":"[ˈfɔːrɪdʒ]","kr":"포리지","example":"Squirrels forage for nuts in autumn.","exampleKr":"다람쥐는 가을에 견과류를 찾아다닌다."},{"id":"d7-80","day":7,"word":"at risk","meaning":"위험에 처한","ipa":"[æt rɪsk]","kr":"앳 리스크","example":"Their savings were at risk during the crisis.","exampleKr":"위기 동안 그들의 저축이 위험에 처했다."},{"id":"d7-81","day":7,"word":"against","meaning":"~와 반대로","ipa":"[əˈɡenst]","kr":"어겐스트","example":"His decision went against the advice of experts.","exampleKr":"그의 결정은 전문가들의 조언과 반대였다."},{"id":"d7-82","day":7,"word":"motor","meaning":"운동의","ipa":"[ˈmoʊtər]","kr":"모우터","example":"The therapy improves the child's motor skills.","exampleKr":"그 치료는 아이의 운동 능력을 향상시킨다.","roots":"mot(움직이다, 라틴어 movere) + -or(명사·형용사형) → 움직이게 하는, 운동의"},{"id":"d7-83","day":7,"word":"track","meaning":"추적하다","ipa":"[træk]","kr":"트랙","example":"Scientists track the animal's movements by satellite.","exampleKr":"과학자들은 위성으로 그 동물의 움직임을 추적한다."},{"id":"d7-84","day":7,"word":"juvenile","meaning":"성장기의","ipa":"[ˈdʒuːvənl]","kr":"주버늘","example":"The park has a juvenile deer population.","exampleKr":"그 공원에는 성장기 사슴 개체군이 있다.","roots":"juven(젊은, 라틴어 juvenis) + -ile(형용사형) → 젊은, 성장기의"},{"id":"d7-85","day":7,"word":"persistence","meaning":"지속, 끈기","ipa":"[pərˈsɪstəns]","kr":"퍼시스턴스","example":"Her persistence finally paid off.","exampleKr":"그녀의 끈기는 마침내 결실을 맺었다.","roots":"per-(끝까지) + sist(서다, 라틴어 sistere) + -ence(명사형) → 끝까지 버티고 서 있음, 지속·끈기"},{"id":"d7-86","day":7,"word":"consistency","meaning":"지속, 끈기","ipa":"[kənˈsɪstənsi]","kr":"컨시스턴시","example":"Consistency is key to building good habits.","exampleKr":"지속성은 좋은 습관을 만드는 데 핵심이다.","roots":"con-(함께) + sist(서다, 라틴어 sistere) + -ency(명사형) → 함께 서서 한결같음, 지속성·일관성"},{"id":"d7-87","day":7,"word":"endurance","meaning":"지속, 끈기","ipa":"[ɪnˈdʊrəns]","kr":"인듀런스","example":"Marathon runners need great endurance.","exampleKr":"마라톤 선수들은 뛰어난 지속력이 필요하다.","roots":"en-(만들다) + dur(단단한·견디다, 라틴어 durus, durare) + -ance(명사형) → 단단하게 견뎌내는 것, 지속·인내"},{"id":"d7-88","day":7,"word":"run an article","meaning":"기사를 싣다","ipa":"[rʌn ən ˈɑːrtɪkl]","kr":"런 언 아티클","example":"The newspaper ran an article about the scandal.","exampleKr":"신문은 그 스캔들에 대한 기사를 실었다."},{"id":"d7-89","day":7,"word":"title","meaning":"제목을 붙이다","ipa":"[ˈtaɪtl]","kr":"타이틀","example":"The book is titled \"The Long Road.\"","exampleKr":"그 책은 \"긴 길\"이라는 제목이 붙었다."},{"id":"d7-90","day":7,"word":"torture","meaning":"고문","ipa":"[ˈtɔːrtʃər]","kr":"토처","example":"The prisoner endured months of torture.","exampleKr":"그 죄수는 몇 달간의 고문을 견뎠다.","roots":"tor(t)(비틀다, 라틴어 torquere) + -ure(명사형) → 몸을 비틀어 괴롭히는 것, 고문"},{"id":"d7-91","day":7,"word":"cut in front of","meaning":"~앞에 끼어들다","ipa":"[kʌt ɪn frʌnt əv]","kr":"컷 인 프런트 오브","example":"He cut in front of the line.","exampleKr":"그는 줄 앞에 끼어들었다."},{"id":"d7-92","day":7,"word":"be willing to","meaning":"기꺼이 ~하다","ipa":"[bi ˈwɪlɪŋ tuː]","kr":"비 윌링 투","example":"She is willing to help anytime.","exampleKr":"그녀는 언제든 기꺼이 도울 의향이 있다."},{"id":"d7-93","day":7,"word":"be reluctant to","meaning":"꺼려 하다","ipa":"[bi rɪˈlʌktənt tuː]","kr":"비 릴럭턴트 투","example":"He was reluctant to share his opinion.","exampleKr":"그는 자신의 의견을 공유하기를 꺼렸다.","roots":"re-(반대로) + luct(싸우다, 라틴어 luctari) + -ant(형용사형) → 맞서 싸우려는, 꺼려하는"},{"id":"d7-94","day":7,"word":"serve","meaning":"응대하다","ipa":"[sɜːrv]","kr":"서브","example":"The waiter served the meal quickly.","exampleKr":"그 웨이터는 음식을 빠르게 응대했다."},{"id":"d7-95","day":7,"word":"preference","meaning":"선호도","ipa":"[ˈprefrəns]","kr":"프레퍼런스","example":"Customers can indicate their seating preference.","exampleKr":"고객들은 좌석 선호도를 표시할 수 있다.","roots":"pre-(먼저) + fer(나르다·옮기다, 라틴어 ferre) + -ence(명사형) → 먼저 갖다 놓는 것, 선호"},{"id":"d7-96","day":7,"word":"note","meaning":"언급하다","ipa":"[noʊt]","kr":"노우트","example":"Please note the change in schedule.","exampleKr":"일정 변경을 참고해 주세요."},{"id":"d7-97","day":7,"word":"cite","meaning":"언급하다","ipa":"[saɪt]","kr":"사이트","example":"The report cited several studies.","exampleKr":"그 보고서는 여러 연구를 언급했다."},{"id":"d7-98","day":7,"word":"state","meaning":"언급하다","ipa":"[steɪt]","kr":"스테이트","example":"He clearly stated his intentions.","exampleKr":"그는 자신의 의도를 명확하게 언급했다."},{"id":"d7-99","day":7,"word":"first-come, first-served","meaning":"선착순의","ipa":"[ˈfɜːrst kʌm ˈfɜːrst sɜːrvd]","kr":"퍼스트 컴 퍼스트 서브드","example":"Seats are available on a first-come, first-served basis.","exampleKr":"좌석은 선착순으로 제공된다."},{"id":"d7-100","day":7,"word":"multiple","meaning":"다수의","ipa":"[ˈmʌltɪpl]","kr":"멀티플","example":"The store has multiple locations.","exampleKr":"그 가게는 여러 지점을 가지고 있다.","roots":"multi-(많은, 라틴어 multus) + -ple(접다, 라틴어 plicare) → 여러 겹으로 접힌, 다수의"},{"id":"d8-1","day":8,"word":"queue","meaning":"줄","ipa":"[kjuː]","kr":"큐","example":"People waited in a long queue outside the shop.","exampleKr":"사람들은 가게 밖에서 긴 줄을 서서 기다렸다."},{"id":"d8-2","day":8,"word":"row","meaning":"줄","ipa":"[roʊ]","kr":"로우","example":"They sat in the front row of the theater.","exampleKr":"그들은 극장의 앞줄에 앉았다."},{"id":"d8-3","day":8,"word":"separate","meaning":"여러 개의, 분리된","ipa":"[ˈsepərət]","kr":"세퍼럿","example":"The kids were kept in separate rooms.","exampleKr":"아이들은 각각 분리된 방에 있었다.","roots":"se-(따로) + par(준비하다, 라틴어 parare) + -ate → 따로 떼어 준비해 놓은"},{"id":"d8-4","day":8,"word":"overwhelmingly","meaning":"압도적으로","ipa":"[ˌoʊvərˈwelmɪŋli]","kr":"오버웰밍리","example":"Voters overwhelmingly supported the new law.","exampleKr":"유권자들은 압도적으로 새 법을 지지했다."},{"id":"d8-5","day":8,"word":"justice","meaning":"정의감","ipa":"[ˈdʒʌstɪs]","kr":"저스티스","example":"She has a strong sense of justice.","exampleKr":"그녀는 강한 정의감을 가지고 있다.","roots":"just(정의로운, 라틴어 justus) + -ice(명사형) → 정의로운 상태"},{"id":"d8-6","day":8,"word":"evolutionary","meaning":"진화의","ipa":"[ˌiːvəˈluːʃəneri]","kr":"이벌루셔네리","example":"The book explains evolutionary biology.","exampleKr":"그 책은 진화 생물학을 설명한다.","roots":"e-(밖으로) + volu(구르다, 라틴어 volvere) + -tion + -ary → 밖으로 굴러 나오는, 진화의"},{"id":"d8-7","day":8,"word":"biologist","meaning":"생물학자","ipa":"[baɪˈɑːlədʒɪst]","kr":"바이알러지스트","example":"The biologist studied coral reefs.","exampleKr":"그 생물학자는 산호초를 연구했다.","roots":"bio(생명, 그리스어 bios) + log(학문, 그리스어 logos) + -ist → 생명을 연구하는 사람"},{"id":"d8-8","day":8,"word":"extraordinary","meaning":"탁월한, 특별한","ipa":"[ɪkˈstrɔːrdəneri]","kr":"익스트로디너리","example":"He showed extraordinary talent at a young age.","exampleKr":"그는 어린 나이에 탁월한 재능을 보였다.","roots":"extra-(밖의) + ordin(순서, 라틴어 ordo) + -ary → 질서 밖의, 비범한"},{"id":"d8-9","day":8,"word":"remarkable","meaning":"탁월한, 특별한","ipa":"[rɪˈmɑːrkəbl]","kr":"리마커블","example":"She achieved remarkable success in a short time.","exampleKr":"그녀는 짧은 시간에 탁월한 성공을 거뒀다."},{"id":"d8-10","day":8,"word":"outstanding","meaning":"탁월한, 특별한","ipa":"[aʊtˈstændɪŋ]","kr":"아웃스탠딩","example":"He received an outstanding review from his boss.","exampleKr":"그는 상사로부터 탁월한 평가를 받았다."},{"id":"d8-11","day":8,"word":"astonishing","meaning":"탁월한, 특별한","ipa":"[əˈstɑːnɪʃɪŋ]","kr":"어스타니싱","example":"The results were astonishing to the researchers.","exampleKr":"그 결과는 연구자들에게 놀라웠다.","roots":"a-(강조, 고대 프랑스어 estoner) + ton(천둥치다, 라틴어 tonare) + -ish → 천둥소리에 놀란 듯한"},{"id":"d8-12","day":8,"word":"exceptional","meaning":"탁월한, 특별한","ipa":"[ɪkˈsepʃənl]","kr":"익셉셔늘","example":"She showed exceptional skill in the competition.","exampleKr":"그녀는 대회에서 탁월한 기술을 보였다.","roots":"ex-(밖으로) + cept(잡다, 라틴어 capere) + -ion + -al → 밖으로 따로 잡아낸, 예외적인"},{"id":"d8-13","day":8,"word":"conscious","meaning":"의식적인","ipa":"[ˈkɑːnʃəs]","kr":"칸셔스","example":"He made a conscious effort to eat healthier.","exampleKr":"그는 더 건강하게 먹으려는 의식적인 노력을 했다.","roots":"con-(함께) + sci(알다, 라틴어 scire) + -ous → 함께 알고 있는, 의식하는"},{"id":"d8-14","day":8,"word":"fitness","meaning":"적합성","ipa":"[ˈfɪtnəs]","kr":"핏니스","example":"Her fitness for the job impressed the panel.","exampleKr":"그 일에 대한 그녀의 적합성은 패널에게 깊은 인상을 줬다."},{"id":"d8-15","day":8,"word":"shake off","meaning":"떨쳐내다","ipa":"[ʃeɪk ɔːf]","kr":"셰이크 오프","example":"He couldn't shake off his cold.","exampleKr":"그는 감기를 떨쳐낼 수 없었다."},{"id":"d8-16","day":8,"word":"pursuer","meaning":"추격자","ipa":"[pərˈsuːər]","kr":"퍼수어","example":"The pursuer gave up after a long chase.","exampleKr":"그 추격자는 긴 추격 끝에 포기했다.","roots":"pur-(앞으로, 라틴어 pro) + su(e)(따르다, 라틴어 sequi) + -er → 뒤쫓아가는 사람"},{"id":"d8-17","day":8,"word":"reliable","meaning":"믿을 만한","ipa":"[rɪˈlaɪəbl]","kr":"릴라이어블","example":"She is a reliable source of information.","exampleKr":"그녀는 믿을 만한 정보원이다.","roots":"re-(다시) + li(묶다, 라틴어 ligare) + -able → 다시 묶어 의지할 수 있는"},{"id":"d8-18","day":8,"word":"dependable","meaning":"믿을 만한","ipa":"[dɪˈpendəbl]","kr":"디펜더블","example":"He is a dependable friend.","exampleKr":"그는 믿을 만한 친구다.","roots":"de-(아래로) + pend(매달리다, 라틴어 pendere) + -able → 아래로 매달려 의지할 수 있는"},{"id":"d8-19","day":8,"word":"credible","meaning":"믿을 만한","ipa":"[ˈkredəbl]","kr":"크레더블","example":"The witness gave a credible account of events.","exampleKr":"그 목격자는 믿을 만한 사건 설명을 했다.","roots":"cred(믿다, 라틴어 credere) + -ible → 믿을 수 있는"},{"id":"d8-20","day":8,"word":"convincing","meaning":"믿을 만한","ipa":"[kənˈvɪnsɪŋ]","kr":"컨빈싱","example":"His argument was very convincing.","exampleKr":"그의 주장은 매우 설득력 있었다.","roots":"con-(완전히) + vinc(정복하다, 라틴어 vincere) + -ing → 완전히 이겨 설득하는"},{"id":"d8-21","day":8,"word":"trustworthy","meaning":"믿을 만한","ipa":"[ˈtrʌstwɜːrði]","kr":"트러스트워디","example":"She is known as a trustworthy leader.","exampleKr":"그녀는 믿을 만한 리더로 알려져 있다."},{"id":"d8-22","day":8,"word":"genuinely","meaning":"정말로, 진정으로","ipa":"[ˈdʒenjuɪnli]","kr":"제뉴인리","example":"He was genuinely happy for her success.","exampleKr":"그는 그녀의 성공에 대해 정말로 기뻐했다."},{"id":"d8-23","day":8,"word":"sincerely","meaning":"정말로, 진정으로","ipa":"[sɪnˈsɪrli]","kr":"신시얼리","example":"I sincerely apologize for the mistake.","exampleKr":"나는 그 실수에 대해 진심으로 사과한다."},{"id":"d8-24","day":8,"word":"hare","meaning":"산토끼","ipa":"[her]","kr":"헤어","example":"The hare ran quickly across the field.","exampleKr":"산토끼는 들판을 빠르게 가로질러 뛰었다."},{"id":"d8-25","day":8,"word":"foreknowledge","meaning":"미리 아는 것, 선견지명","ipa":"[ˌfɔːrˈnɑːlɪdʒ]","kr":"포날리지","example":"He had no foreknowledge of the plan.","exampleKr":"그는 그 계획에 대한 사전 지식이 없었다."},{"id":"d8-26","day":8,"word":"posture","meaning":"자세","ipa":"[ˈpɑːstʃər]","kr":"파스처","example":"Good posture helps prevent back pain.","exampleKr":"좋은 자세는 요통을 예방하는 데 도움이 된다.","roots":"pos(놓다, 라틴어 ponere) + -ture(명사형) → 몸을 놓아둔 상태, 자세"},{"id":"d8-27","day":8,"word":"reveal","meaning":"드러내다","ipa":"[rɪˈviːl]","kr":"리빌","example":"The photo revealed a hidden detail.","exampleKr":"그 사진은 숨겨진 세부 사항을 드러냈다.","roots":"re-(뒤로) + veal(베일, 라틴어 velum) → 베일을 벗겨 뒤로 젖히다, 드러내다"},{"id":"d8-28","day":8,"word":"clue","meaning":"단서","ipa":"[kluː]","kr":"클루","example":"The stain gave a clue about what happened.","exampleKr":"그 얼룩은 무슨 일이 있었는지 단서를 주었다."},{"id":"d8-29","day":8,"word":"anticipate","meaning":"예상하다","ipa":"[ænˈtɪsɪpeɪt]","kr":"앤티시페이트","example":"She anticipated his questions and prepared answers.","exampleKr":"그녀는 그의 질문을 예상하고 답을 준비했다.","roots":"anti-(미리, 라틴어 ante) + cip(잡다, 라틴어 capere) + -ate → 미리 잡다, 예상하다"},{"id":"d8-30","day":8,"word":"fatal","meaning":"치명적인","ipa":"[ˈfeɪtl]","kr":"페이틀","example":"The accident turned out to be fatal.","exampleKr":"그 사고는 치명적인 것으로 밝혀졌다.","roots":"fat(운명, 라틴어 fatum) + -al → 운명에 관한, 치명적인"},{"id":"d8-31","day":8,"word":"deadly","meaning":"치명적인","ipa":"[ˈdedli]","kr":"데들리","example":"The virus can be deadly for the elderly.","exampleKr":"그 바이러스는 노인들에게 치명적일 수 있다."},{"id":"d8-32","day":8,"word":"lethal","meaning":"치명적인","ipa":"[ˈliːθl]","kr":"리썰","example":"The snake's venom is lethal.","exampleKr":"그 뱀의 독은 치명적이다.","roots":"leth(죽음, 라틴어 letum) + -al → 죽음에 이르는"},{"id":"d8-33","day":8,"word":"consequence","meaning":"결과","ipa":"[ˈkɑːnsəkwens]","kr":"칸시퀀스","example":"Every action has a consequence.","exampleKr":"모든 행동에는 결과가 있다.","roots":"con-(함께) + sequ(따르다, 라틴어 sequi) + -ence → 함께 뒤따라 나오는 것"},{"id":"d8-34","day":8,"word":"outcome","meaning":"결과","ipa":"[ˈaʊtkʌm]","kr":"아웃컴","example":"The outcome of the trial surprised everyone.","exampleKr":"재판의 결과는 모두를 놀라게 했다."},{"id":"d8-35","day":8,"word":"effect","meaning":"결과","ipa":"[ɪˈfekt]","kr":"이펙트","example":"The medicine had an immediate effect.","exampleKr":"그 약은 즉각적인 효과가 있었다.","roots":"ef-(밖으로, ex의 변형) + fect(만들다, 라틴어 facere) → 밖으로 만들어낸 것, 결과"},{"id":"d8-36","day":8,"word":"self-awareness","meaning":"자기 인식","ipa":"[self əˈwernəs]","kr":"셀프 어웨어니스","example":"Meditation can improve self-awareness.","exampleKr":"명상은 자기 인식을 향상시킬 수 있다."},{"id":"d8-37","day":8,"word":"die out","meaning":"멸종되다","ipa":"[daɪ aʊt]","kr":"다이 아웃","example":"The tradition slowly died out.","exampleKr":"그 전통은 서서히 사라졌다."},{"id":"d8-38","day":8,"word":"perish","meaning":"사라지다","ipa":"[ˈperɪʃ]","kr":"페리시","example":"Many crops perished during the drought.","exampleKr":"많은 작물이 가뭄 동안 사라졌다.","roots":"per-(완전히) + ish(가다, 라틴어 ire) → 완전히 가버리다, 사라지다"},{"id":"d8-39","day":8,"word":"vanish","meaning":"사라지다","ipa":"[ˈvænɪʃ]","kr":"배니시","example":"The magician made the coin vanish.","exampleKr":"그 마술사는 동전을 사라지게 했다.","roots":"van(빈, 라틴어 vanus) + -ish → 텅 비어 사라지다"},{"id":"d8-40","day":8,"word":"fade","meaning":"사라지다","ipa":"[feɪd]","kr":"페이드","example":"The colors faded in the sunlight.","exampleKr":"그 색깔은 햇빛에 바랬다."},{"id":"d8-41","day":8,"word":"descended","meaning":"전래한, 유래한, 후손인","ipa":"[dɪˈsendɪd]","kr":"디센디드","example":"The custom is descended from ancient rituals.","exampleKr":"그 관습은 고대 의식에서 전래되었다.","roots":"de-(아래로) + scend(오르다, 라틴어 scandere) → 아래로 내려오다"},{"id":"d8-42","day":8,"word":"descendant","meaning":"후손","ipa":"[dɪˈsendənt]","kr":"디센던트","example":"He is a descendant of the royal family.","exampleKr":"그는 왕족의 후손이다.","roots":"de-(아래로) + scend(오르다, 라틴어 scandere) + -ant → 아래로 내려온 사람, 후손"},{"id":"d8-43","day":8,"word":"offspring","meaning":"후손, 새끼","ipa":"[ˈɔːfsprɪŋ]","kr":"오프스프링","example":"The offspring resembled its parents closely.","exampleKr":"그 새끼는 부모를 매우 닮았다."},{"id":"d8-44","day":8,"word":"ancestor","meaning":"조상","ipa":"[ˈænsestər]","kr":"앤세스터","example":"Her ancestors came from Ireland.","exampleKr":"그녀의 조상은 아일랜드에서 왔다.","roots":"an-(앞서, 라틴어 ante) + cess(가다, 라틴어 cedere) + -or → 앞서 간 사람, 조상"},{"id":"d8-45","day":8,"word":"forefather","meaning":"조상","ipa":"[ˈfɔːrfɑːðər]","kr":"포파더","example":"Our forefathers built this town.","exampleKr":"우리 조상들이 이 마을을 세웠다."},{"id":"d8-46","day":8,"word":"forebear","meaning":"조상","ipa":"[ˈfɔːrber]","kr":"포베어","example":"Their forebears settled here centuries ago.","exampleKr":"그들의 조상은 수 세기 전에 이곳에 정착했다."},{"id":"d8-47","day":8,"word":"ascendant","meaning":"조상","ipa":"[əˈsendənt]","kr":"어센던트","example":"Her ascendant was a famous explorer.","exampleKr":"그녀의 조상은 유명한 탐험가였다.","roots":"a-(~쪽으로, 라틴어 ad) + scend(오르다, 라틴어 scandere) + -ant → 위로 올라가는"},{"id":"d8-48","day":8,"word":"concealment","meaning":"숨김, 은폐","ipa":"[kənˈsiːlmənt]","kr":"컨실먼트","example":"The animal used camouflage for concealment.","exampleKr":"그 동물은 은폐를 위해 위장을 사용했다.","roots":"con-(강조) + ceal(숨기다, 라틴어 celare) + -ment → 완전히 숨김"},{"id":"d8-49","day":8,"word":"motive","meaning":"동기","ipa":"[ˈmoʊtɪv]","kr":"모우티브","example":"The police searched for a motive.","exampleKr":"경찰은 동기를 찾았다.","roots":"mot(움직이다, 라틴어 movere) + -ive → 움직이게 하는 것, 동기"},{"id":"d8-50","day":8,"word":"conceal","meaning":"숨기다","ipa":"[kənˈsiːl]","kr":"컨실","example":"He tried to conceal his nervousness.","exampleKr":"그는 자신의 긴장을 숨기려 했다.","roots":"con-(강조) + ceal(숨기다, 라틴어 celare) → 완전히 숨기다"},{"id":"d8-51","day":8,"word":"convincing","meaning":"설득력 있는","ipa":"[kənˈvɪnsɪŋ]","kr":"컨빈싱","example":"The evidence was convincing enough for the jury.","exampleKr":"그 증거는 배심원단에게 충분히 설득력 있었다.","roots":"con-(완전히) + vinc(정복하다, 라틴어 vincere) + -ing → 완전히 이겨 설득하는"},{"id":"d8-52","day":8,"word":"persuasive","meaning":"설득력 있는","ipa":"[pərˈsweɪsɪv]","kr":"퍼스웨이시브","example":"She gave a persuasive speech about recycling.","exampleKr":"그녀는 재활용에 대해 설득력 있는 연설을 했다.","roots":"per-(완전히) + suas(권하다, 라틴어 suadere) + -ive → 완전히 설득하는"},{"id":"d8-53","day":8,"word":"compelling","meaning":"설득력 있는","ipa":"[kəmˈpelɪŋ]","kr":"컴펠링","example":"The documentary presents a compelling argument.","exampleKr":"그 다큐멘터리는 설득력 있는 주장을 제시한다.","roots":"com-(강조) + pel(밀다, 라틴어 pellere) + -ing → 강하게 밀어붙이는"},{"id":"d8-54","day":8,"word":"convictive","meaning":"설득력 있는","ipa":"[kənˈvɪktɪv]","kr":"컨빅티브","example":"His convictive tone made people believe him.","exampleKr":"그의 설득력 있는 어조는 사람들이 그를 믿게 만들었다.","roots":"con-(완전히) + vict(정복하다, 라틴어 vincere) + -ive → 완전히 이겨 확신시키는"},{"id":"d8-55","day":8,"word":"classical","meaning":"고전적인","ipa":"[ˈklæsɪkl]","kr":"클래시클","example":"She studies classical music at the conservatory.","exampleKr":"그녀는 음악원에서 고전 음악을 공부한다.","roots":"class(계급, 라틴어 classis) + -ical → 최고 계급의, 고전의"},{"id":"d8-56","day":8,"word":"region","meaning":"부위, 영역","ipa":"[ˈriːdʒən]","kr":"리전","example":"The disease spread across the region.","exampleKr":"그 질병은 그 지역 전역으로 퍼졌다.","roots":"reg(다스리다, 라틴어 regere) + -ion → 다스려지는 구역, 지역"},{"id":"d8-57","day":8,"word":"activate","meaning":"활성화하다","ipa":"[ˈæktɪveɪt]","kr":"액티베이트","example":"Pressing the button activates the alarm.","exampleKr":"버튼을 누르면 경보가 활성화된다.","roots":"act(행하다, 라틴어 agere) + -ive + -ate → 행하게 만들다, 활성화하다"},{"id":"d8-58","day":8,"word":"language-processing","meaning":"언어처리","ipa":"[ˈlæŋɡwɪdʒ ˈprɑːsesɪŋ]","kr":"랭귀지 프라세싱","example":"The brain's language-processing area was damaged.","exampleKr":"뇌의 언어 처리 영역이 손상되었다."},{"id":"d8-59","day":8,"word":"respond","meaning":"반응하다","ipa":"[rɪˈspɑːnd]","kr":"리스판드","example":"She responded quickly to the email.","exampleKr":"그녀는 이메일에 빠르게 반응했다.","roots":"re-(다시) + spond(약속하다, 라틴어 spondere) → 다시 약속하며 답하다"},{"id":"d8-60","day":8,"word":"react","meaning":"반응하다","ipa":"[riˈækt]","kr":"리액트","example":"He reacted calmly to the criticism.","exampleKr":"그는 비판에 침착하게 반응했다.","roots":"re-(다시) + act(행하다, 라틴어 agere) → 다시 행하다, 반응하다"},{"id":"d8-61","day":8,"word":"as though","meaning":"마치 ~처럼","ipa":"[æz ðoʊ]","kr":"애즈 도우","example":"She acted as though nothing happened.","exampleKr":"그녀는 아무 일도 없었던 것처럼 행동했다."},{"id":"d8-62","day":8,"word":"metaphor","meaning":"은유, 비유","ipa":"[ˈmetəfər]","kr":"메터퍼","example":"The poem uses the ocean as a metaphor for life.","exampleKr":"그 시는 바다를 인생에 대한 은유로 사용한다.","roots":"meta-(넘어) + phor(옮기다, 그리스어 pherein) → 의미를 넘어 옮기는 것, 은유"},{"id":"d8-63","day":8,"word":"analogy","meaning":"비유","ipa":"[əˈnælədʒi]","kr":"어낼러지","example":"He drew an analogy between farming and business.","exampleKr":"그는 농사와 사업 사이의 비유를 그렸다.","roots":"ana-(~에 따라) + log(비율, 그리스어 logos) + -y → 비율에 맞게 견주는 것"},{"id":"d8-64","day":8,"word":"cliched","meaning":"상투적인, 진부한","ipa":"[kliːˈʃeɪd]","kr":"클리셰이드","example":"The plot felt cliched and predictable.","exampleKr":"그 줄거리는 상투적이고 예측 가능하게 느껴졌다."},{"id":"d8-65","day":8,"word":"sensory","meaning":"감각의","ipa":"[ˈsensəri]","kr":"센서리","example":"The toy provides sensory stimulation for babies.","exampleKr":"그 장난감은 아기에게 감각적 자극을 제공한다.","roots":"sens(느끼다, 라틴어 sentire) + -ory → 느끼는 것과 관련된"},{"id":"d8-66","day":8,"word":"sensitive","meaning":"민감한","ipa":"[ˈsensətɪv]","kr":"센서티브","example":"This topic is sensitive for many people.","exampleKr":"이 주제는 많은 사람들에게 민감하다.","roots":"sens(느끼다, 라틴어 sentire) + -itive → 쉽게 느끼는"},{"id":"d8-67","day":8,"word":"sensible","meaning":"현명한","ipa":"[ˈsensəbl]","kr":"센서블","example":"He made a sensible choice under pressure.","exampleKr":"그는 압박 속에서 현명한 선택을 했다.","roots":"sens(느끼다, 라틴어 sentire) + -ible → 느끼고 분별할 수 있는"},{"id":"d8-68","day":8,"word":"cortex","meaning":"대뇌 피질","ipa":"[ˈkɔːrteks]","kr":"코텍스","example":"The visual cortex processes images.","exampleKr":"시각 피질은 이미지를 처리한다."},{"id":"d8-69","day":8,"word":"coordinate","meaning":"조정하다","ipa":"[koʊˈɔːrdɪneɪt]","kr":"코오디네이트","example":"She coordinated the entire event.","exampleKr":"그녀는 그 행사 전체를 조정했다.","roots":"co-(함께) + ordin(순서, 라틴어 ordo) + -ate → 함께 순서를 맞추다"},{"id":"d8-70","day":8,"word":"fundamental","meaning":"필수적인","ipa":"[ˌfʌndəˈmentl]","kr":"펀더멘틀","example":"Reading is a fundamental skill.","exampleKr":"읽기는 필수적인 기술이다.","roots":"fund(바닥, 라틴어 fundus) + -ment + -al → 바닥이 되는, 근본적인"},{"id":"d8-71","day":8,"word":"component","meaning":"요소","ipa":"[kəmˈpoʊnənt]","kr":"컴포우넌트","example":"Each component of the machine was tested.","exampleKr":"그 기계의 각 요소가 검사되었다.","roots":"com-(함께) + pon(놓다, 라틴어 ponere) + -ent → 함께 놓인 것, 구성요소"},{"id":"d8-72","day":8,"word":"formula","meaning":"공식","ipa":"[ˈfɔːrmjələ]","kr":"포뮬러","example":"The scientist discovered a new formula.","exampleKr":"그 과학자는 새로운 공식을 발견했다.","roots":"form(형태, 라틴어 forma) + -ula(작은 것) → 작게 정리된 형태, 공식"},{"id":"d8-73","day":8,"word":"deploy","meaning":"배치하다","ipa":"[dɪˈplɔɪ]","kr":"디플로이","example":"The company deployed the update overnight.","exampleKr":"그 회사는 밤새 업데이트를 배치했다.","roots":"de-(반대로, 라틴어 dis) + ploy(접다, 라틴어 plicare) → 접힌 것을 펼치다, 배치하다"},{"id":"d8-74","day":8,"word":"deployment","meaning":"배치","ipa":"[dɪˈplɔɪmənt]","kr":"디플로이먼트","example":"The deployment of troops began at dawn.","exampleKr":"병력 배치는 새벽에 시작되었다.","roots":"de-(반대로, 라틴어 dis) + ploy(접다, 라틴어 plicare) + -ment → 접힌 것을 펼쳐 배치함"},{"id":"d8-75","day":8,"word":"unfold","meaning":"펼치다","ipa":"[ʌnˈfoʊld]","kr":"언포울드","example":"The plan slowly unfolded over the year.","exampleKr":"그 계획은 한 해 동안 서서히 펼쳐졌다."},{"id":"d8-76","day":8,"word":"observe","meaning":"준수하다, 관찰하다","ipa":"[əbˈzɜːrv]","kr":"업저브","example":"He observed the birds through binoculars.","exampleKr":"그는 쌍안경으로 새들을 관찰했다.","roots":"ob-(향하여) + serv(지키다, 라틴어 servare) → 향해 지켜보다, 준수하다"},{"id":"d8-77","day":8,"word":"observance","meaning":"준수","ipa":"[əbˈzɜːrvəns]","kr":"업저번스","example":"The holiday observance varies by country.","exampleKr":"그 휴일 준수는 나라마다 다르다.","roots":"ob-(향하여) + serv(지키다, 라틴어 servare) + -ance → 지켜 따름, 준수"},{"id":"d8-78","day":8,"word":"observation","meaning":"관찰","ipa":"[ˌɑːbzərˈveɪʃn]","kr":"압저베이션","example":"Her observation skills are excellent.","exampleKr":"그녀의 관찰 능력은 뛰어나다.","roots":"ob-(향하여) + serv(지키다, 라틴어 servare) + -ation → 지켜봄, 관찰"},{"id":"d8-79","day":8,"word":"eternal","meaning":"불변의","ipa":"[ɪˈtɜːrnl]","kr":"이터늘","example":"They promised each other eternal love.","exampleKr":"그들은 서로에게 영원한 사랑을 약속했다."},{"id":"d8-80","day":8,"word":"perpetual","meaning":"불변의","ipa":"[pərˈpetʃuəl]","kr":"퍼페추얼","example":"The city seems to be in a state of perpetual construction.","exampleKr":"그 도시는 끊임없는 공사 상태에 있는 것 같다.","roots":"per-(내내) + pet(향하다, 라틴어 petere) + -ual → 끝까지 계속 나아가는"},{"id":"d8-81","day":8,"word":"permanent","meaning":"불변의","ipa":"[ˈpɜːrmənənt]","kr":"퍼머넌트","example":"The scar left a permanent mark.","exampleKr":"그 흉터는 영구적인 자국을 남겼다.","roots":"per-(끝까지) + man(머무르다, 라틴어 manere) + -ent → 끝까지 머무르는"},{"id":"d8-82","day":8,"word":"everlasting","meaning":"불변의","ipa":"[ˌevərˈlæstɪŋ]","kr":"에버래스팅","example":"She hoped for an everlasting friendship.","exampleKr":"그녀는 영원한 우정을 바랐다."},{"id":"d8-83","day":8,"word":"equation","meaning":"방정식","ipa":"[ɪˈkweɪʒn]","kr":"이퀘이전","example":"He solved the equation quickly.","exampleKr":"그는 그 방정식을 빠르게 풀었다.","roots":"equ(같은, 라틴어 aequus) + -ation → 같게 만드는 것, 방정식"},{"id":"d8-84","day":8,"word":"thrive","meaning":"번영하다, 발전하다","ipa":"[θraɪv]","kr":"쓰라이브","example":"Small startups thrive in supportive communities.","exampleKr":"작은 스타트업은 지원해주는 커뮤니티에서 번영한다."},{"id":"d8-85","day":8,"word":"flourish","meaning":"번영하다","ipa":"[ˈflɜːrɪʃ]","kr":"플러리시","example":"Art flourished during the Renaissance.","exampleKr":"예술은 르네상스 동안 번영했다.","roots":"flor(꽃, 라틴어 florere) + -ish → 꽃을 피우다, 번영하다"},{"id":"d8-86","day":8,"word":"prosper","meaning":"번영하다","ipa":"[ˈprɑːspər]","kr":"프라스퍼","example":"Businesses prospered after the tax cut.","exampleKr":"사업체들은 세금 감면 후 번영했다.","roots":"pro-(앞으로) + sper(희망, 라틴어 sperare) → 앞날에 희망을 갖다, 번영하다"},{"id":"d8-87","day":8,"word":"intense","meaning":"집중한, 격렬한","ipa":"[ɪnˈtens]","kr":"인텐스","example":"The competition was intense this year.","exampleKr":"올해 경쟁은 격렬했다.","roots":"in-(안으로) + tens(팽팽히 당기다, 라틴어 tendere) → 안으로 팽팽히 당겨진, 강렬한"},{"id":"d8-88","day":8,"word":"disciplined","meaning":"규칙을 따르는","ipa":"[ˈdɪsɪplɪnd]","kr":"디서플린드","example":"She has a disciplined approach to studying.","exampleKr":"그녀는 규칙을 따르는 학습 접근법을 가지고 있다.","roots":"discipl(제자, 라틴어 discipulus, discere '배우다'에서 유래) + -ine + -ed → 배움을 따라 훈련된"},{"id":"d8-89","day":8,"word":"manipulatory","meaning":"조작적인","ipa":"[məˈnɪpjələtɔːri]","kr":"머니퓰러토리","example":"His manipulatory tactics upset his coworkers.","exampleKr":"그의 조작적인 전술은 동료들을 화나게 했다.","roots":"manu(손, 라틴어 manus) + pul(채우다, 라틴어 plere) + -atory → 손으로 조작하는"},{"id":"d8-90","day":8,"word":"achievement","meaning":"완성, 성취","ipa":"[əˈtʃiːvmənt]","kr":"어치브먼트","example":"Winning the award was a great achievement.","exampleKr":"그 상을 받은 것은 큰 성취였다.","roots":"a-(~로) + chieve(끝, 고대 프랑스어 chief, 라틴어 caput) + -ment → 끝까지 이르러 이루어냄"},{"id":"d8-91","day":8,"word":"condense","meaning":"응축하다","ipa":"[kənˈdens]","kr":"컨덴스","example":"The article condenses years of research.","exampleKr":"그 기사는 수년간의 연구를 응축한다.","roots":"con-(함께) + dense(빽빽한, 라틴어 densus) → 함께 빽빽하게 만들다"},{"id":"d8-92","day":8,"word":"portable","meaning":"휴대용의","ipa":"[ˈpɔːrtəbl]","kr":"포터블","example":"She bought a portable charger for travel.","exampleKr":"그녀는 여행용 휴대용 충전기를 샀다.","roots":"port(나르다, 라틴어 portare) + -able → 나를 수 있는"},{"id":"d8-93","day":8,"word":"facilitate","meaning":"용이하게 하다","ipa":"[fəˈsɪlɪteɪt]","kr":"퍼실리테이트","example":"The app facilitates communication between teams.","exampleKr":"그 앱은 팀 간의 소통을 용이하게 한다.","roots":"facil(쉬운, 라틴어 facilis) + -itate → 쉽게 만들다"},{"id":"d8-94","day":8,"word":"facility","meaning":"시설","ipa":"[fəˈsɪləti]","kr":"퍼실러티","example":"The gym has a great sports facility.","exampleKr":"그 헬스장은 훌륭한 스포츠 시설을 가지고 있다.","roots":"facil(쉬운, 라틴어 facilis) + -ity → 쉽게 하는 것, 시설"},{"id":"d8-95","day":8,"word":"nomad","meaning":"유목민","ipa":"[ˈnoʊmæd]","kr":"노우매드","example":"He lived like a digital nomad.","exampleKr":"그는 디지털 유목민처럼 살았다."},{"id":"d8-96","day":8,"word":"given","meaning":"~를 고려하면","ipa":"[ˈɡɪvn]","kr":"기븐","example":"Given the weather, we should postpone the trip.","exampleKr":"날씨를 고려하면, 우리는 여행을 연기해야 한다."},{"id":"d8-97","day":8,"word":"variety","meaning":"다양성","ipa":"[vəˈraɪəti]","kr":"버라이어티","example":"The menu offers a wide variety of dishes.","exampleKr":"그 메뉴는 폭넓은 다양성의 요리를 제공한다.","roots":"vari(다양한, 라틴어 varius) + -ety → 다양한 상태"},{"id":"d8-98","day":8,"word":"utmost","meaning":"최고로","ipa":"[ˈʌtmoʊst]","kr":"엇모우스트","example":"Safety is of utmost importance.","exampleKr":"안전은 최고로 중요하다."},{"id":"d8-99","day":8,"word":"relevant","meaning":"관련있는","ipa":"[ˈreləvənt]","kr":"렐러번트","example":"Please share only relevant information.","exampleKr":"관련 있는 정보만 공유해 주세요.","roots":"re-(다시) + lev(들어올리다, 라틴어 levare) + -ant → 다시 끌어올려 관련짓는"},{"id":"d8-100","day":8,"word":"struggle","meaning":"수고, 노력","ipa":"[ˈstrʌɡl]","kr":"스트러글","example":"Her struggle to learn English paid off.","exampleKr":"영어를 배우려는 그녀의 노력은 결실을 맺었다."},{"id":"d9-1","day":9,"word":"pack","meaning":"포장하다","ipa":"[pæk]","kr":"팩","example":"She packed her bags for the trip.","exampleKr":"그녀는 여행을 위해 짐을 쌌다."},{"id":"d9-2","day":9,"word":"flexibility","meaning":"유연성, 융통성","ipa":"[ˌfleksəˈbɪləti]","kr":"플렉서빌러티","example":"Remote work offers more flexibility.","exampleKr":"재택근무는 더 많은 유연성을 제공한다.","roots":"flex(구부리다, 라틴어 flectere) + -ible + -ity → 잘 구부러지는 성질"},{"id":"d9-3","day":9,"word":"transit","meaning":"이동","ipa":"[ˈtrænzɪt]","kr":"트랜짓","example":"Public transit is efficient in this city.","exampleKr":"이 도시에서는 대중 이동수단이 효율적이다.","roots":"trans-(가로질러) + it(가다, 라틴어 ire) → 가로질러 감, 이동"},{"id":"d9-4","day":9,"word":"collaborate","meaning":"협동하다","ipa":"[kəˈlæbəreɪt]","kr":"컬래버레이트","example":"The two companies collaborated on a new product.","exampleKr":"두 회사는 새 제품에 대해 협동했다.","roots":"col-(함께, com-) + labor(일하다, 라틴어 laborare) + -ate → 함께 일하다"},{"id":"d9-5","day":9,"word":"cooperate","meaning":"협동하다","ipa":"[koʊˈɑːpəreɪt]","kr":"코오퍼레이트","example":"The neighbors cooperated to clean up the park.","exampleKr":"이웃들은 공원을 청소하기 위해 협동했다.","roots":"co-(함께) + operate(일하다, 라틴어 operari) → 함께 일하다"},{"id":"d9-6","day":9,"word":"coordinate","meaning":"협동하다","ipa":"[koʊˈɔːrdɪneɪt]","kr":"코오디네이트","example":"They coordinated their schedules for the trip.","exampleKr":"그들은 여행을 위해 일정을 조율했다.","roots":"co-(함께) + ordinate(순서 짓다, 라틴어 ordinare) → 함께 순서를 맞추다"},{"id":"d9-7","day":9,"word":"peer","meaning":"동료","ipa":"[pɪr]","kr":"피어","example":"She discussed the idea with her peers.","exampleKr":"그녀는 동료들과 그 아이디어를 논의했다."},{"id":"d9-8","day":9,"word":"colleague","meaning":"동료","ipa":"[ˈkɑːliːɡ]","kr":"칼리그","example":"He asked a colleague for advice.","exampleKr":"그는 동료에게 조언을 구했다.","roots":"col-(함께) + leg(임명하다, 라틴어 legare) → 함께 임명된 사람, 동료"},{"id":"d9-9","day":9,"word":"companion","meaning":"동료","ipa":"[kəmˈpænjən]","kr":"컴패니언","example":"His dog is his constant companion.","exampleKr":"그의 개는 항상 그의 동료다.","roots":"com-(함께) + pan(빵, 라틴어 panis) + -ion → 함께 빵을 먹는 사람"},{"id":"d9-10","day":9,"word":"associate","meaning":"동료","ipa":"[əˈsoʊʃiət]","kr":"어소시엇","example":"She works as an associate at the firm.","exampleKr":"그녀는 그 회사에서 동료로 일한다.","roots":"as-(~쪽으로, ad-) + soci(동료, 라틴어 socius) + -ate → 동료로 합쳐지다"},{"id":"d9-11","day":9,"word":"assemble","meaning":"조성하다, 모으다","ipa":"[əˈsembl]","kr":"어셈블","example":"The volunteers assembled to plan the event.","exampleKr":"자원봉사자들은 행사를 계획하기 위해 모였다.","roots":"as-(~쪽으로, ad-) + sembl(함께, 라틴어 simul) → 한데 모으다"},{"id":"d9-12","day":9,"word":"aggregate","meaning":"모으다","ipa":"[ˈæɡrɪɡeɪt]","kr":"애그리게이트","example":"The data was aggregated from multiple sources.","exampleKr":"그 데이터는 여러 출처에서 모아졌다.","roots":"ag-(~쪽으로, ad-) + greg(무리, 라틴어 grex) + -ate → 무리로 모으다"},{"id":"d9-13","day":9,"word":"abundant","meaning":"많은, 풍부한","ipa":"[əˈbʌndənt]","kr":"어번던트","example":"The region has abundant natural resources.","exampleKr":"그 지역은 풍부한 천연 자원을 가지고 있다.","roots":"ab-(강조) + und(물결치다, 라틴어 undare) + -ant → 넘쳐흐르는, 풍부한"},{"id":"d9-14","day":9,"word":"plentiful","meaning":"풍부한","ipa":"[ˈplentɪfl]","kr":"플렌티플","example":"Food was plentiful during the harvest season.","exampleKr":"수확철에는 음식이 풍부했다.","roots":"plen(가득한, 라틴어 plenus) + -ty + -ful → 가득 차 있는"},{"id":"d9-15","day":9,"word":"ample","meaning":"풍부한","ipa":"[ˈæmpl]","kr":"앰플","example":"There is ample parking near the venue.","exampleKr":"행사장 근처에는 충분한 주차 공간이 있다."},{"id":"d9-16","day":9,"word":"mammal","meaning":"포유동물","ipa":"[ˈmæml]","kr":"매멀","example":"A whale is a mammal, not a fish.","exampleKr":"고래는 물고기가 아니라 포유동물이다.","roots":"mamma(젖가슴, 라틴어 mamma) + -al → 젖을 먹이는 동물"},{"id":"d9-17","day":9,"word":"somewhat","meaning":"다소","ipa":"[ˈsʌmwʌt]","kr":"섬왓","example":"The situation improved somewhat after the meeting.","exampleKr":"그 상황은 회의 후 다소 나아졌다."},{"id":"d9-18","day":9,"word":"more or less","meaning":"다소","ipa":"[mɔːr ɔːr les]","kr":"모어 오어 레스","example":"The two designs are more or less the same.","exampleKr":"두 디자인은 다소 같다."},{"id":"d9-19","day":9,"word":"extinct","meaning":"멸종된","ipa":"[ɪkˈstɪŋkt]","kr":"익스팅트","example":"The species went extinct decades ago.","exampleKr":"그 종은 수십 년 전에 멸종되었다.","roots":"ex-(밖으로) + stinct(끄다, 라틴어 stinguere) → 완전히 꺼진, 멸종된"},{"id":"d9-20","day":9,"word":"instinct","meaning":"본능","ipa":"[ˈɪnstɪŋkt]","kr":"인스팅트","example":"Her maternal instinct kicked in immediately.","exampleKr":"그녀의 모성 본능이 즉시 발동했다.","roots":"in-(안으로) + stinct(찌르다, 라틴어 stinguere) → 안에서 찔러 움직이게 하는 충동, 본능"},{"id":"d9-21","day":9,"word":"distinct","meaning":"뚜렷한, 구분되는","ipa":"[dɪˈstɪŋkt]","kr":"디스팅트","example":"The two accents are quite distinct.","exampleKr":"그 두 억양은 꽤 뚜렷이 구분된다.","roots":"di-(분리) + stinct(찌르다, 라틴어 stinguere) → 찔러서 갈라놓아 구별되는"},{"id":"d9-22","day":9,"word":"fossil","meaning":"화석","ipa":"[ˈfɑːsl]","kr":"파슬","example":"They found a dinosaur fossil in the desert.","exampleKr":"그들은 사막에서 공룡 화석을 발견했다.","roots":"foss(파내다, 라틴어 fodere) + -il → 땅에서 파낸 것, 화석"},{"id":"d9-23","day":9,"word":"analysis","meaning":"분석","ipa":"[əˈnæləsɪs]","kr":"어낼러시스","example":"The report includes a detailed analysis.","exampleKr":"그 보고서는 상세한 분석을 포함한다.","roots":"ana-(완전히, 그리스어) + lysis(풀다, 그리스어 lyein) → 완전히 풀어 나눔, 분석"},{"id":"d9-24","day":9,"word":"shrink","meaning":"줄어들다","ipa":"[ʃrɪŋk]","kr":"슈링크","example":"The economy shrank during the recession.","exampleKr":"경제는 경기 침체 동안 줄어들었다."},{"id":"d9-25","day":9,"word":"diminish","meaning":"줄어들다","ipa":"[dɪˈmɪnɪʃ]","kr":"디미니시","example":"His influence diminished over the years.","exampleKr":"그의 영향력은 수년에 걸쳐 줄어들었다.","roots":"di-(분리) + minish(작게 만들다, 라틴어 minuere) → 작게 쪼개어 줄이다"},{"id":"d9-26","day":9,"word":"lessen","meaning":"줄어들다","ipa":"[ˈlesn]","kr":"레슨","example":"The medicine helped lessen the pain.","exampleKr":"그 약은 고통을 줄이는 데 도움이 되었다."},{"id":"d9-27","day":9,"word":"dwindle","meaning":"줄어들다","ipa":"[ˈdwɪndl]","kr":"드윈들","example":"The population dwindled after the war.","exampleKr":"인구는 전쟁 후 줄어들었다."},{"id":"d9-28","day":9,"word":"countless","meaning":"셀 수 없이 많은","ipa":"[ˈkaʊntləs]","kr":"카운틀리스","example":"She has answered countless questions today.","exampleKr":"그녀는 오늘 셀 수 없이 많은 질문에 답했다."},{"id":"d9-29","day":9,"word":"numerous","meaning":"무수히 많은","ipa":"[ˈnuːmərəs]","kr":"뉴머러스","example":"He has won numerous awards.","exampleKr":"그는 무수히 많은 상을 받았다.","roots":"numer(수, 라틴어 numerus) + -ous → 수가 많은"},{"id":"d9-30","day":9,"word":"a host of","meaning":"수많은","ipa":"[ə hoʊst əv]","kr":"어 호스트 오브","example":"The event faced a host of problems.","exampleKr":"그 행사는 수많은 문제에 직면했다."},{"id":"d9-31","day":9,"word":"innumerable","meaning":"수많은","ipa":"[ɪˈnuːmərəbl]","kr":"이뉴머러블","example":"There are innumerable stars in the sky.","exampleKr":"하늘에는 수많은 별이 있다.","roots":"in-(부정) + numer(수, 라틴어 numerus) + -able → 셀 수 없는"},{"id":"d9-32","day":9,"word":"a number of","meaning":"수많은","ipa":"[ə ˈnʌmbər əv]","kr":"어 넘버 오브","example":"A number of students missed the deadline.","exampleKr":"수많은 학생들이 마감일을 놓쳤다."},{"id":"d9-33","day":9,"word":"lineage","meaning":"혈통","ipa":"[ˈlɪniɪdʒ]","kr":"리니지","example":"The family traces its lineage back centuries.","exampleKr":"그 가문은 자신들의 혈통을 몇 세기 전까지 추적한다.","roots":"line(선, 라틴어 linea) + -age → 이어져 내려온 선, 혈통"},{"id":"d9-34","day":9,"word":"split","meaning":"분리","ipa":"[splɪt]","kr":"스플릿","example":"The road splits into two directions.","exampleKr":"그 길은 두 방향으로 분리된다."},{"id":"d9-35","day":9,"word":"gradual","meaning":"점진적인","ipa":"[ˈɡrædʒuəl]","kr":"그래주얼","example":"The change was gradual but noticeable.","exampleKr":"그 변화는 점진적이었지만 눈에 띄었다.","roots":"grad(걸음, 라틴어 gradus) + -ual → 한 걸음씩 나아가는"},{"id":"d9-36","day":9,"word":"evolution","meaning":"진화","ipa":"[ˌevəˈluːʃn]","kr":"에벌루션","example":"The evolution of the species took millions of years.","exampleKr":"그 종의 진화는 수백만 년이 걸렸다.","roots":"e-(밖으로, ex-) + vol(구르다, 라틴어 volvere) + -ution → 밖으로 펼쳐져 나옴, 진화"},{"id":"d9-37","day":9,"word":"branch","meaning":"가지","ipa":"[bræntʃ]","kr":"브랜치","example":"The company opened a new branch downtown.","exampleKr":"그 회사는 시내에 새 지점을 열었다."},{"id":"d9-38","day":9,"word":"break off","meaning":"갈라지다, 분리되다","ipa":"[breɪk ɔːf]","kr":"브레이크 오프","example":"The two countries broke off diplomatic ties.","exampleKr":"두 나라는 외교 관계를 단절했다."},{"id":"d9-39","day":9,"word":"at least","meaning":"최소한, 적어도","ipa":"[æt liːst]","kr":"앳 리스트","example":"Bring at least two forms of ID.","exampleKr":"최소한 두 가지 신분증을 가져오세요."},{"id":"d9-40","day":9,"word":"at most","meaning":"기껏해야","ipa":"[æt moʊst]","kr":"앳 모우스트","example":"The wait will be ten minutes at most.","exampleKr":"대기 시간은 기껏해야 10분일 것이다."},{"id":"d9-41","day":9,"word":"wheat","meaning":"밀","ipa":"[wiːt]","kr":"위트","example":"Farmers harvested the wheat in early summer.","exampleKr":"농부들은 초여름에 밀을 수확했다."},{"id":"d9-42","day":9,"word":"barley","meaning":"보리","ipa":"[ˈbɑːrli]","kr":"발리","example":"Beer is made from barley.","exampleKr":"맥주는 보리로 만들어진다."},{"id":"d9-43","day":9,"word":"domestication","meaning":"재배","ipa":"[dəˌmestɪˈkeɪʃn]","kr":"더메스티케이션","example":"The domestication of dogs began thousands of years ago.","exampleKr":"개의 가축화는 수천 년 전에 시작되었다.","roots":"domest(집의, 라틴어 domus) + -ic + -ate + -ion → 집 안으로 들여 기름, 길들이기"},{"id":"d9-44","day":9,"word":"along with","meaning":"~와 함께","ipa":"[əˈlɔːŋ wɪð]","kr":"얼롱 위드","example":"She brought snacks along with drinks.","exampleKr":"그녀는 음료와 함께 간식을 가져왔다."},{"id":"d9-45","day":9,"word":"weed","meaning":"잡초, 풀","ipa":"[wiːd]","kr":"위드","example":"He pulled the weeds from the garden.","exampleKr":"그는 정원에서 잡초를 뽑았다."},{"id":"d9-46","day":9,"word":"rye","meaning":"호밀","ipa":"[raɪ]","kr":"라이","example":"He ordered a sandwich made with rye bread.","exampleKr":"그는 호밀 빵으로 만든 샌드위치를 주문했다."},{"id":"d9-47","day":9,"word":"unenviable","meaning":"부러워할 것 없는","ipa":"[ʌnˈenviəbl]","kr":"언엔비어블","example":"She had the unenviable task of firing employees.","exampleKr":"그녀는 직원들을 해고해야 하는 부러워할 것 없는 임무를 맡았다.","roots":"un-(부정) + envi(부러워하다, 라틴어 invidia) + -able → 부러워할 수 없는"},{"id":"d9-48","day":9,"word":"eliminate","meaning":"제거하다","ipa":"[ɪˈlɪmɪneɪt]","kr":"일리미네이트","example":"The team eliminated all errors before launch.","exampleKr":"그 팀은 출시 전에 모든 오류를 제거했다.","roots":"e-(밖으로, ex-) + limin(문지방, 라틴어 limen) + -ate → 문 밖으로 내쫓다, 제거하다"},{"id":"d9-49","day":9,"word":"get rid of","meaning":"제거하다","ipa":"[ɡet rɪd əv]","kr":"겟 리드 오브","example":"He got rid of his old furniture.","exampleKr":"그는 오래된 가구를 제거했다."},{"id":"d9-50","day":9,"word":"do away with","meaning":"제거하다","ipa":"[duː əˈweɪ wɪð]","kr":"두 어웨이 위드","example":"The company did away with paper forms.","exampleKr":"그 회사는 종이 양식을 없앴다."},{"id":"d9-51","day":9,"word":"invader","meaning":"침입자","ipa":"[ɪnˈveɪdər]","kr":"인베이더","example":"The invaders were driven back from the border.","exampleKr":"침입자들은 국경에서 격퇴되었다.","roots":"in-(안으로) + vad(가다, 라틴어 vadere) + -er → 안으로 쳐들어가는 사람"},{"id":"d9-52","day":9,"word":"cultivation","meaning":"경작, 재배","ipa":"[ˌkʌltɪˈveɪʃn]","kr":"컬티베이션","example":"The cultivation of rice requires a lot of water.","exampleKr":"쌀의 경작에는 많은 물이 필요하다.","roots":"cult(경작하다, 라틴어 colere) + -ivate + -ion → 땅을 갈아 기름"},{"id":"d9-53","day":9,"word":"expand","meaning":"확장하다","ipa":"[ɪkˈspænd]","kr":"익스팬드","example":"The company expanded into new markets.","exampleKr":"그 회사는 새로운 시장으로 확장했다.","roots":"ex-(밖으로) + pand(펼치다, 라틴어 pandere) → 밖으로 펼치다"},{"id":"d9-54","day":9,"word":"expend","meaning":"소비하다","ipa":"[ɪkˈspend]","kr":"익스펜드","example":"They expended a lot of energy on the project.","exampleKr":"그들은 그 프로젝트에 많은 에너지를 소비했다.","roots":"ex-(밖으로) + pend(지불하다, 라틴어 pendere) → 밖으로 지불하다, 소비하다"},{"id":"d9-55","day":9,"word":"extend","meaning":"연장하다","ipa":"[ɪkˈstend]","kr":"익스텐드","example":"She extended her stay by two days.","exampleKr":"그녀는 체류를 이틀 연장했다.","roots":"ex-(밖으로) + tend(뻗다, 라틴어 tendere) → 밖으로 뻗다"},{"id":"d9-56","day":9,"word":"distribution","meaning":"분포, 분배","ipa":"[ˌdɪstrɪˈbjuːʃn]","kr":"디스트리뷰션","example":"The distribution of wealth remains unequal.","exampleKr":"부의 분포는 여전히 불균등하다.","roots":"dis-(나누어) + tribut(주다, 라틴어 tribuere) + -ion → 나누어 줌"},{"id":"d9-57","day":9,"word":"prove","meaning":"증명하다","ipa":"[pruːv]","kr":"프루브","example":"The test proved his theory correct.","exampleKr":"그 실험은 그의 이론이 옳다는 것을 증명했다."},{"id":"d9-58","day":9,"word":"disprove","meaning":"틀렸다고 증명하다","ipa":"[dɪsˈpruːv]","kr":"디스프루브","example":"New evidence disproved the old theory.","exampleKr":"새 증거가 그 낡은 이론이 틀렸다고 증명했다.","roots":"dis-(반대) + prove(입증하다, 라틴어 probare) → 틀렸음을 입증하다"},{"id":"d9-59","day":9,"word":"approve","meaning":"승인하다, 인정하다","ipa":"[əˈpruːv]","kr":"어프루브","example":"The board approved the new budget.","exampleKr":"이사회는 새 예산을 승인했다.","roots":"ap-(~쪽으로, ad-) + prove(입증하다, 라틴어 probare) → ~쪽으로 인정하다"},{"id":"d9-60","day":9,"word":"improve","meaning":"향상시키다","ipa":"[ɪmˈpruːv]","kr":"임프루브","example":"Practice will improve your writing skills.","exampleKr":"연습은 글쓰기 실력을 향상시킬 것이다.","roots":"im-(안으로, en-) + prove(이익이 되게 하다, 고대 프랑스어 prou) → 이익이 되게 만들다, 향상시키다"},{"id":"d9-61","day":9,"word":"attach","meaning":"들러붙다","ipa":"[əˈtætʃ]","kr":"어태치","example":"Please attach the file to your email.","exampleKr":"이메일에 파일을 첨부해 주세요.","roots":"at-(~쪽으로, ad-) + tach(못, 고대 프랑스어 tache) → ~에 못박아 붙이다"},{"id":"d9-62","day":9,"word":"detach","meaning":"떼다","ipa":"[dɪˈtætʃ]","kr":"디태치","example":"He detached the trailer from the truck.","exampleKr":"그는 트레일러를 트럭에서 떼어냈다.","roots":"de-(분리) + tach(못, 고대 프랑스어 tache) → 못을 떼어내다"},{"id":"d9-63","day":9,"word":"replace","meaning":"대신하다, 대체하다","ipa":"[rɪˈpleɪs]","kr":"리플레이스","example":"Nothing can replace her experience.","exampleKr":"어떤 것도 그녀의 경험을 대신할 수 없다.","roots":"re-(다시) + place(자리, 고대 프랑스어 place) → 자리를 다시 잡다, 대체하다"},{"id":"d9-64","day":9,"word":"pathway","meaning":"경로","ipa":"[ˈpæθweɪ]","kr":"패쓰웨이","example":"The pathway led to a hidden garden.","exampleKr":"그 경로는 숨겨진 정원으로 이어졌다."},{"id":"d9-65","day":9,"word":"obtain","meaning":"얻다","ipa":"[əbˈteɪn]","kr":"업테인","example":"He obtained a license to practice law.","exampleKr":"그는 법률 실무 자격증을 얻었다.","roots":"ob-(~을 향해) + tain(잡다, 라틴어 tenere) → 향해 잡아 얻다"},{"id":"d9-66","day":9,"word":"attain","meaning":"얻다","ipa":"[əˈteɪn]","kr":"어테인","example":"She attained fluency after years of practice.","exampleKr":"그녀는 수년간의 연습 후 유창함을 얻었다.","roots":"at-(~쪽으로, ad-) + tain(닿다, 라틴어 tangere) → 닿아서 이루다"},{"id":"d9-67","day":9,"word":"sustain","meaning":"유지하다","ipa":"[səˈsteɪn]","kr":"서스테인","example":"The company must sustain its growth.","exampleKr":"그 회사는 성장을 유지해야 한다.","roots":"sus-(아래에서, sub-) + tain(잡다, 라틴어 tenere) → 아래서 받쳐 잡다, 유지하다"},{"id":"d9-68","day":9,"word":"retain","meaning":"유지하다","ipa":"[rɪˈteɪn]","kr":"리테인","example":"They retained their top employees.","exampleKr":"그들은 최고의 직원들을 유지했다.","roots":"re-(뒤로) + tain(잡다, 라틴어 tenere) → 뒤에 붙잡아 둠, 유지하다"},{"id":"d9-69","day":9,"word":"contain","meaning":"제한하다","ipa":"[kənˈteɪn]","kr":"컨테인","example":"The report contains sensitive information.","exampleKr":"그 보고서는 민감한 정보를 담고 있다.","roots":"con-(함께) + tain(잡다, 라틴어 tenere) → 함께 담아 잡다"},{"id":"d9-70","day":9,"word":"concerning","meaning":"~와 관련한","ipa":"[kənˈsɜːrnɪŋ]","kr":"컨서닝","example":"He shared an update concerning the project.","exampleKr":"그는 그 프로젝트와 관련한 소식을 공유했다.","roots":"con-(함께) + cern(구별하다, 라틴어 cernere) + -ing → 함께 관련지어 살핌"},{"id":"d9-71","day":9,"word":"regarding","meaning":"~와 관련한","ipa":"[rɪˈɡɑːrdɪŋ]","kr":"리가딩","example":"She had questions regarding the contract.","exampleKr":"그녀는 그 계약과 관련한 질문이 있었다.","roots":"re-(다시) + gard(보다, 고대 프랑스어 regarder) + -ing → 다시 돌아봄, ~에 관하여"},{"id":"d9-72","day":9,"word":"with regard to","meaning":"~와 관련한","ipa":"[wɪð rɪˈɡɑːrd tuː]","kr":"위드 리가드 투","example":"With regard to the schedule, nothing has changed.","exampleKr":"일정과 관련하여, 바뀐 것은 없다."},{"id":"d9-73","day":9,"word":"with respect to","meaning":"~와 관련한","ipa":"[wɪð rɪˈspekt tuː]","kr":"위드 리스펙트 투","example":"With respect to the budget, we need approval.","exampleKr":"예산과 관련하여, 우리는 승인이 필요하다."},{"id":"d9-74","day":9,"word":"intermediate","meaning":"중개자","ipa":"[ˌɪntərˈmiːdiət]","kr":"인터미디엇","example":"The broker acted as an intermediate between buyer and seller.","exampleKr":"그 중개인은 구매자와 판매자 사이의 중개자 역할을 했다.","roots":"inter-(사이에) + medi(중간, 라틴어 medius) + -ate → 사이 중간에 있는"},{"id":"d9-75","day":9,"word":"wholesaler","meaning":"도매업자","ipa":"[ˈhoʊlseɪlər]","kr":"호울세일러","example":"The wholesaler supplies goods to many stores.","exampleKr":"그 도매업자는 많은 가게에 상품을 공급한다."},{"id":"d9-76","day":9,"word":"retailer","meaning":"소매업자","ipa":"[ˈriːteɪlər]","kr":"리테일러","example":"The retailer offered a discount for the holiday.","exampleKr":"그 소매업자는 연휴 할인을 제공했다.","roots":"re-(다시) + tail(자르다, 고대 프랑스어 taillier) + -er → 잘라서 되파는 사람"},{"id":"d9-77","day":9,"word":"relatively","meaning":"상대적으로, 비교적","ipa":"[ˈrelətɪvli]","kr":"렐러티블리","example":"The town remained relatively unchanged over the years.","exampleKr":"그 마을은 수년 동안 비교적 변하지 않았다.","roots":"re-(다시) + lat(옮기다, 라틴어 latus) + -ive + -ly → 관계지어, 상대적으로"},{"id":"d9-78","day":9,"word":"handle","meaning":"취급하다, 다루다","ipa":"[ˈhændl]","kr":"핸들","example":"She handles customer complaints professionally.","exampleKr":"그녀는 고객 불만을 전문적으로 다룬다."},{"id":"d9-79","day":9,"word":"volume","meaning":"양, 부피","ipa":"[ˈvɑːljuːm]","kr":"발륨","example":"The volume of traffic increased during rush hour.","exampleKr":"러시아워 동안 교통량이 증가했다.","roots":"vol(구르다, 라틴어 volvere) + -ume → 둘둘 말린 두루마리, 책의 부피"},{"id":"d9-80","day":9,"word":"provision","meaning":"제공","ipa":"[prəˈvɪʒn]","kr":"프러비전","example":"The contract includes a provision for late fees.","exampleKr":"그 계약서에는 연체료에 대한 조항이 포함되어 있다.","roots":"pro-(미리) + vis(보다, 라틴어 videre) + -ion → 미리 내다보고 준비함"},{"id":"d9-81","day":9,"word":"impractical","meaning":"실제적이지 않은","ipa":"[ɪmˈpræktɪkl]","kr":"임프랙티클","example":"The idea sounded impractical in real life.","exampleKr":"그 아이디어는 실생활에서는 비현실적으로 들렸다.","roots":"im-(부정) + practic(실행하는, 그리스어 praktikos) + -al → 실행되지 않는"},{"id":"d9-82","day":9,"word":"food chain","meaning":"식품 유통","ipa":"[fuːd tʃeɪn]","kr":"푸드 체인","example":"Sharks are near the top of the food chain.","exampleKr":"상어는 먹이 사슬의 최상위에 가깝다."},{"id":"d9-83","day":9,"word":"via","meaning":"~를 통해","ipa":"[ˈvaɪə]","kr":"바이어","example":"He sent the file via email.","exampleKr":"그는 이메일을 통해 파일을 보냈다."},{"id":"d9-84","day":9,"word":"diminish","meaning":"감소시키다","ipa":"[dɪˈmɪnɪʃ]","kr":"디미니시","example":"Her enthusiasm diminished over time.","exampleKr":"그녀의 열정은 시간이 지나며 감소했다."},{"id":"d9-85","day":9,"word":"undermine","meaning":"약화시키다, 훼손하다","ipa":"[ˌʌndərˈmaɪn]","kr":"언더마인","example":"Constant criticism undermined his confidence.","exampleKr":"끊임없는 비판은 그의 자신감을 약화시켰다.","roots":"under-(아래) + mine(파다, 고대 프랑스어 miner) → 아래를 파다, 약화시키다"},{"id":"d9-86","day":9,"word":"compromise","meaning":"훼손하다","ipa":"[ˈkɑːmprəmaɪz]","kr":"캄프러마이즈","example":"The leak compromised the security system.","exampleKr":"그 유출은 보안 시스템을 훼손했다.","roots":"com-(함께) + promise(약속하다, 라틴어 promittere) → 함께 약속하여 타협하다"},{"id":"d9-87","day":9,"word":"deteriorate","meaning":"훼손하다","ipa":"[dɪˈtɪriəreɪt]","kr":"디티리어레이트","example":"His health deteriorated rapidly.","exampleKr":"그의 건강은 빠르게 악화되었다.","roots":"deterior(더 나쁜, 라틴어 deterior) + -ate → 더 나빠지다"},{"id":"d9-88","day":9,"word":"devastate","meaning":"훼손하다","ipa":"[ˈdevəsteɪt]","kr":"데버스테이트","example":"The news devastated the whole family.","exampleKr":"그 소식은 온 가족을 황폐화했다.","roots":"de-(완전히) + vast(황폐하게 하다, 라틴어 vastare) + -ate → 완전히 황폐하게 만들다"},{"id":"d9-89","day":9,"word":"impair","meaning":"훼손하다","ipa":"[ɪmˈper]","kr":"임페어","example":"Alcohol can impair your judgment.","exampleKr":"술은 판단력을 훼손할 수 있다.","roots":"im-(강조) + pair(더 나쁘게, 라틴어 pejor) → 더 나쁘게 만들다, 훼손하다"},{"id":"d9-90","day":9,"word":"autonomy","meaning":"자율성","ipa":"[ɔːˈtɑːnəmi]","kr":"오타너미","example":"Teenagers seek more autonomy from their parents.","exampleKr":"십 대들은 부모로부터 더 많은 자율성을 추구한다.","roots":"auto-(스스로, 그리스어) + nomy(법, 그리스어 nomos) → 스스로 법을 세움, 자율"},{"id":"d9-91","day":9,"word":"bacterium","meaning":"박테리아","ipa":"[bækˈtɪriəm]","kr":"백티리엄","example":"A single bacterium can multiply quickly.","exampleKr":"단일 박테리아는 빠르게 증식할 수 있다.","roots":"bacter(작은 막대, 그리스어 bakterion) + -ium → 막대 모양의 미생물"},{"id":"d9-92","day":9,"word":"indication","meaning":"알려줌, 지시","ipa":"[ˌɪndɪˈkeɪʃn]","kr":"인디케이션","example":"There was no indication of foul play.","exampleKr":"범죄의 낌새는 전혀 없었다.","roots":"in-(안으로) + dic(가리켜 말하다, 라틴어 dicare) + -ation → 안을 가리켜 보여줌"},{"id":"d9-93","day":9,"word":"overcome","meaning":"극복하다","ipa":"[ˌoʊvərˈkʌm]","kr":"오버컴","example":"She overcame her fear of flying.","exampleKr":"그녀는 비행에 대한 두려움을 극복했다."},{"id":"d9-94","day":9,"word":"get over","meaning":"극복하다","ipa":"[ɡet ˈoʊvər]","kr":"겟 오버","example":"It took months to get over the loss.","exampleKr":"그 상실을 극복하는 데 몇 달이 걸렸다."},{"id":"d9-95","day":9,"word":"concentration","meaning":"농도","ipa":"[ˌkɑːnsnˈtreɪʃn]","kr":"칸선트레이션","example":"The medicine's concentration was too high.","exampleKr":"그 약의 농도는 너무 높았다.","roots":"con-(함께) + centr(중심, 라틴어 centrum) + -ation → 중심으로 모음, 농축"},{"id":"d9-96","day":9,"word":"after all","meaning":"결국, 어쨌든","ipa":"[ˈæftər ɔːl]","kr":"애프터 올","example":"After all, he was right about the weather.","exampleKr":"결국, 그는 날씨에 대해 옳았다."},{"id":"d9-97","day":9,"word":"nirvana","meaning":"극락","ipa":"[nɪrˈvɑːnə]","kr":"니르바나","example":"Buddhists seek nirvana through meditation.","exampleKr":"불교도들은 명상을 통해 극락을 추구한다."},{"id":"d9-98","day":9,"word":"ingenious","meaning":"독창적인","ipa":"[ɪnˈdʒiːniəs]","kr":"인지니어스","example":"Her ingenious solution saved the company money.","exampleKr":"그녀의 독창적인 해결책은 회사의 돈을 절약했다.","roots":"in-(안에) + geni(타고나다, 라틴어 gignere) + -ous → 타고난 재능이 있는"},{"id":"d9-99","day":9,"word":"innovative","meaning":"독창적인","ipa":"[ˈɪnəveɪtɪv]","kr":"이노베이티브","example":"The startup developed an innovative app.","exampleKr":"그 스타트업은 독창적인 앱을 개발했다.","roots":"in-(안으로) + nov(새로운, 라틴어 novus) + -ate + -ive → 새로운 것을 안으로 들여오는"},{"id":"d9-100","day":9,"word":"original","meaning":"독창적인","ipa":"[əˈrɪdʒənl]","kr":"어리저늘","example":"The artist created an original piece for the show.","exampleKr":"그 예술가는 전시를 위해 독창적인 작품을 만들었다.","roots":"origin(기원, 라틴어 oriri) + -al → 기원이 되는, 독창적인"},{"id":"d10-1","day":10,"word":"sense","meaning":"감지하다","ipa":"[sens]","kr":"센스","example":"She could sense something was wrong.","exampleKr":"그녀는 뭔가 잘못됐음을 감지할 수 있었다."},{"id":"d10-2","day":10,"word":"detect","meaning":"감지하다","ipa":"[dɪˈtekt]","kr":"디텍트","example":"The alarm detected smoke immediately.","exampleKr":"그 경보는 즉시 연기를 감지했다.","roots":"de-(제거) + tect(덮다, 라틴어 tegere) → 덮개를 벗겨내다, 감지하다"},{"id":"d10-3","day":10,"word":"perceive","meaning":"감지하다","ipa":"[pərˈsiːv]","kr":"퍼시브","example":"People perceive risk differently.","exampleKr":"사람들은 위험을 다르게 감지한다.","roots":"per-(완전히) + ceive(잡다, 라틴어 capere) → 완전히 붙잡다, 인지하다"},{"id":"d10-4","day":10,"word":"preferable","meaning":"선호되는, 바람직한","ipa":"[ˈprefrəbl]","kr":"프레퍼러블","example":"A direct flight is preferable to a layover.","exampleKr":"직항 비행이 경유보다 선호된다.","roots":"pre-(먼저) + fer(나르다, 라틴어 ferre) + -able(~할 수 있는) → 먼저 옮겨질 만한, 선호되는"},{"id":"d10-5","day":10,"word":"amygdala","meaning":"편도체","ipa":"[əˈmɪɡdələ]","kr":"어미그덜러","example":"The amygdala processes fear responses.","exampleKr":"편도체는 두려움 반응을 처리한다."},{"id":"d10-6","day":10,"word":"weigh in","meaning":"관여하다","ipa":"[weɪ ɪn]","kr":"웨이 인","example":"Emotions often weigh in on our decisions.","exampleKr":"감정은 종종 우리의 결정에 관여한다."},{"id":"d10-7","day":10,"word":"release","meaning":"분비하다, 방출하다","ipa":"[rɪˈliːs]","kr":"릴리스","example":"The body releases stress hormones under pressure.","exampleKr":"신체는 압박 속에서 스트레스 호르몬을 분비한다.","roots":"re-(다시) + lease(느슨하게 하다, 라틴어 laxare) → 다시 느슨하게 풀어주다, 방출하다"},{"id":"d10-8","day":10,"word":"sinking","meaning":"무거운, 가라앉는","ipa":"[ˈsɪŋkɪŋ]","kr":"싱킹","example":"She had a sinking feeling about the interview.","exampleKr":"그녀는 면접에 대해 무거운 느낌이 들었다."},{"id":"d10-9","day":10,"word":"guilt","meaning":"죄","ipa":"[ɡɪlt]","kr":"길트","example":"He felt guilt after breaking the promise.","exampleKr":"그는 약속을 어긴 후 죄책감을 느꼈다."},{"id":"d10-10","day":10,"word":"further","meaning":"더, 더욱이","ipa":"[ˈfɜːrðər]","kr":"퍼더","example":"Let's discuss this further tomorrow.","exampleKr":"이것에 대해 내일 더 논의하자."},{"id":"d10-11","day":10,"word":"monetary","meaning":"금전적인","ipa":"[ˈmʌnɪteri]","kr":"머니터리","example":"The prize includes a monetary reward.","exampleKr":"그 상에는 금전적 보상이 포함된다.","roots":"monet(화폐, 라틴어 moneta) + -ary(형용사형) → 화폐에 관한, 금전적인"},{"id":"d10-12","day":10,"word":"get caught","meaning":"들통나다, 잡히다","ipa":"[ɡet kɔːt]","kr":"겟 코트","example":"He got caught cheating on the test.","exampleKr":"그는 시험에서 부정행위를 하다가 들통났다."},{"id":"d10-13","day":10,"word":"fade","meaning":"사라지다","ipa":"[feɪd]","kr":"페이드","example":"Her enthusiasm began to fade.","exampleKr":"그녀의 열정은 사라지기 시작했다."},{"id":"d10-14","day":10,"word":"perish","meaning":"사라지다","ipa":"[ˈperɪʃ]","kr":"페리시","example":"The plants perished in the frost.","exampleKr":"그 식물들은 서리에 사라졌다.","roots":"per-(완전히) + ish(가다, 라틴어 ire) → 완전히 가버리다, 사라지다"},{"id":"d10-15","day":10,"word":"wither","meaning":"사라지다, 시들다","ipa":"[ˈwɪðər]","kr":"위더","example":"The flowers withered without water.","exampleKr":"그 꽃들은 물 없이 시들었다."},{"id":"d10-16","day":10,"word":"markedly","meaning":"현저하게","ipa":"[ˈmɑːrkɪdli]","kr":"마킷들리","example":"Prices increased markedly this year.","exampleKr":"올해 물가가 현저하게 올랐다."},{"id":"d10-17","day":10,"word":"conspicuously","meaning":"매우, 현저하게","ipa":"[kənˈspɪkjuəsli]","kr":"컨스피큐어슬리","example":"He was conspicuously absent from the meeting.","exampleKr":"그는 회의에 눈에 띄게 결석했다.","roots":"con-(강조) + spic(보다, 라틴어 specere) + -uous + -ly → 눈에 잘 띄도록"},{"id":"d10-18","day":10,"word":"strikingly","meaning":"매우, 현저하게","ipa":"[ˈstraɪkɪŋli]","kr":"스트라이킹리","example":"The two brothers look strikingly similar.","exampleKr":"두 형제는 매우 닮았다."},{"id":"d10-19","day":10,"word":"engagement","meaning":"참가, 일","ipa":"[ɪnˈɡeɪdʒmənt]","kr":"인게이지먼트","example":"Community engagement increased after the event.","exampleKr":"지역 사회 참가는 그 행사 이후 증가했다.","roots":"en-(만들다) + gage(담보, 고대 프랑스어 gage) + -ment(명사형) → 약속으로 묶어놓음, 참가/약혼"},{"id":"d10-20","day":10,"word":"dishonest","meaning":"부정직한","ipa":"[dɪsˈɑːnɪst]","kr":"디스아니스트","example":"It's dishonest to hide the truth.","exampleKr":"진실을 숨기는 것은 부정직하다.","roots":"dis-(부정) + honest(정직한, 라틴어 honestus) → 정직하지 않은"},{"id":"d10-21","day":10,"word":"trigger","meaning":"유발하다","ipa":"[ˈtrɪɡər]","kr":"트리거","example":"The smell triggered an old memory.","exampleKr":"그 냄새는 오래된 기억을 유발했다."},{"id":"d10-22","day":10,"word":"result in","meaning":"~을 초래하다","ipa":"[rɪˈzʌlt ɪn]","kr":"리절트 인","example":"The delay resulted in extra costs.","exampleKr":"그 지연은 추가 비용을 초래했다."},{"id":"d10-23","day":10,"word":"prompt","meaning":"~을 초래하다","ipa":"[prɑːmpt]","kr":"프람프트","example":"His question prompted a long discussion.","exampleKr":"그의 질문은 긴 토론을 초래했다.","roots":"pro-(앞으로) + empt(꺼내다, 라틴어 emere) → 앞으로 끌어내다, 촉발하다"},{"id":"d10-24","day":10,"word":"elicit","meaning":"~을 초래하다","ipa":"[ɪˈlɪsɪt]","kr":"일리싯","example":"The survey elicited honest responses.","exampleKr":"그 설문조사는 솔직한 응답을 이끌어냈다.","roots":"e-(밖으로) + licit(꾀어내다, 라틴어 lacere) → 밖으로 이끌어내다"},{"id":"d10-25","day":10,"word":"spark","meaning":"~을 초래하다","ipa":"[spɑːrk]","kr":"스파크","example":"The debate sparked new interest in the topic.","exampleKr":"그 토론은 그 주제에 대한 새로운 관심을 촉발했다."},{"id":"d10-26","day":10,"word":"cause","meaning":"~을 초래하다","ipa":"[kɔːz]","kr":"코즈","example":"Heavy rain caused flooding downtown.","exampleKr":"폭우는 시내에 홍수를 초래했다."},{"id":"d10-27","day":10,"word":"later on","meaning":"나중에, 이후에","ipa":"[ˈleɪtər ɑːn]","kr":"레이터 온","example":"We can talk about it later on.","exampleKr":"나중에 그것에 대해 이야기할 수 있다."},{"id":"d10-28","day":10,"word":"presence","meaning":"존재","ipa":"[ˈprezns]","kr":"프레즌스","example":"Her presence calmed the nervous students.","exampleKr":"그녀의 존재는 긴장한 학생들을 진정시켰다.","roots":"pre-(앞에) + sence(있다, 라틴어 esse) → 앞에 있음, 존재"},{"id":"d10-29","day":10,"word":"absence","meaning":"부재","ipa":"[ˈæbsəns]","kr":"앱슨스","example":"The team struggled in his absence.","exampleKr":"그 팀은 그의 부재 속에서 어려움을 겪었다.","roots":"ab-(떨어져) + sence(있다, 라틴어 esse) → 떨어져 있음, 부재"},{"id":"d10-30","day":10,"word":"dissolve","meaning":"용해시키다","ipa":"[dɪˈzɑːlv]","kr":"디잘브","example":"Sugar dissolves quickly in hot water.","exampleKr":"설탕은 뜨거운 물에서 빠르게 용해된다.","roots":"dis-(흩어지게) + solve(풀다, 라틴어 solvere) → 흩어지게 풀어내다, 용해시키다"},{"id":"d10-31","day":10,"word":"resolve","meaning":"용해하다, 결심하다","ipa":"[rɪˈzɑːlv]","kr":"리잘브","example":"They resolved to finish the project by Friday.","exampleKr":"그들은 금요일까지 그 프로젝트를 끝내기로 결심했다.","roots":"re-(다시/완전히) + solve(풀다, 라틴어 solvere) → 완전히 풀어내다, 해결하다/결심하다"},{"id":"d10-32","day":10,"word":"substance","meaning":"물질","ipa":"[ˈsʌbstəns]","kr":"섭스턴스","example":"The bottle contained an unknown substance.","exampleKr":"그 병에는 알 수 없는 물질이 들어 있었다.","roots":"sub-(아래에) + stance(서다, 라틴어 stare) → 아래에서 받쳐 서 있는 것, 본질/물질"},{"id":"d10-33","day":10,"word":"substantial","meaning":"상당한, 중요한","ipa":"[səbˈstænʃl]","kr":"섭스탠셜","example":"They made a substantial investment in research.","exampleKr":"그들은 연구에 상당한 투자를 했다.","roots":"sub-(아래에) + stant(서다, 라틴어 stare) + -ial(형용사형) → 아래서 든든히 받쳐주는, 상당한"},{"id":"d10-34","day":10,"word":"evenly","meaning":"균등하게","ipa":"[ˈiːvənli]","kr":"이븐리","example":"Spread the sauce evenly over the crust.","exampleKr":"소스를 반죽 위에 균등하게 펴라."},{"id":"d10-35","day":10,"word":"typically","meaning":"일반적으로","ipa":"[ˈtɪpɪkli]","kr":"티피클리","example":"Meetings typically start at nine.","exampleKr":"회의는 일반적으로 9시에 시작한다.","roots":"typ(틀, 그리스어 typos) + -ical + -ly → 정해진 틀대로, 일반적으로"},{"id":"d10-36","day":10,"word":"diffuse","meaning":"퍼지다, 흩뜨리다","ipa":"[dɪˈfjuːz]","kr":"디퓨즈","example":"The scent diffused throughout the house.","exampleKr":"그 향기는 집 전체에 퍼졌다.","roots":"dif-(널리) + fuse(붓다, 라틴어 fundere) → 널리 부어 퍼뜨리다"},{"id":"d10-37","day":10,"word":"scatter","meaning":"흩뜨리다","ipa":"[ˈskætər]","kr":"스캐터","example":"The wind scattered the leaves across the yard.","exampleKr":"바람은 나뭇잎을 마당 전체에 흩뜨렸다."},{"id":"d10-38","day":10,"word":"disperse","meaning":"흩뜨리다","ipa":"[dɪˈspɜːrs]","kr":"디스퍼스","example":"Police asked the crowd to disperse.","exampleKr":"경찰은 군중에게 흩어지라고 요청했다.","roots":"dis-(흩어지게) + sperse(뿌리다, 라틴어 spargere) → 흩어지게 뿌리다"},{"id":"d10-39","day":10,"word":"plus","meaning":"게다가","ipa":"[plʌs]","kr":"플러스","example":"The apartment is spacious, plus it has a view.","exampleKr":"그 아파트는 넓고, 게다가 전망도 좋다."},{"id":"d10-40","day":10,"word":"plenty of","meaning":"많은","ipa":"[ˈplenti əv]","kr":"플렌티 오브","example":"There is plenty of time before the flight.","exampleKr":"비행기 전까지 시간이 많다."},{"id":"d10-41","day":10,"word":"float","meaning":"떠다니다, 부유하다","ipa":"[floʊt]","kr":"플로우트","example":"The boat floated calmly on the lake.","exampleKr":"그 배는 호수 위에 잔잔하게 떠다녔다."},{"id":"d10-42","day":10,"word":"photosynthesis","meaning":"광합성","ipa":"[ˌfoʊtoʊˈsɪnθəsɪs]","kr":"포우토신써시스","example":"Plants use photosynthesis to make food.","exampleKr":"식물은 음식을 만들기 위해 광합성을 이용한다.","roots":"photo-(빛, 그리스어 phos) + syn-(함께) + thesis(놓다, 그리스어 tithenai) → 빛으로 함께 만들어냄, 광합성"},{"id":"d10-43","day":10,"word":"concentration","meaning":"농도","ipa":"[ˌkɑːnsnˈtreɪʃn]","kr":"칸선트레이션","example":"The drink has a high sugar concentration.","exampleKr":"그 음료는 높은 설탕 농도를 가지고 있다.","roots":"con-(함께) + centr(중심, 라틴어 centrum) + -ation(명사형) → 중심으로 모여듦, 농도"},{"id":"d10-44","day":10,"word":"refer to","meaning":"~를 말한다","ipa":"[rɪˈfɜːr tuː]","kr":"리퍼 투","example":"This term refers to a specific legal process.","exampleKr":"이 용어는 특정 법적 절차를 말한다."},{"id":"d10-45","day":10,"word":"decay","meaning":"부패하다","ipa":"[dɪˈkeɪ]","kr":"디케이","example":"Tooth decay can be prevented with good hygiene.","exampleKr":"치아 부패는 좋은 위생으로 예방할 수 있다.","roots":"de-(아래로) + cay(떨어지다, 라틴어 cadere) → 아래로 떨어지다, 부패하다"},{"id":"d10-46","day":10,"word":"decompose","meaning":"부패하다","ipa":"[ˌdiːkəmˈpoʊz]","kr":"디컴포우즈","example":"Leaves decompose and enrich the soil.","exampleKr":"나뭇잎은 부패해서 토양을 비옥하게 만든다.","roots":"de-(반대로) + com-(함께) + pose(놓다, 라틴어 ponere) → 합쳐놓은 것을 다시 흩어놓다, 분해하다"},{"id":"d10-47","day":10,"word":"rot","meaning":"부패하다","ipa":"[rɑːt]","kr":"라트","example":"The fruit began to rot in the heat.","exampleKr":"그 과일은 더위 속에서 부패하기 시작했다."},{"id":"d10-48","day":10,"word":"accumulate","meaning":"축적하다","ipa":"[əˈkjuːmjəleɪt]","kr":"어큐뮬레이트","example":"Debt can accumulate quickly without a budget.","exampleKr":"예산 없이는 빚이 빠르게 축적될 수 있다.","roots":"ac-(~쪽으로) + cumul(더미, 라틴어 cumulus) + -ate(동사형) → 더미를 쌓아가다, 축적하다"},{"id":"d10-49","day":10,"word":"beneath","meaning":"아래에","ipa":"[bɪˈniːθ]","kr":"비니쓰","example":"The treasure was buried beneath the old oak tree.","exampleKr":"그 보물은 오래된 참나무 아래에 묻혀 있었다."},{"id":"d10-50","day":10,"word":"content","meaning":"함량, 내용","ipa":"[ˈkɑːntent]","kr":"칸텐트","example":"The sugar content in the drink is high.","exampleKr":"그 음료의 설탕 함량은 높다.","roots":"con-(함께) + tent(담다, 라틴어 tenere) → 함께 담겨 있는 것, 내용/함량"},{"id":"d10-51","day":10,"word":"reflect","meaning":"반영하다","ipa":"[rɪˈflekt]","kr":"리플렉트","example":"Her choices reflect her values.","exampleKr":"그녀의 선택은 그녀의 가치관을 반영한다.","roots":"re-(뒤로) + flect(구부리다, 라틴어 flectere) → 뒤로 구부려 비추다, 반영하다"},{"id":"d10-52","day":10,"word":"origin","meaning":"출처","ipa":"[ˈɔːrɪdʒɪn]","kr":"오리진","example":"The word has Latin origin.","exampleKr":"그 단어는 라틴어 출처를 가지고 있다.","roots":"orig(생기다, 라틴어 oriri) + -in(명사형) → 생겨난 것, 기원"},{"id":"d10-53","day":10,"word":"derive from","meaning":"~에서 나오다","ipa":"[dɪˈraɪv frəm]","kr":"디라이브 프럼","example":"The tradition derives from an old folk tale.","exampleKr":"그 전통은 오래된 민담에서 나온다."},{"id":"d10-54","day":10,"word":"stem from","meaning":"~에서 유래되다","ipa":"[stem frəm]","kr":"스템 프럼","example":"Her fear stems from a childhood accident.","exampleKr":"그녀의 두려움은 어린 시절 사고에서 유래되었다."},{"id":"d10-55","day":10,"word":"arise from","meaning":"~에서 유래되다","ipa":"[əˈraɪz frəm]","kr":"어라이즈 프럼","example":"Conflicts often arise from miscommunication.","exampleKr":"갈등은 종종 의사소통 오류에서 유래된다."},{"id":"d10-56","day":10,"word":"originate from","meaning":"~에서 유래되다","ipa":"[əˈrɪdʒɪneɪt frəm]","kr":"어리지네이트 프럼","example":"The disease originated from contaminated water.","exampleKr":"그 질병은 오염된 물에서 유래되었다."},{"id":"d10-57","day":10,"word":"result from","meaning":"~에서 유래되다","ipa":"[rɪˈzʌlt frəm]","kr":"리절트 프럼","example":"Her success resulted from years of hard work.","exampleKr":"그녀의 성공은 수년간의 노력에서 유래되었다."},{"id":"d10-58","day":10,"word":"spring from","meaning":"~에서 유래되다","ipa":"[sprɪŋ frəm]","kr":"스프링 프럼","example":"Innovation often springs from necessity.","exampleKr":"혁신은 종종 필요성에서 유래된다."},{"id":"d10-59","day":10,"word":"polar","meaning":"극지방의","ipa":"[ˈpoʊlər]","kr":"포울러","example":"Polar bears live in the Arctic.","exampleKr":"북극곰은 북극 지방에 산다.","roots":"pol(축, 라틴어 polus) + -ar(형용사형) → 축에 관한, 극지방의"},{"id":"d10-60","day":10,"word":"thereby","meaning":"따라서","ipa":"[ðerˈbaɪ]","kr":"데어바이","example":"He passed the test, thereby earning his license.","exampleKr":"그는 시험에 합격했고, 따라서 자격증을 얻었다."},{"id":"d10-61","day":10,"word":"whereby","meaning":"그것으로 해서","ipa":"[werˈbaɪ]","kr":"웨어바이","example":"They designed a plan whereby costs are shared.","exampleKr":"그들은 비용이 공유되는 계획을 설계했다."},{"id":"d10-62","day":10,"word":"conserve","meaning":"보존하다","ipa":"[kənˈsɜːrv]","kr":"컨서브","example":"We should conserve water during the drought.","exampleKr":"우리는 가뭄 동안 물을 보존해야 한다.","roots":"con-(완전히) + serve(지키다, 라틴어 servare) → 완전히 지켜내다, 보존하다"},{"id":"d10-63","day":10,"word":"preserve","meaning":"보존하다","ipa":"[prɪˈzɜːrv]","kr":"프리저브","example":"The museum works to preserve historic artifacts.","exampleKr":"그 박물관은 역사적 유물을 보존하기 위해 노력한다.","roots":"pre-(미리) + serve(지키다, 라틴어 servare) → 미리 지켜두다, 보존하다"},{"id":"d10-64","day":10,"word":"reserve","meaning":"보존하다","ipa":"[rɪˈzɜːrv]","kr":"리저브","example":"They reserve a table for special guests.","exampleKr":"그들은 특별 손님을 위해 테이블을 예약해 둔다.","roots":"re-(뒤로) + serve(지키다, 라틴어 servare) → 뒤로 남겨 지켜두다, 보존하다"},{"id":"d10-65","day":10,"word":"as well","meaning":"또한","ipa":"[æz wel]","kr":"애즈 웰","example":"She plays piano and sings as well.","exampleKr":"그녀는 피아노를 치고 또한 노래도 한다."},{"id":"d10-66","day":10,"word":"organism","meaning":"유기체, 생명체","ipa":"[ˈɔːrɡənɪzəm]","kr":"오거니즘","example":"Every organism adapts to its environment.","exampleKr":"모든 유기체는 환경에 적응한다.","roots":"organ(기관, 그리스어 organon) + -ism(명사형) → 기관을 갖춘 것, 유기체"},{"id":"d10-67","day":10,"word":"comparatively","meaning":"비교적","ipa":"[kəmˈpærətɪvli]","kr":"컴패러티블리","example":"The city is comparatively safe at night.","exampleKr":"그 도시는 밤에 비교적 안전하다.","roots":"com-(함께) + par(같은, 라틴어 par) + -ative + -ly → 함께 놓고 견주어, 비교적으로"},{"id":"d10-68","day":10,"word":"scarce","meaning":"드문","ipa":"[skers]","kr":"스케어스","example":"Clean water is scarce in the region.","exampleKr":"그 지역에서는 깨끗한 물이 드물다."},{"id":"d10-69","day":10,"word":"metabolic","meaning":"신진 대사의","ipa":"[ˌmetəˈbɑːlɪk]","kr":"메터발릭","example":"Exercise boosts your metabolic rate.","exampleKr":"운동은 신진대사율을 높인다.","roots":"meta-(변화) + bol(던지다, 그리스어 ballein) + -ic(형용사형) → 형태를 바꿔 던지는, 신진대사의"},{"id":"d10-70","day":10,"word":"available","meaning":"이용가능한","ipa":"[əˈveɪləbl]","kr":"어베일러블","example":"The manager is available for a call.","exampleKr":"그 매니저는 통화가 가능하다.","roots":"a-(강조) + vail(가치있다, 라틴어 valere) + -able(~할 수 있는) → 쓰일 만한 가치가 있는, 이용 가능한"},{"id":"d10-71","day":10,"word":"entrance","meaning":"입학","ipa":"[ˈentrəns]","kr":"엔트런스","example":"Her college entrance exam went well.","exampleKr":"그녀의 대학 입학 시험은 잘 진행됐다.","roots":"en-(안으로) + trance(들어가다, 라틴어 intrare) + -ance(명사형) → 안으로 들어감, 입학/입구"},{"id":"d10-72","day":10,"word":"potential","meaning":"잠재력, 가능성","ipa":"[pəˈtenʃl]","kr":"퍼텐셜","example":"The coach recognized her potential early on.","exampleKr":"코치는 일찍이 그녀의 잠재력을 알아봤다.","roots":"pot(할 수 있는, 라틴어 posse) + -ential(형용사형) → 할 수 있는 상태, 잠재력"},{"id":"d10-73","day":10,"word":"likelihood","meaning":"가능성","ipa":"[ˈlaɪklihʊd]","kr":"라이클리후드","example":"There's a low likelihood of snow tomorrow.","exampleKr":"내일 눈이 올 가능성은 낮다."},{"id":"d10-74","day":10,"word":"chance","meaning":"가능성","ipa":"[tʃæns]","kr":"챈스","example":"He took a chance and applied for the job.","exampleKr":"그는 가능성을 걸고 그 일자리에 지원했다."},{"id":"d10-75","day":10,"word":"odds","meaning":"가능성","ipa":"[ɑːdz]","kr":"아즈","example":"The odds were against them, but they won.","exampleKr":"가능성이 그들에게 불리했지만, 그들은 이겼다."},{"id":"d10-76","day":10,"word":"talented","meaning":"재능 있는","ipa":"[ˈtæləntɪd]","kr":"탤런티드","example":"She is a talented young violinist.","exampleKr":"그녀는 재능 있는 젊은 바이올리니스트다.","roots":"talent(재능, 그리스어 talanton, 원래 저울추/화폐 단위) + -ed → 재능을 가진"},{"id":"d10-77","day":10,"word":"gifted","meaning":"재능 있는","ipa":"[ˈɡɪftɪd]","kr":"기프티드","example":"He was a gifted student in math.","exampleKr":"그는 수학에 재능 있는 학생이었다."},{"id":"d10-78","day":10,"word":"longingly","meaning":"간절히","ipa":"[ˈlɔːŋɪŋli]","kr":"롱잉리","example":"She looked longingly at the empty swing.","exampleKr":"그녀는 빈 그네를 간절히 바라보았다."},{"id":"d10-79","day":10,"word":"capture","meaning":"사로잡다","ipa":"[ˈkæptʃər]","kr":"캡처","example":"The photo captured a perfect moment.","exampleKr":"그 사진은 완벽한 순간을 사로잡았다.","roots":"cap(잡다, 라틴어 capere) + -ture(명사형) → 붙잡은 것, 사로잡다"},{"id":"d10-80","day":10,"word":"greet","meaning":"인사하다","ipa":"[ɡriːt]","kr":"그리트","example":"She greeted the guests with a warm smile.","exampleKr":"그녀는 따뜻한 미소로 손님들을 인사했다."},{"id":"d10-81","day":10,"word":"reject","meaning":"거절하다, 거부하다","ipa":"[rɪˈdʒekt]","kr":"리젝트","example":"The editor rejected the manuscript.","exampleKr":"편집자는 그 원고를 거절했다.","roots":"re-(뒤로) + ject(던지다, 라틴어 jacere) → 뒤로 던져버리다, 거절하다"},{"id":"d10-82","day":10,"word":"turn down","meaning":"거절하다, 거부하다","ipa":"[tɜːrn daʊn]","kr":"턴 다운","example":"He turned down the promotion.","exampleKr":"그는 그 승진을 거절했다."},{"id":"d10-83","day":10,"word":"refuse","meaning":"거절하다, 거부하다","ipa":"[rɪˈfjuːz]","kr":"리퓨즈","example":"She refused to sign the contract.","exampleKr":"그녀는 계약서에 서명하기를 거부했다.","roots":"re-(뒤로) + fuse(붓다, 라틴어 fundere) → 뒤로 쏟아버리다, 거절하다"},{"id":"d10-84","day":10,"word":"deny","meaning":"거절하다, 거부하다","ipa":"[dɪˈnaɪ]","kr":"디나이","example":"The company denied any wrongdoing.","exampleKr":"그 회사는 어떠한 잘못도 부인했다.","roots":"de-(부정) + ny(말하다, 라틴어 negare) → 아니라고 말하다, 부인하다"},{"id":"d10-85","day":10,"word":"decline","meaning":"거절하다, 거부하다","ipa":"[dɪˈklaɪn]","kr":"디클라인","example":"He declined the second helping of dessert.","exampleKr":"그는 디저트를 한 번 더 먹는 것을 거절했다.","roots":"de-(아래로) + cline(기울다, 라틴어 clinare) → 아래로 기울이다, 거절하다"},{"id":"d10-86","day":10,"word":"heartbroken","meaning":"상심한","ipa":"[ˈhɑːrtbroʊkən]","kr":"하트브로우큰","example":"She was heartbroken after the breakup.","exampleKr":"그녀는 이별 후 상심했다."},{"id":"d10-87","day":10,"word":"workshop","meaning":"작업실","ipa":"[ˈwɜːrkʃɑːp]","kr":"워크샵","example":"The artist works in a small workshop.","exampleKr":"그 예술가는 작은 작업실에서 일한다."},{"id":"d10-88","day":10,"word":"sculpture","meaning":"조각","ipa":"[ˈskʌlptʃər]","kr":"스컬프처","example":"The park displays a modern sculpture.","exampleKr":"그 공원은 현대 조각을 전시한다.","roots":"sculp(조각하다, 라틴어 sculpere) + -ture(명사형) → 조각한 것"},{"id":"d10-89","day":10,"word":"puzzled","meaning":"어리둥절한","ipa":"[ˈpʌzld]","kr":"퍼즐드","example":"He looked puzzled by the question.","exampleKr":"그는 그 질문에 어리둥절해 보였다."},{"id":"d10-90","day":10,"word":"trouser","meaning":"바지의","ipa":"[ˈtraʊzər]","kr":"트라우저","example":"He wore a neat trouser suit to the interview.","exampleKr":"그는 면접에 단정한 바지 정장을 입었다."},{"id":"d10-91","day":10,"word":"artificial","meaning":"인공적인","ipa":"[ˌɑːrtɪˈfɪʃl]","kr":"아티피셜","example":"The lake has an artificial waterfall.","exampleKr":"그 호수에는 인공 폭포가 있다.","roots":"art(기술, 라틴어 ars) + i + fic(만들다, 라틴어 facere) + -ial(형용사형) → 기술로 만들어낸, 인공적인"},{"id":"d10-92","day":10,"word":"limb","meaning":"다리","ipa":"[lɪm]","kr":"림","example":"He lost a limb in the accident.","exampleKr":"그는 그 사고로 팔다리를 잃었다."},{"id":"d10-93","day":10,"word":"realize","meaning":"이루다, 실현하다","ipa":"[ˈriːəlaɪz]","kr":"리얼라이즈","example":"She realized her dream of becoming a doctor.","exampleKr":"그녀는 의사가 되겠다는 꿈을 이뤘다.","roots":"real(실제의, 라틴어 res) + -ize(동사형) → 실제로 만들다, 실현하다"},{"id":"d10-94","day":10,"word":"exhibition","meaning":"전시회","ipa":"[ˌeksɪˈbɪʃn]","kr":"엑서비션","example":"The gallery held a photography exhibition.","exampleKr":"그 갤러리는 사진 전시회를 열었다.","roots":"ex-(밖으로) + hib(가지다, 라틴어 habere) + -ition(명사형) → 밖으로 내보여 가짐, 전시"},{"id":"d10-95","day":10,"word":"sculptor","meaning":"조각가","ipa":"[ˈskʌlptər]","kr":"스컬프터","example":"The sculptor spent years on the statue.","exampleKr":"그 조각가는 그 조각상에 수년을 보냈다.","roots":"sculp(조각하다, 라틴어 sculpere) + -tor(행위자 명사형) → 조각하는 사람"},{"id":"d10-96","day":10,"word":"attend","meaning":"참석하다, 주의하다","ipa":"[əˈtend]","kr":"어텐드","example":"Everyone was invited to attend the ceremony.","exampleKr":"모두가 그 행사에 참석하도록 초대받았다.","roots":"at-(~쪽으로) + tend(뻗다, 라틴어 tendere) → 마음을 그쪽으로 뻗다, 참석하다/주의를 기울이다"},{"id":"d10-97","day":10,"word":"attendance","meaning":"참석","ipa":"[əˈtendəns]","kr":"어텐던스","example":"Attendance at the meeting was mandatory.","exampleKr":"그 회의 참석은 필수였다.","roots":"at-(~쪽으로) + tend(뻗다, 라틴어 tendere) + -ance(명사형) → 마음을 뻗어 참여함, 참석"},{"id":"d10-98","day":10,"word":"attention","meaning":"주의, 관심","ipa":"[əˈtenʃn]","kr":"어텐션","example":"The teacher demanded the students' attention.","exampleKr":"선생님은 학생들의 주의를 요구했다.","roots":"at-(~쪽으로) + tent(뻗다, 라틴어 tendere) + -ion(명사형) → 마음을 뻗침, 주의"},{"id":"d10-99","day":10,"word":"inspiration","meaning":"영감","ipa":"[ˌɪnspəˈreɪʃn]","kr":"인스퍼레이션","example":"Her grandmother was her biggest inspiration.","exampleKr":"그녀의 할머니는 그녀의 가장 큰 영감이었다.","roots":"in-(안으로) + spir(숨쉬다, 라틴어 spirare) + -ation(명사형) → 안으로 숨을 불어넣음, 영감"},{"id":"d10-100","day":10,"word":"perspiration","meaning":"땀, 노력","ipa":"[ˌpɜːrspəˈreɪʃn]","kr":"퍼스퍼레이션","example":"Success takes both inspiration and perspiration.","exampleKr":"성공은 영감과 노력 둘 다 필요로 한다.","roots":"per-(통하여) + spir(숨쉬다, 라틴어 spirare) + -ation(명사형) → 온몸으로 숨을 내쉼, 땀"}];

export const WORDS_BY_ID = Object.fromEntries(WORDS.map((w) => [w.id, w]));
